INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20716, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20716, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "推翻旧制度，推动社会或事物发生根本变化的行动。", "primary_collocate": null, "pronunciation": "gé mìng", "ipa": "kɤ˧˥ miŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这场革命改变了国家。", "target_word": "革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百多年前，中国发生了一场大革命。", "target_word": "革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生都在为革命工作。", "target_word": "革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑带来了一场生活革命。", "target_word": "革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "革命需要很多人的努力。", "target_word": "革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们年轻时参加过革命。", "target_word": "革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课堂上讲解了革命的理论。", "target_word": "革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "革命成功以后，人们过上了好日子。", "target_word": "革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想做一场技术革命。", "target_word": "革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常说起革命年代的生活。", "target_word": "革命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "革命家", "label": "复合词"}, {"form": "革命者", "label": "复合词"}], "register": "中性", "sense_fingerprint": "推翻旧制度、推动社会或事物发生根本变化的行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578a203d-4358-4a88-a532-6eee781a844a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20716, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "革命", "is_correct": true, "explanation": "正确：“革命”指推翻旧制度的根本变革，与“这场……改变了国家”相符。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不能改变国家，“这场……改变了国家”说的是重大的社会变化。"}, {"text": "小说", "is_correct": false, "explanation": "量词“场”不搭配“小说”，应说“部”；“这场小说”不成立，与“这场……改变了国家”的语境不合。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是一个地方，不会改变国家，与“这场……”指重大事件的语境不合。"}], "explanations": {"革命": "正确：“革命”指推翻旧制度的根本变革，与“这场……改变了国家”相符。", "面包": "语义：面包不能改变国家，“这场……改变了国家”说的是重大的社会变化。", "小说": "量词“场”不搭配“小说”，应说“部”；“这场小说”不成立，与“这场……改变了国家”的语境不合。", "花园": "语义：花园是一个地方，不会改变国家，与“这场……”指重大事件的语境不合。"}, "sentence_index": 0, "correct_answer": "革命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天革命了一件衬衫。", "explanation": "这里应该用〈换〉。“革命”指社会或制度的根本变革，不能用于衣物；换衣服要说“换”。"}, {"text": "爱迪生革命了电灯。", "explanation": "这里应该用〈发明〉。“革命”指社会或制度的根本变革，不用来说创造新物品；造出新东西要说“发明”。"}, {"text": "他参加了一只革命。", "explanation": "这里应该用〈场〉。“革命”是大事件，计量时要用“场”，“只”多用于动物或单个器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "革命", "is_correct": true, "explanation": "正确：“讲解了革命的理论”中“革命的理论”是固定说法，能正确填入空格。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不能作“理论”的修饰语，“讲解了作业的理论”不通。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭是日常饮食，不是可以讲解的理论，“讲解了午饭的理论”不通。"}, {"text": "雨衣", "is_correct": false, "explanation": "语义：雨衣是衣物，不能作为“理论”的内容，与语境不合。"}], "explanations": {"革命": "正确：“讲解了革命的理论”中“革命的理论”是固定说法，能正确填入空格。", "作业": "搭配：“作业”不能作“理论”的修饰语，“讲解了作业的理论”不通。", "午饭": "语义：午饭是日常饮食，不是可以讲解的理论，“讲解了午饭的理论”不通。", "雨衣": "语义：雨衣是衣物，不能作为“理论”的内容，与语境不合。"}, "sentence_index": 6, "correct_answer": "革命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司决定革命产品设计。", "explanation": "这里应该用〈革新〉。“革命”指根本性的社会或制度变革，不用于一般产品设计的改进；改进产品设计要说“革新”。"}, {"text": "我们需要革命生产效率。", "explanation": "这里应该用〈提高〉。“革命”不表示提升数量或效率，应说“提高生产效率”。"}, {"text": "这个节目每周播一集革命。", "explanation": "这里应该用〈场〉。“革命”计量时要用“场”，“集”多用于电视节目的单元。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只革命让很多农民有了土地。", "corrected_sentence": "那场革命让很多农民有了土地。", "error_description": "“革命”是一件大事，计量时应用量词“场”，不能用“只”。把“那场革命”说成“那只革命”是量词错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一条革命成功以后，城市的生活变好了。", "corrected_sentence": "一场革命成功以后，城市的生活变好了。", "error_description": "量词错误：“革命”是一件大事，计量时应用量词“场”，不能用“条”。正确说法：一场革命成功以后，城市的生活变好了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
