INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个专门的范围。", "primary_collocate": null, "pronunciation": "lǐng yù", "ipa": "liŋ˨˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "他在科学领域很有名。", "target_word": "领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医学是我最喜欢的领域。", "target_word": "领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个领域需要很多新人。", "target_word": "领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在音乐领域工作了十年。", "target_word": "领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教育领域最近有新变化。", "target_word": "领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是电脑领域的专家。", "target_word": "领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体育领域有很多好老师。", "target_word": "领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想去哪个领域工作？", "target_word": "领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个领域差别很大。", "target_word": "领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在艺术领域，她得过很多奖。", "target_word": "领域", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "領域", "label": "繁体"}], "register": "书面", "sense_fingerprint": "学术、工作或活动的专门范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662c7823-51e1-46b7-b4e3-759c04a652e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20718, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饭馆", "is_correct": false, "explanation": "语义：“饭馆”是供人吃饭的地方，与学术或工作的专门范围无关，“在科学饭馆很有名”说不通。"}, {"text": "领域", "is_correct": true, "explanation": "“领域”指专门的范围，“在科学领域”搭配自然，且与“很有名”的语境相符。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是挡雨的用具，不是专门的范围，“在科学雨伞很有名”说不通。"}, {"text": "市场", "is_correct": false, "explanation": "语义：“市场”指买卖交易的场所，与“科学”和“很有名”都不相符。"}], "explanations": {"饭馆": "语义：“饭馆”是供人吃饭的地方，与学术或工作的专门范围无关，“在科学饭馆很有名”说不通。", "领域": "“领域”指专门的范围，“在科学领域”搭配自然，且与“很有名”的语境相符。", "雨伞": "语义：“雨伞”是挡雨的用具，不是专门的范围，“在科学雨伞很有名”说不通。", "市场": "语义：“市场”指买卖交易的场所，与“科学”和“很有名”都不相符。"}, "sentence_index": 0, "correct_answer": "领域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在身体领域要多注意。", "explanation": "这里应该用〈方面〉。领域指专门的学术或工作范围，“身体方面”这类泛指的方面要用“方面”。"}, {"text": "他的领域有一米八。", "explanation": "这里应该用〈身高〉。领域指专门的范围，人的高矮要用“身高”。"}, {"text": "他的领域有三十公斤。", "explanation": "这里应该用〈体重〉。领域指专门的范围，人的轻重要用“体重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是做饭的地方，与体育和“好老师”都无关。"}, {"text": "领域", "is_correct": true, "explanation": "“领域”指专门的范围，“体育领域”搭配自然，且与句子语境相符。"}, {"text": "车站", "is_correct": false, "explanation": "搭配：“体育车站”不成词组，车站是交通场所，不能用来修饰“体育”。"}, {"text": "银行", "is_correct": false, "explanation": "语义：“银行”是金融机构，“体育银行”与“有很多好老师”说不通。"}], "explanations": {"厨房": "语义：“厨房”是做饭的地方，与体育和“好老师”都无关。", "领域": "“领域”指专门的范围，“体育领域”搭配自然，且与句子语境相符。", "车站": "搭配：“体育车站”不成词组，车站是交通场所，不能用来修饰“体育”。", "银行": "语义：“银行”是金融机构，“体育银行”与“有很多好老师”说不通。"}, "sentence_index": 6, "correct_answer": "领域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的领域要两个小时。", "explanation": "这里应该用〈时间〉。领域指专门的范围，考试持续多久要用“时间”。"}, {"text": "这本书的领域是五十块钱。", "explanation": "这里应该用〈价格〉。领域指专门的范围，书的售价要用“价格”。"}, {"text": "他的领域是医生。", "explanation": "这里应该用〈职业〉。领域指专门的范围，说明一个人的工作身份要用“职业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我对这只领域很感兴趣。", "corrected_sentence": "我对这个领域很感兴趣。", "error_description": "量词错误：“领域”是抽象名词，量词应用“个”，不用“只”（“只”多用于动物等）。正确说法：这个领域。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他毕业后进入了体育领域们。", "corrected_sentence": "他毕业后进入了体育领域。", "error_description": "词缀错误：“领域”是非人名词，不能加复数词尾“们”，应说“体育领域”。正确说法：体育领域。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
