INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20720, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西一点一点加起来。", "primary_collocate": null, "pronunciation": "jī lěi", "ipa": "tɕi˥ leɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "学汉语要一点一点积累词语。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工作中积累了很多经验。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天积累几个新词。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就积累了不少知识。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱要慢慢积累，不能着急。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书，才能积累知识。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司积累了二十年的经验。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多听多说，才能积累语言经验。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在积累写作的材料。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把读过的好句子都积累起来。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "积累了", "label": "体标"}, {"form": "积累着", "label": "体标"}, {"form": "积累过", "label": "体标"}, {"form": "積累", "label": "繁体"}], "register": "中性", "sense_fingerprint": "经验、知识、财富等一点一点地聚集起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578a203d-4358-4a88-a532-6eee781a844a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20720, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "积累", "is_correct": true, "explanation": "正确答案：积累 jī lěi，指经验、知识等一点一点聚集起来。"}, {"text": "机理", "is_correct": false, "explanation": "lǐ 与 lěi 韵母不同（少一个 e），意思是事物内在的道理、机制。"}, {"text": "几类", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，lèi 与 lěi 声调也不同，意思是几种类别。"}, {"text": "极累", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，意思是非常疲劳。"}], "explanations": {"积累": "正确答案：积累 jī lěi，指经验、知识等一点一点聚集起来。", "机理": "lǐ 与 lěi 韵母不同（少一个 e），意思是事物内在的道理、机制。", "几类": "jǐ（第三声）与 jī（第一声）声调不同，lèi 与 lěi 声调也不同，意思是几种类别。", "极累": "jí（第二声）与 jī（第一声）声调不同，意思是非常疲劳。"}, "sentence_index": null, "correct_answer": "积累"}, "level_3": {"options": [{"text": "积累", "is_correct": true, "explanation": "“积累词语”指词语一点一点地聚集起来，与“一点一点”相符。"}, {"text": "拍摄", "is_correct": false, "explanation": "语义：“拍摄”指用镜头记录影像，不能用于“词语”。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”的对象是植物或土地，不能说“浇灌词语”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或物品表面，不能用于“词语”。"}], "explanations": {"积累": "“积累词语”指词语一点一点地聚集起来，与“一点一点”相符。", "拍摄": "语义：“拍摄”指用镜头记录影像，不能用于“词语”。", "浇灌": "搭配：“浇灌”的对象是植物或土地，不能说“浇灌词语”。", "打扫": "搭配：“打扫”的对象是场所或物品表面，不能用于“词语”。"}, "sentence_index": 0, "correct_answer": "积累"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年这个城市的人口积累了十万。", "explanation": "这里应该用〈增加〉。积累指经验、知识、财富等逐渐聚集，人口数量的变化要用“增加”。"}, {"text": "他昨天积累了一场车祸。", "explanation": "这里应该用〈经历〉。积累指一点点聚集，车祸是突发的一次事件，不能说“积累”，要说“经历”。"}, {"text": "他上周积累了一支钢笔。", "explanation": "这里应该用〈买〉。积累指一点点聚集，买一支钢笔是一次性的行为，不能说“积累”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "积累", "is_correct": true, "explanation": "“积累了二十年的经验”指经验逐年聚集，能正确填入空格。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，不能说“喝了二十年的经验”。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复器物，与“经验”不搭。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是表面，不能说“擦了二十年的经验”。"}], "explanations": {"积累": "“积累了二十年的经验”指经验逐年聚集，能正确填入空格。", "喝": "搭配：“喝”的对象是液体，不能说“喝了二十年的经验”。", "修理": "语义：“修理”指修复器物，与“经验”不搭。", "擦": "搭配：“擦”的对象是表面，不能说“擦了二十年的经验”。"}, "sentence_index": 6, "correct_answer": "积累"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他积累了一封信。", "explanation": "这里应该用〈写〉。积累指一点点聚集，不能用来说“写一封信”。"}, {"text": "他积累了一场比赛。", "explanation": "这里应该用〈参加〉。积累指一点点聚集，比赛是一次性的活动，不能说“积累”，要说“参加”。"}, {"text": "政府积累了一座大桥。", "explanation": "这里应该用〈建〉。积累指一点点聚集，大桥要建造，不能说“积累”，要说“建”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这几年积累的了很多经验。", "corrected_sentence": "他这几年积累了很多经验。", "error_description": "错误形式：“积累的了很多经验”；正确形式：“积累了很多经验”。“的”是结构助词，不能插在动词“积累”和体标“了”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想积累了一些经验。", "corrected_sentence": "我想积累一些经验。", "error_description": "体标错误：“想”后面不能直接接“了”表示完成。正确说法：我想积累一些经验。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20722, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "集体", "is_correct": true, "explanation": "正确。“集体”与“个体”相对，指多个人组成的整体。"}, {"text": "森林", "is_correct": false, "explanation": "与“个体”没有反义关系，只是一种自然景物。"}, {"text": "河流", "is_correct": false, "explanation": "与“个体”没有反义关系，只是一种自然景物。"}, {"text": "桌子", "is_correct": false, "explanation": "与“个体”没有反义关系，只是一件家具。"}], "correct_answer": "集体", "explanations": {"集体": "正确。“集体”与“个体”相对，指多个人组成的整体。", "森林": "与“个体”没有反义关系，只是一种自然景物。", "河流": "与“个体”没有反义关系，只是一种自然景物。", "桌子": "与“个体”没有反义关系，只是一件家具。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20722, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "集体", "is_correct": true, "explanation": "正确。“集体”与“个体”相对，指多个人组成的整体。"}, {"text": "老虎", "is_correct": false, "explanation": "与“个体”没有反义关系，只是一种动物。"}, {"text": "天空", "is_correct": false, "explanation": "与“个体”没有反义关系，只是一种自然景象。"}, {"text": "书包", "is_correct": false, "explanation": "与“个体”没有反义关系，只是一件用品。"}], "correct_answer": "集体", "explanations": {"集体": "正确。“集体”与“个体”相对，指多个人组成的整体。", "老虎": "与“个体”没有反义关系，只是一种动物。", "天空": "与“个体”没有反义关系，只是一种自然景象。", "书包": "与“个体”没有反义关系，只是一件用品。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20722, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人或事物，是一个单独的、不是多个的。", "primary_collocate": null, "pronunciation": "gè tǐ", "ipa": "kɤ˥˩ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "每个个体都有自己的想法。", "target_word": "个体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会是由许多个体组成的。", "target_word": "个体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个实验里，每只小鸟都是一个个体。", "target_word": "个体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个体和集体都很重要。", "target_word": "个体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，每个个体的身体情况都不同。", "target_word": "个体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想当集体的一部分，只想做一个自由的个体。", "target_word": "个体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究这些动物时，我们先看一个个体。", "target_word": "个体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个个体的差别很小，所以要多看一些。", "target_word": "个体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望我们尊重每一个个体。", "target_word": "个体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司很重视员工个体的发展。", "target_word": "个体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "个体户", "label": "复合"}, {"form": "個體", "label": "繁体"}], "register": "正式", "sense_fingerprint": "整体或群体中单独的一个人或事物，与集体、整体相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f562dea-1484-4d6c-8f48-09986f773a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20722, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "个体", "is_correct": true, "explanation": "正确。“个体”指单独的个人或事物，可以有自己的想法。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有想法，与句中“自己的想法”不符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会有想法，与句中“自己的想法”不符。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”是不可数名词，不能与“每个”搭配。"}], "explanations": {"个体": "正确。“个体”指单独的个人或事物，可以有自己的想法。", "石头": "语义：石头没有想法，与句中“自己的想法”不符。", "桌子": "语义：桌子不会有想法，与句中“自己的想法”不符。", "空气": "搭配：“空气”是不可数名词，不能与“每个”搭配。"}, "sentence_index": 0, "correct_answer": "个体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请填写你的个体信息。", "explanation": "这里应该用〈个人〉。“个人信息”是固定说法，“个体”指单独的个人或事物，不用于填写个人信息。"}, {"text": "这个数学题的个体很难。", "explanation": "这里应该用〈难度〉。“个体”指单独的人或事物，不能作为题目难易的主语。"}, {"text": "这块蛋糕的个体很甜。", "explanation": "这里应该用〈味道〉。甜不甜说的是味道，“个体”指单独的个人或事物，不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "个体", "is_correct": true, "explanation": "正确。“一个个体”指一只单独的动物，与“研究这些动物”相合。"}, {"text": "气味", "is_correct": false, "explanation": "语义：“气味”要用鼻子闻，不能用“看”作宾语。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”不搭配“声音”，声音不能被看见。"}, {"text": "墙壁", "is_correct": false, "explanation": "搭配：“墙壁”通常用“一面”计量，且与研究动物无关。"}], "explanations": {"个体": "正确。“一个个体”指一只单独的动物，与“研究这些动物”相合。", "气味": "语义：“气味”要用鼻子闻，不能用“看”作宾语。", "声音": "搭配：“看”不搭配“声音”，声音不能被看见。", "墙壁": "搭配：“墙壁”通常用“一面”计量，且与研究动物无关。"}, "sentence_index": 6, "correct_answer": "个体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的个体很大。", "explanation": "这里应该用〈规模〉。“个体”指单独的个人或事物，不能用来说公司的大小。"}, {"text": "这家公司的个体开了三天会议。", "explanation": "这里应该用〈部门〉。“个体”指单独的个人或事物，不能作为开会的主体。"}, {"text": "这家公司的个体下了三天的雨。", "explanation": "这里应该用〈天气〉。下雨的主语是天气，“个体”指单独的个人或事物，不能作下雨的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究人员记录了每一本个体的体重。", "corrected_sentence": "研究人员记录了每一只个体的体重。", "error_description": "量词错误：“本”用于书籍等物品，指动物个体应用“只”。正确：“每一只个体的体重”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个数据记录了每个个体们的变化。", "corrected_sentence": "这个数据记录了每个个体的变化。", "error_description": "加“们”错误：“每个”已表示单个，“个体”后不能再加“们”。正确：“每个个体的变化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
