INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20726, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "说大话，把小的说成大的。", "primary_collocate": null, "pronunciation": "kuā zhāng", "ipa": "[kʰua˥ ʈʂɑŋ˥]", "syllable_count": 2, "sentences": [{"text": "他说话总是很夸张，说一顿能吃十碗饭。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明夸张地说他昨天看到了一只恐龙。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他夸张地说，自己一个人扛走了一座山。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别说得那么夸张，哪有这么多人？", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲故事时总爱夸张。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟夸张地说，他等了一百年。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样说太夸张了，没那么严重。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位朋友的话听上去很夸张。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把小事说得很夸张，让人担心。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个渔夫说，那条鱼有两米长，话说得很夸张。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "夸张地", "label": "状语形式"}, {"form": "夸张手法", "label": "复合词"}], "register": "中性", "sense_fingerprint": "说大话，把小的说成大的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b713ff2c-e8ec-4a37-94c3-89752342a172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夸张", "is_correct": true, "explanation": "正确：“很夸张”指说话言过其实，与“吃十碗饭”的夸大说法吻合。"}, {"text": "精确", "is_correct": false, "explanation": "语义：“精确”指准确，与“吃十碗饭”的夸大说法冲突。"}, {"text": "文雅", "is_correct": false, "explanation": "语域：“文雅”指斯文，与这种夸大的口吻不合。"}, {"text": "含蓄", "is_correct": false, "explanation": "语义：“含蓄”指委婉，与“吃十碗饭”的直白夸大冲突。"}], "explanations": {"夸张": "正确：“很夸张”指说话言过其实，与“吃十碗饭”的夸大说法吻合。", "精确": "语义：“精确”指准确，与“吃十碗饭”的夸大说法冲突。", "文雅": "语域：“文雅”指斯文，与这种夸大的口吻不合。", "含蓄": "语义：“含蓄”指委婉，与“吃十碗饭”的直白夸大冲突。"}, "sentence_index": 0, "correct_answer": "夸张"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的体重夸张了五斤。", "explanation": "这里应该用〈增加〉。夸张指说大话、把小的说成大的，不表示体重增加；应说“体重增加了五斤”。"}, {"text": "他把房间夸张了一半。", "explanation": "这里应该用〈缩小〉。夸张不表示空间缩小，应说“把房间缩小了一半”。"}, {"text": "他的存款夸张了一半。", "explanation": "这里应该用〈减少〉。夸张不表示金额下降，应说“存款减少了一半”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夸张", "is_correct": true, "explanation": "正确：“太夸张了”指说得过分，与“没那么严重”的语境相合。"}, {"text": "精彩", "is_correct": false, "explanation": "语义：“精彩”是褒义，与“没那么严重”的劝慰语境不合。"}, {"text": "圆满", "is_correct": false, "explanation": "语义：“圆满”指完美收场，与“没那么严重”的语境不合。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”多用于排列、动作，不用来形容说法。"}], "explanations": {"夸张": "正确：“太夸张了”指说得过分，与“没那么严重”的语境相合。", "精彩": "语义：“精彩”是褒义，与“没那么严重”的劝慰语境不合。", "圆满": "语义：“圆满”指完美收场，与“没那么严重”的语境不合。", "整齐": "搭配：“整齐”多用于排列、动作，不用来形容说法。"}, "sentence_index": 6, "correct_answer": "夸张"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司把成本夸张了一半。", "explanation": "这里应该用〈缩减〉。夸张不表示成本减少，应说“把成本缩减了一半”。"}, {"text": "比赛夸张了三天。", "explanation": "这里应该用〈推迟〉。夸张不表示日期的改变，应说“比赛推迟了三天”。"}, {"text": "这场讲座夸张了一个小时。", "explanation": "这里应该用〈缩短〉。夸张不表示时长减少，应说“讲座缩短了一个小时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他讲话太夸张地了。", "corrected_sentence": "他讲话太夸张了。", "error_description": "错误：“夸张”后多加了“地”。“地”只修饰动词，“太夸张了”中不能加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把小事说很夸张。", "corrected_sentence": "他把小事说得很夸张。", "error_description": "错误：缺少“得”。动词“说”后接程度补语“很夸张”时，必须用“得”连接，应说“说得很夸张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
