INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20730, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "照顾花草树木，让它们长得更好。", "primary_collocate": null, "pronunciation": "yuán yì", "ipa": "ɥɛn˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "爸爸退休后很喜欢园艺。", "target_word": "园艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她周末在花园里做园艺。", "target_word": "园艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "园艺需要耐心，花草才能长好。", "target_word": "园艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对园艺很有兴趣，种了很多花。", "target_word": "园艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学园艺可以让你知道怎么照顾树。", "target_word": "园艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷做了一辈子园艺，什么花都会种。", "target_word": "园艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "园艺让他的心情平静下来。", "target_word": "园艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书店买了一本关于园艺的书。", "target_word": "园艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做园艺的人每天要给花浇水。", "target_word": "园艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对园艺一点也不懂，养的花总是死掉。", "target_word": "园艺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "园艺师", "label": "复合"}, {"form": "園藝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "种植和照顾花草树木的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245410d8-ef7c-4e0b-b864-35d4e472cd06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20730, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "园艺", "is_correct": true, "explanation": "“喜欢园艺”指把照顾花草当作爱好，与退休后的兴趣相符。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行不是可以喜欢的爱好对象，“喜欢银行”说不通。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂不是爱好的对象，与退休后的生活不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是爱好的对象，“喜欢冰箱”说不通。"}], "explanations": {"园艺": "“喜欢园艺”指把照顾花草当作爱好，与退休后的兴趣相符。", "银行": "语义：银行不是可以喜欢的爱好对象，“喜欢银行”说不通。", "工厂": "语义：工厂不是爱好的对象，与退休后的生活不符。", "冰箱": "语义：冰箱不是爱好的对象，“喜欢冰箱”说不通。"}, "sentence_index": 0, "correct_answer": "园艺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民在田里园艺水稻，收成很好。", "explanation": "这里应该用〈种植〉。园艺指照顾花草树木，大田作物的种植要用“种植”。"}, {"text": "周末我们一起去园艺散步。", "explanation": "这里应该用〈公园〉。园艺指照顾花草树木的活动，不是可以散步的地方。"}, {"text": "渔民在湖里园艺鱼，每年都有收获。", "explanation": "这里应该用〈养殖〉。园艺指照顾花草树木，养鱼等水产要用“养殖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20730, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "园艺", "is_correct": true, "explanation": "“园艺”是一种能让人心情平静的活动，句意通顺。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：蚊子不能让人心情平静，“蚊子让他的心情平静下来”说不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟通常让人紧张，不能让心情平静下来。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高与心情无关，“身高让他的心情平静下来”不通。"}], "explanations": {"园艺": "“园艺”是一种能让人心情平静的活动，句意通顺。", "蚊子": "语义：蚊子不能让人心情平静，“蚊子让他的心情平静下来”说不通。", "闹钟": "语义：闹钟通常让人紧张，不能让心情平静下来。", "身高": "体貌：身高与心情无关，“身高让他的心情平静下来”不通。"}, "sentence_index": 6, "correct_answer": "园艺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市政府每年都会园艺街道，种上很多树。", "explanation": "这里应该用〈绿化〉。园艺指照顾植物的活动，让街道变绿要用“绿化”。"}, {"text": "工人在工地上园艺树木，准备盖楼。", "explanation": "这里应该用〈栽种〉。园艺指照顾花草的活动，工地上种树要用“栽种”。"}, {"text": "居民们一起园艺小区的环境。", "explanation": "这里应该用〈美化〉。园艺指照顾植物，改善环境的整体面貌要用“美化”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我对园艺的很感兴趣。", "corrected_sentence": "我对园艺很感兴趣。", "error_description": "“的”多余：“园艺”后面不加“的”，应说“对园艺很感兴趣”，不能说“对园艺的很感兴趣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他向园艺很感兴趣。", "corrected_sentence": "他对园艺很感兴趣。", "error_description": "介词错误：“对……感兴趣”要用介词“对”，不能用“向”，应说“对园艺很感兴趣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
