INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20732, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "盒子是一个东西，可以把别的东西放进去。", "primary_collocate": null, "pronunciation": "hé zi", "ipa": "xɤ˧˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "桌子上有一个红盒子。", "target_word": "盒子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把礼物放进盒子里。", "target_word": "盒子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子是用纸做的。", "target_word": "盒子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请打开盒子看一看。", "target_word": "盒子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子太小，放不下这本书。", "target_word": "盒子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把饼干装在铁盒子里。", "target_word": "盒子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子里有三支笔。", "target_word": "盒子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一个漂亮的盒子。", "target_word": "盒子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把玩具收进盒子。", "target_word": "盒子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她关上盒子，放到床下。", "target_word": "盒子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个盒子", "label": "量词"}, {"form": "纸盒子", "label": "复合"}, {"form": "铁盒子", "label": "复合"}], "register": "口语", "sense_fingerprint": "可以装东西的带盖容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e21988-a24b-41f5-92fd-a20a131657a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20732, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盒子", "is_correct": true, "explanation": "盒子：可以把别的东西放进去的带盖容器，即本词条的意思。"}, {"text": "胡子", "is_correct": false, "explanation": "hú（第二声）与 hé（第二声）韵母不同（u／e），意思是胡须。"}, {"text": "孩子", "is_correct": false, "explanation": "hái（第二声）与 hé（第二声）韵母不同（ái／é），意思是小孩。"}, {"text": "鞋子", "is_correct": false, "explanation": "xié（第二声）与 hé（第二声）声母不同（x／h），又多一个 i 介音，意思是鞋。"}], "explanations": {"盒子": "盒子：可以把别的东西放进去的带盖容器，即本词条的意思。", "胡子": "hú（第二声）与 hé（第二声）韵母不同（u／e），意思是胡须。", "孩子": "hái（第二声）与 hé（第二声）韵母不同（ái／é），意思是小孩。", "鞋子": "xié（第二声）与 hé（第二声）声母不同（x／h），又多一个 i 介音，意思是鞋。"}, "sentence_index": null, "correct_answer": "盒子"}, "level_3": {"options": [{"text": "盒子", "is_correct": true, "explanation": "盒子：可以装东西的带盖容器，能放在桌上，与句意相符。"}, {"text": "树", "is_correct": false, "explanation": "搭配：树用“棵”计数，不说“一个红树”；树也放不到桌子上。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：墙用“堵”或“面”计数，“一个红墙”不成立，且墙不能放在桌面上。"}, {"text": "森林", "is_correct": false, "explanation": "语义：森林体积巨大，不能放在桌子上。"}], "explanations": {"盒子": "盒子：可以装东西的带盖容器，能放在桌上，与句意相符。", "树": "搭配：树用“棵”计数，不说“一个红树”；树也放不到桌子上。", "墙": "搭配：墙用“堵”或“面”计数，“一个红墙”不成立，且墙不能放在桌面上。", "森林": "语义：森林体积巨大，不能放在桌子上。"}, "sentence_index": 0, "correct_answer": "盒子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一把盒子，准备装饼干。", "explanation": "这里应该用〈个〉。“把”多用于有柄的东西，如伞、椅子、刀；盒子应说“一个盒子”。"}, {"text": "妈妈给我一条盒子，让我装书。", "explanation": "这里应该用〈个〉。“条”多用于细长的东西，如裤子、河流；盒子应说“一个盒子”。"}, {"text": "我在柜台上看到一支盒子。", "explanation": "这里应该用〈个〉。“支”多用于笔、蜡烛等细长的东西；盒子应说“一个盒子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20732, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "盒子", "is_correct": true, "explanation": "盒子：可以把别的东西放进去的带盖容器，即本词条的意思。"}, {"text": "格子", "is_correct": false, "explanation": "gé（第二声）与 hé（第二声）声母不同（g／h），意思是方格。"}, {"text": "猴子", "is_correct": false, "explanation": "hóu（第二声）与 hé（第二声）韵母不同（ou／e），意思是一种动物。"}, {"text": "个子", "is_correct": false, "explanation": "gè（第四声）与 hé（第二声）声母和声调都不同（g／h，第四声／第二声），意思是身高。"}], "explanations": {"盒子": "盒子：可以把别的东西放进去的带盖容器，即本词条的意思。", "格子": "gé（第二声）与 hé（第二声）声母不同（g／h），意思是方格。", "猴子": "hóu（第二声）与 hé（第二声）韵母不同（ou／e），意思是一种动物。", "个子": "gè（第四声）与 hé（第二声）声母和声调都不同（g／h，第四声／第二声），意思是身高。"}, "sentence_index": null, "correct_answer": "盒子"}, "level_3": {"options": [{"text": "盒子", "is_correct": true, "explanation": "盒子：可以装东西的带盖容器，能装下笔，与句意相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能用来装笔，“天空里有三支笔”不成立。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是可以装东西的地方，与“里有三支笔”的说法矛盾。"}, {"text": "穹苍", "is_correct": false, "explanation": "语域：“穹苍”是书面语，口语句中不用；且天空一类的地方也装不下笔。"}], "explanations": {"盒子": "盒子：可以装东西的带盖容器，能装下笔，与句意相符。", "天空": "语义：天空不能用来装笔，“天空里有三支笔”不成立。", "月亮": "语义：月亮不是可以装东西的地方，与“里有三支笔”的说法矛盾。", "穹苍": "语域：“穹苍”是书面语，口语句中不用；且天空一类的地方也装不下笔。"}, "sentence_index": 6, "correct_answer": "盒子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用盒子喝了一杯水。", "explanation": "这里应该用〈杯子〉。盒子用来装东西，不能直接用来盛水喝，喝水要用杯子。"}, {"text": "我想用盒子煮一锅面条。", "explanation": "这里应该用〈锅〉。盒子不能加热，煮面要用锅。"}, {"text": "他把盒子戴在头上出门了。", "explanation": "这里应该用〈帽子〉。盒子是装东西的容器，不能戴在头上，遮阳要用帽子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把钥匙放在盒子。", "corrected_sentence": "我把钥匙放在盒子里。", "error_description": "方位词漏用：“盒子”作处所时后面要加方位词“里”，应说“放在盒子里”，不能只说“放在盒子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
