INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20734, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "香蕉的皮，吃香蕉前要剥掉它。", "primary_collocate": null, "pronunciation": "xiāng jiāo pí", "ipa": "ɕiɑŋ˥ tɕiɑʊ˥ pʰi˧˥", "syllable_count": 3, "sentences": [{"text": "吃完香蕉，请把香蕉皮扔进垃圾桶。", "target_word": "香蕉皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有一块香蕉皮，小心别滑倒。", "target_word": "香蕉皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟踩到香蕉皮，摔了一跤。", "target_word": "香蕉皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "香蕉皮是黄色的，里面的肉很甜。", "target_word": "香蕉皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猴子吃了香蕉，把香蕉皮丢在树下。", "target_word": "香蕉皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "香蕉皮要先剥开，才能吃里面的香蕉。", "target_word": "香蕉皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个垃圾桶里全是香蕉皮和纸。", "target_word": "香蕉皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说香蕉皮可以放进厨房的垃圾袋。", "target_word": "香蕉皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着手里的香蕉皮，不知道往哪儿扔。", "target_word": "香蕉皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的香蕉皮很危险，我把它捡起来了。", "target_word": "香蕉皮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块香蕉皮", "label": "量词"}], "register": "中性", "sense_fingerprint": "香蕉外面黄色的皮，吃之前要剥掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4208b8-fa3e-439a-94ca-4737d9934ac5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20734, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "香蕉皮", "is_correct": true, "explanation": "正确答案。“香蕉皮”是吃完香蕉后要扔掉的皮，可以扔进垃圾桶。"}, {"text": "香蕉树", "is_correct": false, "explanation": "语义：垃圾桶装不下一棵树，“扔进垃圾桶”的东西必须能装进桶里。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱体积太大，装不进垃圾桶。"}, {"text": "香蕉味", "is_correct": false, "explanation": "搭配：“味道”不是实物，不能说“扔进垃圾桶”。"}], "explanations": {"香蕉皮": "正确答案。“香蕉皮”是吃完香蕉后要扔掉的皮，可以扔进垃圾桶。", "香蕉树": "语义：垃圾桶装不下一棵树，“扔进垃圾桶”的东西必须能装进桶里。", "冰箱": "语义：冰箱体积太大，装不进垃圾桶。", "香蕉味": "搭配：“味道”不是实物，不能说“扔进垃圾桶”。"}, "sentence_index": 0, "correct_answer": "香蕉皮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "超市里的香蕉皮很便宜，我买了两斤。", "explanation": "这里应该用〈香蕉〉。香蕉皮是剥下来扔掉的，超市按斤卖的是香蕉。"}, {"text": "这片香蕉皮很大，可以用来包粽子。", "explanation": "这里应该用〈香蕉叶〉。香蕉皮是剥下来扔掉的，不能包粽子；包粽子用的是香蕉叶。"}, {"text": "香蕉皮很脆，是我最喜欢的零食。", "explanation": "这里应该用〈香蕉片〉。香蕉皮不是零食，零食是晒干或炸脆的香蕉片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "香蕉皮", "is_correct": true, "explanation": "正确答案。“香蕉皮”是可以装进垃圾桶的东西，可以说“全是香蕉皮”。"}, {"text": "大象", "is_correct": false, "explanation": "语义：垃圾桶里不可能全是大象，大象也装不进垃圾桶。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑的部件，不会成堆地装在垃圾桶里。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“友谊”是抽象概念，不能和“纸”一起装进垃圾桶。"}], "explanations": {"香蕉皮": "正确答案。“香蕉皮”是可以装进垃圾桶的东西，可以说“全是香蕉皮”。", "大象": "语义：垃圾桶里不可能全是大象，大象也装不进垃圾桶。", "窗户": "语义：窗户是建筑的部件，不会成堆地装在垃圾桶里。", "友谊": "搭配：“友谊”是抽象概念，不能和“纸”一起装进垃圾桶。"}, "sentence_index": 6, "correct_answer": "香蕉皮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个香蕉皮很好吃，我每天都吃。", "explanation": "这里应该用〈香蕉〉。香蕉皮剥下来就扔掉，好吃、每天吃的是香蕉。"}, {"text": "院子里的香蕉皮长得很高。", "explanation": "这里应该用〈香蕉树〉。香蕉皮是剥下来的皮，不会生长；会长高的是香蕉树。"}, {"text": "妈妈把香蕉皮切成片做沙拉。", "explanation": "这里应该用〈香蕉〉。香蕉皮不能吃，切成片做沙拉的是香蕉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只香蕉皮被风吹走了。", "corrected_sentence": "那块香蕉皮被风吹走了。", "error_description": "量词错误：“香蕉皮”可以用“块”或“片”，一般不用“只”（“只”多用于鞋、碗、动物等）。错误形式是“那只香蕉皮”，正确形式是“那块香蕉皮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路上的香蕉皮了很滑。", "corrected_sentence": "路上的香蕉皮很滑。", "error_description": "了的位置错误：“了”不能放在名词“香蕉皮”后面。正确形式是“路上的香蕉皮很滑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
