INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20738, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从迷糊、蒙昧的状态中醒悟过来，开始明白道理或意识到某事。", "primary_collocate": null, "pronunciation": "jué xǐng", "ipa": "tɕyɛ˧˥ ɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "读了这本书以后，她终于觉醒了。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读了那本书，一下子觉醒了。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们觉醒后，开始为自己争取权利。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了那部纪录片，他的环保意识觉醒了。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影让很多年轻人觉醒了。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她终于觉醒，决定离开那个公司。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直到失去健康，他才真正觉醒。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的环保意识正在觉醒。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争让这个国家的人民觉醒了。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场大病让他觉醒，开始珍惜时间。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "觉醒了", "label": "完成体标"}, {"form": "觉醒过", "label": "经历体标"}], "register": "书面", "sense_fingerprint": "从睡眠中醒来，或突然醒悟明白道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86a9e316-c77e-4d87-af76-e864fd5a52f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20738, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "觉醒", "is_correct": true, "explanation": "正确：读书后醒悟、明白了道理，用“觉醒”。"}, {"text": "迁徙", "is_correct": false, "explanation": "语义：“迁徙”指大范围移动，与读书后的变化无关。"}, {"text": "咆哮", "is_correct": false, "explanation": "语义：“咆哮”指大声吼叫，不表示读书后明白道理。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休指离开工作岗位，不会因读一本书而发生。"}], "explanations": {"觉醒": "正确：读书后醒悟、明白了道理，用“觉醒”。", "迁徙": "语义：“迁徙”指大范围移动，与读书后的变化无关。", "咆哮": "语义：“咆哮”指大声吼叫，不表示读书后明白道理。", "退休": "语义：退休指离开工作岗位，不会因读一本书而发生。"}, "sentence_index": 0, "correct_answer": "觉醒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病人昏迷多日后终于觉醒，慢慢睁开了眼睛。", "explanation": "这里应该用〈苏醒〉。觉醒指从睡眠中醒来或醒悟，病人从昏迷中恢复要用苏醒。"}, {"text": "他的腿伤慢慢觉醒了，已经能下地走路。", "explanation": "这里应该用〈好转〉。觉醒指醒来或醒悟，伤势逐渐好起来要用好转。"}, {"text": "雨停以后，天上的乌云慢慢觉醒了。", "explanation": "这里应该用〈消散〉。觉醒指醒来或醒悟，云雾散开要用消散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "觉醒", "is_correct": true, "explanation": "正确。“直到失去健康，他才真正觉醒”指经历变故后醒悟。"}, {"text": "昏迷", "is_correct": false, "explanation": "语义：“昏迷”指失去知觉，与“真正醒悟”的意思正相反。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”是工作外出，与失去健康后的醒悟无关。"}, {"text": "迷惑", "is_correct": false, "explanation": "语义：“迷惑”指弄不清楚，与“真正”明白之后的结果相矛盾。"}], "explanations": {"觉醒": "正确。“直到失去健康，他才真正觉醒”指经历变故后醒悟。", "昏迷": "语义：“昏迷”指失去知觉，与“真正醒悟”的意思正相反。", "出差": "语义：“出差”是工作外出，与失去健康后的醒悟无关。", "迷惑": "语义：“迷惑”指弄不清楚，与“真正”明白之后的结果相矛盾。"}, "sentence_index": 6, "correct_answer": "觉醒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次手术后，他的膝盖慢慢觉醒了，可以正常走路了。", "explanation": "这里应该用〈复原〉。觉醒指醒来或醒悟，膝盖恢复原状要用复原。"}, {"text": "喝了热汤以后，身上的寒意慢慢觉醒了。", "explanation": "这里应该用〈消退〉。觉醒指醒来或醒悟，寒意逐渐减弱要用消退。"}, {"text": "这场风波很快就觉醒了。", "explanation": "这里应该用〈平息〉。觉醒指醒来或醒悟，风波停止要用平息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "看完那篇文章，他终于觉醒了着。", "corrected_sentence": "看完那篇文章，他终于觉醒了。", "error_description": "错误在体标：“了”已表示动作完成，又多出“着”，句子不通；应只用“觉醒了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那次失败让他觉醒来了，明白了努力的重要。", "corrected_sentence": "那次失败让他觉醒了，明白了努力的重要。", "error_description": "错误在补语：“觉醒”后不能接“来了”，应说“觉醒了”，表示已经醒悟。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
