INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20746, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放入某个容器或空间的里面。", "primary_collocate": null, "pronunciation": "fàng jìn", "ipa": "faŋ˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "他把钥匙放进了口袋。", "target_word": "放进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把书放进书包里。", "target_word": "放进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把牛奶放进冰箱里。", "target_word": "放进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把一点盐放进了汤里。", "target_word": "放进", "complexity_tier": "T3", "furigana": "fàng jìn", "sentence_source": "generated"}, {"text": "他把脏衣服放进洗衣机，然后按了开关。", "target_word": "放进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把手放进热水里，会烫伤的。", "target_word": "放进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把礼物放进盒子，再用纸包好。", "target_word": "放进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先把鸡蛋放进碗里，再加牛奶。", "target_word": "放进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个包很大，可以放进一台电脑。", "target_word": "放进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们把作业放进红色的盒子里。", "target_word": "放进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放进了", "label": "完成体"}, {"form": "放进去", "label": "趋向补语"}, {"form": "放进来", "label": "趋向补语"}, {"form": "放進", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把东西放入某个容器或空间里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e685e353-0b99-4f1c-ae5d-499665025313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20746, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放进", "is_correct": true, "explanation": "放进：表示把东西放入某处里面，与“钥匙”和“口袋”搭配，符合句意。"}, {"text": "吞进", "is_correct": false, "explanation": "搭配：“吞进”指咽入肚中，口袋不能被吞咽，句意荒谬。"}, {"text": "寄进", "is_correct": false, "explanation": "搭配：“寄”需要收件地址或邮箱之类的目的地，不能用于口袋。"}, {"text": "存进", "is_correct": false, "explanation": "搭配：“存”多用于银行、账户或仓库，不能说把钥匙“存进”口袋。"}], "explanations": {"放进": "放进：表示把东西放入某处里面，与“钥匙”和“口袋”搭配，符合句意。", "吞进": "搭配：“吞进”指咽入肚中，口袋不能被吞咽，句意荒谬。", "寄进": "搭配：“寄”需要收件地址或邮箱之类的目的地，不能用于口袋。", "存进": "搭配：“存”多用于银行、账户或仓库，不能说把钥匙“存进”口袋。"}, "sentence_index": 0, "correct_answer": "放进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生把药水放进了病人的血管。", "explanation": "这里应该用〈注入〉。注入指把药液送入体内，放进只表示一般的放置，不用于血管。"}, {"text": "他把病人放进了医院。", "explanation": "这里应该用〈送进〉。送进指把人护送到某处，如医院；放进多用于一般的放置，对病人说“放进医院”不自然。"}, {"text": "她把花放进了桌子上。", "explanation": "这里应该用〈放在〉。放进指放入某个空间的里面，桌面是在上面，应用“放在”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20746, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放进", "is_correct": true, "explanation": "放进：表示把礼物放入盒子里，与“礼物”和“盒子”搭配，符合句意。"}, {"text": "喷进", "is_correct": false, "explanation": "搭配：“喷进”用于液体或气体，礼物是固体，不能说“喷进盒子”。"}, {"text": "抬进", "is_correct": false, "explanation": "搭配：“抬”指搬运较重、较大的东西，与小件礼物装进盒子的搭配不合。"}, {"text": "咬进", "is_correct": false, "explanation": "语义：“咬进”指用牙齿咬入，盒子不能被咬，句意荒谬。"}], "explanations": {"放进": "放进：表示把礼物放入盒子里，与“礼物”和“盒子”搭配，符合句意。", "喷进": "搭配：“喷进”用于液体或气体，礼物是固体，不能说“喷进盒子”。", "抬进": "搭配：“抬”指搬运较重、较大的东西，与小件礼物装进盒子的搭配不合。", "咬进": "语义：“咬进”指用牙齿咬入，盒子不能被咬，句意荒谬。"}, "sentence_index": 6, "correct_answer": "放进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "写作文时，每段第一行要放进两格。", "explanation": "这里应该用〈缩进〉。放进表示把东西放入某处，段落开头空两格要用缩进。"}, {"text": "医生提醒我们，针不要放进皮肤太深。", "explanation": "这里应该用〈刺进〉。放进表示一般的放置，尖锐的针穿入身体要用刺进。"}, {"text": "在工地干活，要戴口罩，以免放进灰尘。", "explanation": "这里应该用〈吸进〉。放进是人主动放置物品，呼吸时把灰尘吸入体内要用吸进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把书放进着书包。", "corrected_sentence": "他把书放进了书包。", "error_description": "错误在“着”。“放进”表示动作完成、结果已经产生，应使用“了”。应把“着”改为“了”，说“放进了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她礼物放进纸箱，然后用胶带封好。", "corrected_sentence": "她把礼物放进纸箱，然后用胶带封好。", "error_description": "错误在“把”字缺失。“放进”表示把东西放入某处，要用“把”引出被放置的“礼物”，应说“把礼物放进纸箱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
