INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20750, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "太阳是天上一个很亮很热的圆球，它给我们带来光和温暖。", "primary_collocate": null, "pronunciation": "tài yáng", "ipa": "tʰai˥˩ jaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "太阳从东边升起来了。", "target_word": "太阳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天太阳很大，出门要带帽子。", "target_word": "太阳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳下山以后，天慢慢黑了。", "target_word": "太阳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的太阳照在身上很暖和。", "target_word": "太阳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天中午的太阳特别热。", "target_word": "太阳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在太阳下面玩得很开心。", "target_word": "太阳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物需要太阳和水才能长大。", "target_word": "太阳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳是天上最亮的东西。", "target_word": "太阳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上起床时，太阳已经出来了。", "target_word": "太阳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在海边看太阳慢慢落下去。", "target_word": "太阳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "太阳能", "label": "复合"}, {"form": "太阳镜", "label": "复合"}, {"form": "太陽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "天上发光发热的恒星，白天的光和热的来源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083b86a6-9f7b-4d1f-ab6f-174ff48943e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20750, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "太阳", "is_correct": true, "explanation": "太阳：天上发光发热的恒星，可以从东边升起。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不会从东边升起来。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“升起”不用于汽车。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎不会从东边升起来。"}], "explanations": {"太阳": "太阳：天上发光发热的恒星，可以从东边升起。", "冰箱": "语义：冰箱不会从东边升起来。", "汽车": "搭配：“升起”不用于汽车。", "老虎": "语义：老虎不会从东边升起来。"}, "sentence_index": 0, "correct_answer": "太阳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天边挂着一只太阳。", "explanation": "量词错误：太阳是天体，量词应该用〈个〉，〈只〉多用于动物。"}, {"text": "房间里的太阳坏了，我们只好点蜡烛。", "explanation": "这里应该用〈灯〉。太阳是天上的天体，室内照明要用〈灯〉，不能说“太阳坏了”。"}, {"text": "厨房里放着一把太阳。", "explanation": "量词错误：〈把〉多用于有柄的器具，“太阳”是天体，量词应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太阳", "is_correct": true, "explanation": "太阳：白天发光发热的天体，是植物需要的光和热的来源。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：植物长大不需要桌子。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：植物生长需要的是阳光和水，不说需要电视。"}, {"text": "小鸟", "is_correct": false, "explanation": "语义：植物需要的不是小鸟。"}], "explanations": {"太阳": "太阳：白天发光发热的天体，是植物需要的光和热的来源。", "桌子": "语义：植物长大不需要桌子。", "电视": "搭配：植物生长需要的是阳光和水，不说需要电视。", "小鸟": "语义：植物需要的不是小鸟。"}, "sentence_index": 6, "correct_answer": "太阳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们坐在海边看一张太阳慢慢落下去。", "explanation": "量词错误：“太阳”不用〈张〉，应该用〈个〉，〈张〉多用于平面的东西。"}, {"text": "我们坐在海边看一根太阳慢慢落下去。", "explanation": "量词错误：“太阳”不用〈根〉，应该用〈个〉，〈根〉多用于细长的东西。"}, {"text": "这盏灯能发太阳，很省电。", "explanation": "这里应该用〈光〉。灯发出的是光，太阳是天体，不能说“发太阳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天上有一只很亮的太阳。", "corrected_sentence": "天上有一个很亮的太阳。", "error_description": "错误：量词“只”；正确：“个”。“太阳”是天体，量词用“个”，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "早上窗外升起一张很大的太阳。", "corrected_sentence": "早上窗外升起一个很大的太阳。", "error_description": "错误：量词“张”；正确：“个”。“张”多用于平面的东西，“太阳”是天体，应该用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
