INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20751, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一个东西放到某个地方。", "primary_collocate": null, "pronunciation": "fàng zài", "ipa": "fɑŋ˥˩ tsai˥˩", "syllable_count": 2, "sentences": [{"text": "请把书放在桌子上。", "target_word": "放在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手机放在包里。", "target_word": "放在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把钥匙放在门口了。", "target_word": "放在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶放在冰箱里，不会坏。", "target_word": "放在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把花放在窗边。", "target_word": "放在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行李放在车后面吧。", "target_word": "放在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把鞋放在床上。", "target_word": "放在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把照片放在盒子里。", "target_word": "放在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把杯子放在我旁边。", "target_word": "放在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的书包放在教室里。", "target_word": "放在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放在了", "label": "体标"}], "register": "通用", "sense_fingerprint": "把东西放到某个位置上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17259789-fe49-4308-9f94-df080a361105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20751, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放在", "is_correct": true, "explanation": "放在表示把东西安置到某个地方，与「请把书……桌子上」的意思相合。"}, {"text": "躺", "is_correct": false, "explanation": "配价：「躺」是不及物动词，只能用于人或动物，不能支配「书」。"}, {"text": "倒", "is_correct": false, "explanation": "语义：「倒」指把液体或散装的东西往下倒，与「把书……桌子上」的意思不合。"}, {"text": "写", "is_correct": false, "explanation": "语义：「写」指书写文字，不能表示把书安放到桌子上。"}], "explanations": {"放在": "放在表示把东西安置到某个地方，与「请把书……桌子上」的意思相合。", "躺": "配价：「躺」是不及物动词，只能用于人或动物，不能支配「书」。", "倒": "语义：「倒」指把液体或散装的东西往下倒，与「把书……桌子上」的意思不合。", "写": "语义：「写」指书写文字，不能表示把书安放到桌子上。"}, "sentence_index": 0, "correct_answer": "放在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这份礼物放在妈妈。", "explanation": "这里应该用〈送给〉。放在后面接的是地点，不能接人；把东西交给人要说送给。"}, {"text": "学校放在山脚下。", "explanation": "这里应该用〈坐落〉。放在用于可以搬动的东西，学校这样的固定建筑要用坐落，表示位于某处。"}, {"text": "他把时间放在本子上。", "explanation": "这里应该用〈记〉。放在表示把实物摆放到某处，时间不是实物，要记下来，应说记在本子上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20751, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放在", "is_correct": true, "explanation": "放在表示把东西安置到某个地方，「别把鞋放在床上」是不让人把鞋放到床上，句意相合。"}, {"text": "铺", "is_correct": false, "explanation": "语义：「铺」指摊平、铺展，鞋不能被铺在床上，句意不通。"}, {"text": "咬", "is_correct": false, "explanation": "语义：「咬」指用牙齿夹住，与「把鞋……床上」的意思不合。"}, {"text": "穿", "is_correct": false, "explanation": "配价：「穿」需要穿的人作主语，并且支配衣物，不能说「穿在床上」。"}], "explanations": {"放在": "放在表示把东西安置到某个地方，「别把鞋放在床上」是不让人把鞋放到床上，句意相合。", "铺": "语义：「铺」指摊平、铺展，鞋不能被铺在床上，句意不通。", "咬": "语义：「咬」指用牙齿夹住，与「把鞋……床上」的意思不合。", "穿": "配价：「穿」需要穿的人作主语，并且支配衣物，不能说「穿在床上」。"}, "sentence_index": 6, "correct_answer": "放在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "月亮放在天上。", "explanation": "这里应该用〈挂〉。放在用于可以搬动的东西，月亮是悬在空中的，要说挂在天上。"}, {"text": "这个故事放在民间。", "explanation": "这里应该用〈流传〉。放在指人为搬放东西，故事在民间传开要用流传。"}, {"text": "笑容放在脸上。", "explanation": "这里应该用〈浮现〉。放在指人为搬放东西，笑容是表情，要说浮现在脸上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把手机放在在书架上。", "corrected_sentence": "我把手机放在书架上。", "error_description": "错误形式：「放在在」；正确形式：「放在」。「放在」已经包含「在」，不能再重复加「在」，应去掉多余的「在」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的书包放在着椅子上。", "corrected_sentence": "我的书包放在椅子上。", "error_description": "错误形式：「放在着」；正确形式：「放在」。「着」表示持续，要紧跟动词之后，「放在」后面不能直接加「着」，应去掉「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
