INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20756, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "泛指各种具体的物品。", "primary_collocate": null, "pronunciation": "dōng xi", "ipa": "tʊŋ ɕi", "syllable_count": 2, "sentences": [{"text": "我去超市买东西。", "target_word": "东西", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上有很多东西。", "target_word": "东西", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个东西太重了，我拿不动。", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，出门以前要把东西收好。", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的东西放在哪儿了？", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把东西都放进了书包里。", "target_word": "东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别忘了带你的东西。", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店卖的东西又好又便宜。", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想把用不着的东西送给朋友。", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家的时候，我整理了很多旧东西。", "target_word": "东西", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "样", "label": "量词"}, {"form": "東西", "label": "繁体"}], "register": "口语", "sense_fingerprint": "泛指各种具体的物品、东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3728d7ac-a5c9-42ec-9c46-36da5936aa49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20756, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "东西", "is_correct": true, "explanation": "正确。“买东西”指在超市购买物品，符合句意。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不能在超市购买，“买时间”说不通。"}, {"text": "东边", "is_correct": false, "explanation": "配价：“买”的宾语要是可购买的物品，方位词“东边”不能作宾语。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是抽象感受，不能在超市购买。"}], "explanations": {"东西": "正确。“买东西”指在超市购买物品，符合句意。", "时间": "语义：时间不能在超市购买，“买时间”说不通。", "东边": "配价：“买”的宾语要是可购买的物品，方位词“东边”不能作宾语。", "心情": "语义：心情是抽象感受，不能在超市购买。"}, "sentence_index": 0, "correct_answer": "东西"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在路上买了一本东西。", "explanation": "这里应该用〈件〉。〈本〉用于书册，“东西”不能用“本”计量。"}, {"text": "他从家里搬出了一只东西。", "explanation": "这里应该用〈件〉。〈只〉用于动物，“东西”不能用“只”计量。"}, {"text": "我借了一辆东西。", "explanation": "这里应该用〈件〉。〈辆〉用于车辆，“东西”不能用“辆”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "东西", "is_correct": true, "explanation": "正确。“带你的东西”指可以携带的物品，符合句意。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不能被携带，“带你的名字”说不通。"}, {"text": "历史", "is_correct": false, "explanation": "搭配：“带”一般接可携带的物件，不说“带历史”。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光线形成的影像，不能被携带，“带你的影子”说不通。"}], "explanations": {"东西": "正确。“带你的东西”指可以携带的物品，符合句意。", "名字": "语义：名字不能被携带，“带你的名字”说不通。", "历史": "搭配：“带”一般接可携带的物件，不说“带历史”。", "影子": "语义：影子是光线形成的影像，不能被携带，“带你的影子”说不通。"}, "sentence_index": 6, "correct_answer": "东西"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个地区的东西条件很差。", "explanation": "这里应该用〈物质〉。“物质条件”指生活和经济方面的条件，“东西”不能这样用。"}, {"text": "防疫东西已经运到了。", "explanation": "这里应该用〈物资〉。“防疫物资”是固定说法，口语词“东西”不用在这种正式的组合里。"}, {"text": "这家店卖卫生东西。", "explanation": "这里应该用〈用品〉。“卫生用品”是固定说法，不说“卫生东西”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "抽屉里有很多东西们。", "corrected_sentence": "抽屉里有很多东西。", "error_description": "词缀错误：“东西”后不能加“们”，“们”只用于人。正确形式是“东西”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些是我东西。", "corrected_sentence": "这些是我的东西。", "error_description": "“的”遗漏：“我”修饰“东西”时要加“的”，应说“我的东西”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20758, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变白", "is_correct": true, "explanation": "正确：“变白”与“变黑”是一对反义的颜色变化。"}, {"text": "融化", "is_correct": false, "explanation": "不是反义：融化指固体变成液体，与颜色变化无关。"}, {"text": "生长", "is_correct": false, "explanation": "不是反义：生长指生物长大，与颜色变化无关。"}, {"text": "扩大", "is_correct": false, "explanation": "不是反义：扩大指范围或规模变大，与颜色变化无关。"}], "correct_answer": "变白", "explanations": {"变白": "正确：“变白”与“变黑”是一对反义的颜色变化。", "融化": "不是反义：融化指固体变成液体，与颜色变化无关。", "生长": "不是反义：生长指生物长大，与颜色变化无关。", "扩大": "不是反义：扩大指范围或规模变大，与颜色变化无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20758, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变白", "is_correct": true, "explanation": "正确：“变白”与“变黑”是一对反义的颜色变化。"}, {"text": "膨胀", "is_correct": false, "explanation": "不是反义：膨胀指体积增大，与颜色变化无关。"}, {"text": "增长", "is_correct": false, "explanation": "不是反义：增长指数量或程度增加，与颜色变化无关。"}, {"text": "腐烂", "is_correct": false, "explanation": "不是反义：腐烂指物质变质分解，它常伴随变黑，但与“变黑”不构成反义。"}], "correct_answer": "变白", "explanations": {"变白": "正确：“变白”与“变黑”是一对反义的颜色变化。", "膨胀": "不是反义：膨胀指体积增大，与颜色变化无关。", "增长": "不是反义：增长指数量或程度增加，与颜色变化无关。", "腐烂": "不是反义：腐烂指物质变质分解，它常伴随变黑，但与“变黑”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20758, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西的颜色变成黑色。", "primary_collocate": null, "pronunciation": "biàn hēi", "ipa": "pjɛn˥˩ xeɪ˥", "syllable_count": 2, "sentences": [{"text": "香蕉放太久，皮会变黑。", "target_word": "变黑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "白纸掉进墨水里，马上变黑了。", "target_word": "变黑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "锅用火烧久了，底部会变黑。", "target_word": "变黑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银戒指戴了很多年，颜色变黑了。", "target_word": "变黑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天上的云变黑了，可能要下雨。", "target_word": "变黑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牙齿不刷，时间长了会变黑。", "target_word": "变黑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个铜盆放在潮湿的地方很久，表面就变黑了。", "target_word": "变黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的白墙，用了几年就变黑了。", "target_word": "变黑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水里放了墨，清水一下子变黑了。", "target_word": "变黑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "肉炒得太久，颜色都变黑了。", "target_word": "变黑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "变黑了", "label": "体标（了）"}, {"form": "变黑过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "东西颜色变成黑色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb8ad67b-239f-4a6f-82cc-ce442b51a334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20758, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变黑", "is_correct": true, "explanation": "正确：biàn hēi，意思是颜色变成黑色。"}, {"text": "变灰", "is_correct": false, "explanation": "huī（第一声）与 hēi（第一声）韵母不同（ui 与 ei），意思是变成灰色。"}, {"text": "变回", "is_correct": false, "explanation": "huí（第二声）与 hēi（第一声）韵母与声调都不同，意思是恢复原样。"}, {"text": "偏黑", "is_correct": false, "explanation": "piān（第一声）与 biàn（第四声）声母与声调都不同，意思是略微发黑。"}], "explanations": {"变黑": "正确：biàn hēi，意思是颜色变成黑色。", "变灰": "huī（第一声）与 hēi（第一声）韵母不同（ui 与 ei），意思是变成灰色。", "变回": "huí（第二声）与 hēi（第一声）韵母与声调都不同，意思是恢复原样。", "偏黑": "piān（第一声）与 biàn（第四声）声母与声调都不同，意思是略微发黑。"}, "sentence_index": null, "correct_answer": "变黑"}, "level_3": {"options": [{"text": "变黑", "is_correct": true, "explanation": "正确：“变黑”指香蕉皮因放久而颜色变成黑色，符合句中的因果关系。"}, {"text": "变亮", "is_correct": false, "explanation": "语义：香蕉放太久会发黑，不会变亮。"}, {"text": "变干净", "is_correct": false, "explanation": "语义：句中“放太久”说明皮会坏，不会变干净。"}, {"text": "变大", "is_correct": false, "explanation": "语义：香蕉皮不会因放久而变大。"}], "explanations": {"变黑": "正确：“变黑”指香蕉皮因放久而颜色变成黑色，符合句中的因果关系。", "变亮": "语义：香蕉放太久会发黑，不会变亮。", "变干净": "语义：句中“放太久”说明皮会坏，不会变干净。", "变大": "语义：香蕉皮不会因放久而变大。"}, "sentence_index": 0, "correct_answer": "变黑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个节日的气氛很快就变黑了。", "explanation": "这里应该用〈冷清〉。“变黑”只用于颜色，“气氛”不是颜色，应说气氛冷清。"}, {"text": "他感冒了，声音变黑了。", "explanation": "这里应该用〈变哑〉。“变黑”只说颜色，声音没有颜色。"}, {"text": "这学期我的成绩变黑了。", "explanation": "这里应该用〈变差〉。“变黑”只说颜色，不能评价成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变黑", "is_correct": true, "explanation": "正确：“变黑”指铜盆表面因潮湿而颜色变黑，符合句中的因果关系。"}, {"text": "变干", "is_correct": false, "explanation": "语义：句中说铜盆放在潮湿的地方，表面不会变干。"}, {"text": "变轻", "is_correct": false, "explanation": "语义：表面颜色的变化不会让铜盆变轻，句中强调的是颜色。"}, {"text": "变长", "is_correct": false, "explanation": "语义：放在潮湿的地方不会让铜盆的形状变长。"}], "explanations": {"变黑": "正确：“变黑”指铜盆表面因潮湿而颜色变黑，符合句中的因果关系。", "变干": "语义：句中说铜盆放在潮湿的地方，表面不会变干。", "变轻": "语义：表面颜色的变化不会让铜盆变轻，句中强调的是颜色。", "变长": "语义：放在潮湿的地方不会让铜盆的形状变长。"}, "sentence_index": 6, "correct_answer": "变黑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汤放了一夜，味道变黑了。", "explanation": "这里应该用〈变酸〉。“变黑”只说颜色，不能说味道。"}, {"text": "天气变黑了，要多穿衣服。", "explanation": "这里应该用〈变冷〉。“变黑”只说颜色，不能说气温。"}, {"text": "音乐的声音变黑了，我听不清。", "explanation": "这里应该用〈变小〉。“变黑”只说颜色，不能说声音大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "银戒指戴久了，表面就很变黑了。", "corrected_sentence": "银戒指戴久了，表面就变黑了。", "error_description": "“很”是程度副词，不能直接修饰动作性的“变黑”。应去掉多出的“很”，说“表面就变黑了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这口铁锅用久了，把底部就变黑了。", "corrected_sentence": "这口铁锅用久了，底部就变黑了。", "error_description": "“变黑”是不及物的变化动词，不能用“把”字句，应去掉“把”，说“底部就变黑了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
