INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20760, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看书上的字，知道它在说什么。", "primary_collocate": null, "pronunciation": "yuè dú", "ipa": "ɥe˥˩ tu˧˥", "syllable_count": 2, "sentences": [{"text": "弟弟还小，不会自己阅读。", "target_word": "阅读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在地铁上阅读新闻。", "target_word": "阅读", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她戴着眼镜阅读说明书。", "target_word": "阅读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先阅读题目，再写答案。", "target_word": "阅读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷每天早上阅读一份报纸。", "target_word": "阅读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光线太暗，没法阅读。", "target_word": "阅读", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他阅读得很快，一会儿就看完了。", "target_word": "阅读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们安静地阅读着自己的书。", "target_word": "阅读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想阅读这封信的内容。", "target_word": "阅读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阅读以前，先洗洗手。", "target_word": "阅读", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "阅读了", "label": "体标"}, {"form": "阅读过", "label": "体标"}, {"form": "阅读着", "label": "体标"}, {"form": "阅读量", "label": "复合"}, {"form": "閱讀", "label": "繁体"}], "register": "书面", "sense_fingerprint": "看书上的字并知道内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c5209d6-189a-4b08-9be6-981d2b1ec05c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20760, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阅读", "is_correct": true, "explanation": "正确。「弟弟还小，不会自己阅读」说明他还不会看书，符合句意。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：人不能「自己下雨」，句意不通。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：「出生」是一次性事件，不能与「自己」组合表示能力。"}, {"text": "开花", "is_correct": false, "explanation": "语义：「开花」是植物的动作，人不能「自己开花」，句意不通。"}], "explanations": {"阅读": "正确。「弟弟还小，不会自己阅读」说明他还不会看书，符合句意。", "下雨": "语义：人不能「自己下雨」，句意不通。", "出生": "搭配：「出生」是一次性事件，不能与「自己」组合表示能力。", "开花": "语义：「开花」是植物的动作，人不能「自己开花」，句意不通。"}, "sentence_index": 0, "correct_answer": "阅读"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去博物馆阅读展览。", "explanation": "这里应该用〈参观〉。阅读针对文字，去博物馆看展览要说参观。"}, {"text": "妹妹在作业本上阅读了一个苹果。", "explanation": "这里应该用〈画〉。阅读针对文字，在作业本上画苹果要说画。"}, {"text": "妈妈每天早上阅读房间。", "explanation": "这里应该用〈收拾〉。阅读针对文字，整理房间要说收拾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阅读", "is_correct": true, "explanation": "正确。「阅读得很快，一会儿就看完了」前后连贯，符合句意。"}, {"text": "跑", "is_correct": false, "explanation": "语义：「跑得很快」与「一会儿就看完了」的内容不相关，句意不通。"}, {"text": "游", "is_correct": false, "explanation": "语义：游泳与「看完了」无关，句意不通。"}, {"text": "写", "is_correct": false, "explanation": "搭配：「写得很快」不能与「看完了」搭配，「看完」的对象应是读物。"}], "explanations": {"阅读": "正确。「阅读得很快，一会儿就看完了」前后连贯，符合句意。", "跑": "语义：「跑得很快」与「一会儿就看完了」的内容不相关，句意不通。", "游": "语义：游泳与「看完了」无关，句意不通。", "写": "搭配：「写得很快」不能与「看完了」搭配，「看完」的对象应是读物。"}, "sentence_index": 6, "correct_answer": "阅读"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用相机阅读了一张照片。", "explanation": "这里应该用〈拍〉。阅读针对文字，用相机拍照要说拍。"}, {"text": "他阅读自行车去学校。", "explanation": "这里应该用〈骑〉。阅读针对文字，骑自行车要说骑。"}, {"text": "妈妈在厨房里阅读菜。", "explanation": "这里应该用〈切〉。阅读针对文字，切菜要说切。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他安静地阅读了着一封信。", "corrected_sentence": "他安静地阅读着一封信。", "error_description": "体标错误：「了」与「着」不能同时用于同一动词，正确说法是「阅读着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想阅读这份合同一下。", "corrected_sentence": "我想阅读这份合同。", "error_description": "位置错误：「一下」是动量补语，不能放在宾语「这份合同」之后，去掉「一下」即为正确说法「我想阅读这份合同」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
