INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20764, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使人的兴趣、热情或想象力等被引发出来，从而振作起来、行动起来。", "primary_collocate": null, "pronunciation": "jī fā", "ipa": "tɕi˥ fa˥", "syllable_count": 2, "sentences": [{"text": "这本书激发了我学中文的兴趣。", "target_word": "激发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话激发了学生的好奇心。", "target_word": "激发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好音乐能激发孩子的想象力。", "target_word": "激发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛激发着大家练习的热情。", "target_word": "激发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行激发了他画画的想法。", "target_word": "激发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用故事激发弟弟读书的兴趣。", "target_word": "激发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个小小的问题激发了大家的讨论。", "target_word": "激发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想用游戏激发孩子们的学习兴趣。", "target_word": "激发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成功激发过很多年轻人的梦想。", "target_word": "激发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个好消息激发了大家工作的热情。", "target_word": "激发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "激发了", "label": "体标"}, {"form": "激发着", "label": "体标"}, {"form": "激发过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使人产生热情、兴趣并行动起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05710f7d-b7af-44a9-a7be-d2504441099b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20764, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "激发", "is_correct": true, "explanation": "jī fā（第一、一声）意思是使人产生热情、兴趣并行动起来。"}, {"text": "技法", "is_correct": false, "explanation": "jì fǎ（第四、三声）与 jī fā（第一、一声）两个音节的声调都不同，意思是技术上的方法。"}, {"text": "寄发", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是寄出、发送。"}, {"text": "继发", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是接续着发生，多用于医学语境。"}], "explanations": {"激发": "jī fā（第一、一声）意思是使人产生热情、兴趣并行动起来。", "技法": "jì fǎ（第四、三声）与 jī fā（第一、一声）两个音节的声调都不同，意思是技术上的方法。", "寄发": "jì（第四声）与 jī（第一声）声调不同，意思是寄出、发送。", "继发": "jì（第四声）与 jī（第一声）声调不同，意思是接续着发生，多用于医学语境。"}, "sentence_index": null, "correct_answer": "激发"}, "level_3": {"options": [{"text": "激发", "is_correct": true, "explanation": "正确：「激发」指使兴趣被引发，与“学中文的兴趣”搭配，符合句意。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：「拆除」用于房屋、设施等实体，不能用于兴趣，句子不通。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：「批改」用于作业、试卷，不能说“批改兴趣”。"}, {"text": "设计", "is_correct": false, "explanation": "语义：「设计」指规划图样或方案，不能用来说“设计兴趣”。"}], "explanations": {"激发": "正确：「激发」指使兴趣被引发，与“学中文的兴趣”搭配，符合句意。", "拆除": "语义：「拆除」用于房屋、设施等实体，不能用于兴趣，句子不通。", "批改": "搭配：「批改」用于作业、试卷，不能说“批改兴趣”。", "设计": "语义：「设计」指规划图样或方案，不能用来说“设计兴趣”。"}, "sentence_index": 0, "correct_answer": "激发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂激发了大量废气，污染了附近的空气。", "explanation": "这里应该用〈排放〉。「激发」用于使人的兴趣、热情、能力等活跃起来，不能用于废气这类物质。"}, {"text": "这盏灯激发了房间里的黑暗。", "explanation": "这里应该用〈驱散〉。「激发」用于使人的兴趣、热情、能力等活跃起来，不能用于黑暗这类状态。"}, {"text": "这场大雨激发了庄稼。", "explanation": "这里应该用〈促进〉。「激发」用于使人的兴趣、热情、能力等活跃起来，不能直接用于庄稼，表示促进作物生长要用〈促进〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激发", "is_correct": true, "explanation": "正确：「激发」表示引发，“一个小小的问题激发了大家的讨论”符合句意。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：「擦」用于桌面、玻璃等具体的东西，不能说“擦讨论”。"}, {"text": "租", "is_correct": false, "explanation": "语义：「租」指付钱使用物品或房屋，不能用于讨论。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」要搭配歌曲、戏曲，不能说“唱讨论”。"}], "explanations": {"激发": "正确：「激发」表示引发，“一个小小的问题激发了大家的讨论”符合句意。", "擦": "搭配：「擦」用于桌面、玻璃等具体的东西，不能说“擦讨论”。", "租": "语义：「租」指付钱使用物品或房屋，不能用于讨论。", "唱": "搭配：「唱」要搭配歌曲、戏曲，不能说“唱讨论”。"}, "sentence_index": 6, "correct_answer": "激发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新规定激发了工人的负担。", "explanation": "这里应该用〈减少〉。「激发」用于兴趣、热情，负担是要减少的，不能说被激发。"}, {"text": "杀虫剂激发了害虫。", "explanation": "这里应该用〈消灭〉。害虫是要消灭的对象，不能用“激发”让它们活跃起来。"}, {"text": "这阵风激发了房间里的灰尘。", "explanation": "这里应该用〈扬起〉。「激发」用于人的兴趣、热情、能力等，不能用于灰尘这类物质，风卷起灰尘要用〈扬起〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一首歌激发下了他的回忆。", "corrected_sentence": "一首歌激发起了他的回忆。", "error_description": "错误：补语用了“下”。正确：应为“激发起”，“起”表示使某种感情或回忆兴起，“激发下”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天的比赛激发着大家的热情。", "corrected_sentence": "昨天的比赛激发了大家的热情。", "error_description": "错误：“着”表示动作正在进行，与已经完成的“昨天”不符。正确：应为“激发了”，表示过去已经完成的事。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
