INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20766, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把种子放到土里，让它长大。", "primary_collocate": null, "pronunciation": "zhòng huā", "ipa": "ʈʂʊŋ˥˩ xwa˥", "syllable_count": 2, "sentences": [{"text": "妈妈喜欢在院子里种花。", "target_word": "种花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，我们一起在院子里种花。", "target_word": "种花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家阳台太小，不能种花。", "target_word": "种花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在阳台上种花，也种菜。", "target_word": "种花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我跟奶奶学过种花。", "target_word": "种花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种花以前，要先把土弄松。", "target_word": "种花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今年第一次种花，不太会。", "target_word": "种花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种花需要有水，也需要太阳。", "target_word": "种花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末老师带学生在学校后面种花。", "target_word": "种花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居在门口种花，路过的人都说好看。", "target_word": "种花", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种了花", "label": "体标（了）"}, {"form": "种过花", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "把花的种子放进土里让花长大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fde7ad18-0ff2-44e3-844c-df7b9ce4ca9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20766, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "种花", "is_correct": true, "explanation": "“种花”指把种子或植株放进土里，与院子里的场景和“喜欢”的语境相符。"}, {"text": "洗花", "is_correct": false, "explanation": "搭配：“洗”一般搭配衣物、餐具等，不说洗花。"}, {"text": "踩花", "is_correct": false, "explanation": "语义：“踩”是践踏，花被踩坏，与“喜欢”的语义冲突。"}, {"text": "撕花", "is_correct": false, "explanation": "语义：“撕”是破坏动作，与“喜欢”的语义冲突。"}], "explanations": {"种花": "“种花”指把种子或植株放进土里，与院子里的场景和“喜欢”的语境相符。", "洗花": "搭配：“洗”一般搭配衣物、餐具等，不说洗花。", "踩花": "语义：“踩”是践踏，花被踩坏，与“喜欢”的语义冲突。", "撕花": "语义：“撕”是破坏动作，与“喜欢”的语义冲突。"}, "sentence_index": 0, "correct_answer": "种花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她喜欢在花瓶里种花。", "explanation": "这里应该用〈插花〉。种花指把种子或植株种进土里，花瓶里没有土，应说插花。"}, {"text": "她在头上种了一朵红花。", "explanation": "这里应该用〈戴花〉。种花指把植物种进土里，花不能种在头上，应说戴花。"}, {"text": "她用丝线在布上种花。", "explanation": "这里应该用〈绣花〉。种花是种植，用丝线在布上做花要说绣花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种花", "is_correct": true, "explanation": "“种花”与“今年第一次”和“不太会”相符，指第一次把花种进土里。"}, {"text": "喂花", "is_correct": false, "explanation": "搭配：“喂”的对象一般是人或动物，不说喂花。"}, {"text": "驯花", "is_correct": false, "explanation": "语义：“驯”指驯服动物，花不能被驯服，与句意不合。"}, {"text": "嚼花", "is_correct": false, "explanation": "语义：“嚼”是咀嚼，花不能嚼着种，与种植的语境冲突。"}], "explanations": {"种花": "“种花”与“今年第一次”和“不太会”相符，指第一次把花种进土里。", "喂花": "搭配：“喂”的对象一般是人或动物，不说喂花。", "驯花": "语义：“驯”指驯服动物，花不能被驯服，与句意不合。", "嚼花": "语义：“嚼”是咀嚼，花不能嚼着种，与种植的语境冲突。"}, "sentence_index": 6, "correct_answer": "种花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用彩纸种花，送给朋友。", "explanation": "这里应该用〈折花〉。纸做的花不能种，用彩纸做花要说折花。"}, {"text": "她在纸上种花，颜色很鲜艳。", "explanation": "这里应该用〈画花〉。种花需要土地，在纸上画花要说画花。"}, {"text": "工匠在木头上种花。", "explanation": "这里应该用〈刻花〉。木头上不能种花，在木头上雕出花要说刻花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在阳台上种花过。", "corrected_sentence": "我昨天在阳台上种过花。", "error_description": "体标错误：“过”应紧跟动词，说“种过花”，不能放在宾语“花”之后说“种花过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今年第一次种花，种很不好。", "corrected_sentence": "他今年第一次种花，种得很不好。", "error_description": "补语错误：程度补语要用“得”连接，漏掉“得”，应说“种得很不好”，不说“种很不好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20770, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变大", "is_correct": true, "explanation": "正确答案。“变大”与“变小”是一对反义词，都指体积或程度的变化方向相反。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“出发”指动身去某处，与“变小”的变化义没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "语义：“思考”指用脑子思索，与“变小”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”指悠闲地走动，与“变小”没有反义关系。"}], "correct_answer": "变大", "explanations": {"变大": "正确答案。“变大”与“变小”是一对反义词，都指体积或程度的变化方向相反。", "出发": "语义：“出发”指动身去某处，与“变小”的变化义没有反义关系。", "思考": "语义：“思考”指用脑子思索，与“变小”没有反义关系。", "散步": "语义：“散步”指悠闲地走动，与“变小”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20770, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变大", "is_correct": true, "explanation": "正确答案。“变大”与“变小”是一对反义词，表示体积或程度增大。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”指在水中运动，与“变小”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”指用声音表达音乐，与“变小”没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "语义：“写字”指用笔书写文字，与“变小”没有反义关系。"}], "correct_answer": "变大", "explanations": {"变大": "正确答案。“变大”与“变小”是一对反义词，表示体积或程度增大。", "游泳": "语义：“游泳”指在水中运动，与“变小”没有反义关系。", "唱歌": "语义：“唱歌”指用声音表达音乐，与“变小”没有反义关系。", "写字": "语义：“写字”指用笔书写文字，与“变小”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20770, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变得比以前小。", "primary_collocate": null, "pronunciation": "biàn xiǎo", "ipa": "pjɛn˥˩ ɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "洗过以后，这件衣服变小了。", "target_word": "变小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，外面的声音慢慢变小了。", "target_word": "变小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃得很少，肚子慢慢变小了。", "target_word": "变小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停以后，风也变小了。", "target_word": "变小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳升高了，我的影子变小了。", "target_word": "变小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球漏气了，一点一点变小。", "target_word": "变小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热水一洗，毛衣就变小了。", "target_word": "变小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大后，觉得房间变小了。", "target_word": "变小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞远了，在天上慢慢变小。", "target_word": "变小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐太吵了，声音能不能变小一点？", "target_word": "变小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变小了", "label": "体标"}, {"form": "变小过", "label": "体标"}, {"form": "變小", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物的大小、数量或程度比以前减小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe847b-453c-49ae-ad59-f1b51c9b852b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20770, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长大", "is_correct": false, "explanation": "语义：衣服不会生长，“长大”只用于人或动植物，与洗后缩水的语境不符。"}, {"text": "增加", "is_correct": false, "explanation": "语义：洗水后衣服只会缩小，“增加”指数量或程度上升，与句意相反。"}, {"text": "变小", "is_correct": true, "explanation": "正确答案。洗过后衣服缩水，变得比以前小，符合句意。"}, {"text": "生病", "is_correct": false, "explanation": "语义：衣服不会生病，“生病”不能用于物品。"}], "explanations": {"长大": "语义：衣服不会生长，“长大”只用于人或动植物，与洗后缩水的语境不符。", "增加": "语义：洗水后衣服只会缩小，“增加”指数量或程度上升，与句意相反。", "变小": "正确答案。洗过后衣服缩水，变得比以前小，符合句意。", "生病": "语义：衣服不会生病，“生病”不能用于物品。"}, "sentence_index": 0, "correct_answer": "变小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试以后，班里的同学变小了。", "explanation": "这里应该用〈减少〉。“变小”指事物的体积或程度变小，人数减少要用〈减少〉。"}, {"text": "今天的气温变小了，我们穿上了外套。", "explanation": "这里应该用〈降低〉。气温下降要用〈降低〉，不能说“变小”。"}, {"text": "上个月，他的成绩变小了。", "explanation": "这里应该用〈下降〉。成绩的下滑要用〈下降〉，“变小”不能描述成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提高", "is_correct": false, "explanation": "搭配：“提高”用于水平、质量，不能用于毛衣的大小。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物，与毛衣缩水的变化无关。"}, {"text": "变小", "is_correct": true, "explanation": "正确答案。热水使毛衣缩水，变得比以前小，符合句意。"}, {"text": "旅行", "is_correct": false, "explanation": "语义：“旅行”指外出游览，毛衣不会旅行。"}], "explanations": {"提高": "搭配：“提高”用于水平、质量，不能用于毛衣的大小。", "发明": "语义：“发明”指创造新事物，与毛衣缩水的变化无关。", "变小": "正确答案。热水使毛衣缩水，变得比以前小，符合句意。", "旅行": "语义：“旅行”指外出游览，毛衣不会旅行。"}, "sentence_index": 6, "correct_answer": "变小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的假期变小了。", "explanation": "这里应该用〈缩短〉。假期的长度缩减要用〈缩短〉，“变小”不能描述假期。"}, {"text": "他的汉语水平变小了。", "explanation": "这里应该用〈下降〉。水平降低要用〈下降〉，“变小”不能描述水平。"}, {"text": "我的存款变小了。", "explanation": "这里应该用〈减少〉。存款的数量减少要用〈减少〉，“变小”描述的是体积或程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块饼干放了一晚上，就被变小了。", "corrected_sentence": "这块饼干放了一晚上，就变小了。", "error_description": "“变小”是不及物动词，没有可以承受动作的受事，不能用“被”构成被动句，应直接说“变小了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "裤子洗了一次，就变小着。", "corrected_sentence": "裤子洗了一次，就变小了。", "error_description": "体标用错：“变小”表示变化的结果，应该用“了”表示变化已经完成。“着”表示状态持续，不能和“变小”这样的变化动词搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
