INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20774, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变少。", "primary_collocate": null, "pronunciation": "jiǎn shǎo", "ipa": "tɕjɛn˨˩˦ ʂau˨˩˦", "syllable_count": 2, "sentences": [{"text": "我想减少吃糖的次数。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关灯可以减少用电。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把每天喝咖啡的杯数减少了。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司减少了三个人。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了身体好，爸爸减少了抽烟。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多用公共汽车能减少污染。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师减少了我们的作业。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈想减少家里花钱的地方。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让他减少盐的量。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要减少用塑料袋。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减少了", "label": "体标"}, {"form": "减少过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使数量变少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d347d6-cd46-4fd0-a1a8-e1f8b84db37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "减少", "is_correct": true, "explanation": "正确答案。“我想减少吃糖的次数”中，指使次数变少。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于抹去具体物体表面，不能和“次数”搭配。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢掉具体物品，与吃糖的次数无关，与句意冲突。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”指向下掘取，不能用来处理次数，与句意冲突。"}], "explanations": {"减少": "正确答案。“我想减少吃糖的次数”中，指使次数变少。", "擦": "搭配：“擦”用于抹去具体物体表面，不能和“次数”搭配。", "扔": "语义：“扔”指丢掉具体物品，与吃糖的次数无关，与句意冲突。", "挖": "语义：“挖”指向下掘取，不能用来处理次数，与句意冲突。"}, "sentence_index": 0, "correct_answer": "减少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的气温减少了三度。", "explanation": "这里应该用〈降低〉。减少说数量变少，气温、温度等要用降低。"}, {"text": "这块布的颜色减少了一些。", "explanation": "这里应该用〈褪色〉。布料颜色变淡要说褪色，减少说数量变少，不用于颜色。"}, {"text": "老师的声音慢慢减少了。", "explanation": "这里应该用〈减弱〉。声音的强弱要用减弱，减少只用于数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "减少", "is_correct": true, "explanation": "正确答案。“老师减少了我们的作业”中，指使作业变少。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用来处理作业，与句意冲突。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用液体，不能用来处理作业，与句意冲突。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”多用于食物，不说烤作业。"}], "explanations": {"减少": "正确答案。“老师减少了我们的作业”中，指使作业变少。", "吃": "语义：“吃”指进食，不能用来处理作业，与句意冲突。", "喝": "语义：“喝”指饮用液体，不能用来处理作业，与句意冲突。", "烤": "搭配：“烤”多用于食物，不说烤作业。"}, "sentence_index": 6, "correct_answer": "减少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "十减少三，等于七。", "explanation": "这里应该用〈减去〉。算式中的减法要用减去，减少说数量变少，不用于算式。"}, {"text": "他的汉语水平减少了。", "explanation": "这里应该用〈下降〉。水平的变化要说提高或下降，减少只用于数量。"}, {"text": "爷爷的视力减少了。", "explanation": "这里应该用〈减退〉。视力等能力的衰退要用减退，减少只用于数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司的员工减少了到三个人。", "corrected_sentence": "公司的员工减少到了三个人。", "error_description": "“了”位置错误：“减少到”是动词加补语的结构，“了”应放在补语“到”之后，应说“减少到了三个人”，不能说“减少了到三个人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些年，城市的污染减少地很明显。", "corrected_sentence": "这些年，城市的污染减少得很明显。", "error_description": "补语标记用错：表示程度的补语要用“得”，不能用“地”，应说“减少得很明显”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
