INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20776, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "省钱就是不花太多的钱。", "primary_collocate": null, "pronunciation": "shěng qián", "ipa": "ʂɤŋ˨˩˦ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我想省钱，所以自己带饭。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁比打车更省钱。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月都省钱买书。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买便宜的东西可以省钱。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说在家做饭更省钱。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这次旅行想尽量省钱。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了省钱，走路去上班。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样买菜一点也不省钱。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很会省钱，一个月只花一千块。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在网上买东西能省钱，也很方便。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "省了钱", "label": "体标"}, {"form": "省过钱", "label": "体标"}, {"form": "省点钱", "label": "离合"}], "register": "口语", "sense_fingerprint": "少花钱、节约开支", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c13fba2-698e-4727-b25b-42f4c360e701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20776, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "省钱", "is_correct": true, "explanation": "正确。省钱指不花太多的钱。"}, {"text": "剩钱", "is_correct": false, "explanation": "剩钱 shèng qián 与 shěng qián 声调不同（第四声与第三声），意思是剩下的钱。"}, {"text": "赏钱", "is_correct": false, "explanation": "赏钱 shǎng qián 与 shěng qián 韵母不同（ang 与 eng），意思是赏赐或小费。"}, {"text": "升迁", "is_correct": false, "explanation": "升迁 shēng qiān 与 shěng qián 声调不同，意思是职位提高。"}], "explanations": {"省钱": "正确。省钱指不花太多的钱。", "剩钱": "剩钱 shèng qián 与 shěng qián 声调不同（第四声与第三声），意思是剩下的钱。", "赏钱": "赏钱 shǎng qián 与 shěng qián 韵母不同（ang 与 eng），意思是赏赐或小费。", "升迁": "升迁 shēng qiān 与 shěng qián 声调不同，意思是职位提高。"}, "sentence_index": null, "correct_answer": "省钱"}, "level_3": {"options": [{"text": "省钱", "is_correct": true, "explanation": "正确。省钱与后半句“所以自己带饭”构成因果，符合“想省钱”的理由。"}, {"text": "花钱", "is_correct": false, "explanation": "语义：花钱与“所以自己带饭”的理由相反，自己带饭正是为了少花钱。"}, {"text": "挣钱", "is_correct": false, "explanation": "语义：挣钱是获得收入，与“自己带饭”之间没有因果关系。"}, {"text": "请客", "is_correct": false, "explanation": "语义：请客是宴请他人，与“我想……，所以自己带饭”的因果关系不通。"}], "explanations": {"省钱": "正确。省钱与后半句“所以自己带饭”构成因果，符合“想省钱”的理由。", "花钱": "语义：花钱与“所以自己带饭”的理由相反，自己带饭正是为了少花钱。", "挣钱": "语义：挣钱是获得收入，与“自己带饭”之间没有因果关系。", "请客": "语义：请客是宴请他人，与“我想……，所以自己带饭”的因果关系不通。"}, "sentence_index": 0, "correct_answer": "省钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他靠卖菜省钱，每个月收入五千块。", "explanation": "这里应该用〈挣钱〉。省钱指少花钱，靠卖菜获得收入要用挣钱。"}, {"text": "他每个月都去银行省钱。", "explanation": "这里应该用〈存钱〉。去银行是为了存钱，省钱指少花钱，不能用于银行。"}, {"text": "他这个人一向乱省钱。", "explanation": "这里应该用〈花钱〉。“乱”指随便花钱，省钱指少花钱，二者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省钱", "is_correct": true, "explanation": "正确。“为了省钱”说明走路去上班的目的，与句意一致。"}, {"text": "乘车", "is_correct": false, "explanation": "语义：乘车与“走路去上班”相互矛盾，不能作为“为了”的目的。"}, {"text": "打车", "is_correct": false, "explanation": "语义：打车与“走路去上班”的做法冲突，句子的前后逻辑不通。"}, {"text": "开车", "is_correct": false, "explanation": "语义：开车与“走路去上班”相互矛盾，前后逻辑不通。"}], "explanations": {"省钱": "正确。“为了省钱”说明走路去上班的目的，与句意一致。", "乘车": "语义：乘车与“走路去上班”相互矛盾，不能作为“为了”的目的。", "打车": "语义：打车与“走路去上班”的做法冲突，句子的前后逻辑不通。", "开车": "语义：开车与“走路去上班”相互矛盾，前后逻辑不通。"}, "sentence_index": 6, "correct_answer": "省钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次投资他省钱。", "explanation": "这里应该用〈赔钱〉。省钱指少花钱，投资亏损要用赔钱。"}, {"text": "他在商店卖衣服省钱，每天收入两千块。", "explanation": "这里应该用〈赚钱〉。省钱指少花钱，卖衣服获得收入要用赚钱。"}, {"text": "他手头紧，只好向朋友省钱。", "explanation": "这里应该用〈借钱〉。手头紧时向朋友要钱要用借钱，省钱不能表示借入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他上个月省着很多钱。", "corrected_sentence": "他上个月省了很多钱。", "error_description": "错误形式：“省着”；正确形式：“省了”。表示已经完成、得到结果（省下很多钱）要用“了”，“着”表示持续，不能这样用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她这个月省钱得很厉害。", "corrected_sentence": "她这个月省钱省得很厉害。", "error_description": "错误形式：“省钱得很厉害”；正确形式：“省钱省得很厉害”。带补语“得”的结构要重复动词，即“V+宾语+V+得+补语”，不能省去第二个“省”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
