INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20778, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "种菜就是在土里种下菜种子，然后浇水，让它们长大。", "primary_collocate": null, "pronunciation": "zhòng cài", "ipa": "ʈʂʊŋ˥˩ tsʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷在院子里种菜。", "target_word": "种菜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家阳台上可以种菜。", "target_word": "种菜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天到了，妈妈开始种菜。", "target_word": "种菜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "种菜要给小苗浇水。", "target_word": "种菜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他退休以后喜欢种菜。", "target_word": "种菜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们学校有一块地，同学们可以种菜。", "target_word": "种菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以前学过种菜，知道要浇水。", "target_word": "种菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶今天在地里种菜，我去帮她浇水。", "target_word": "种菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在小花园里种菜，吃自己种的菜。", "target_word": "种菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种菜的时候，土要松，水也要够。", "target_word": "种菜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种了菜", "label": "体标"}, {"form": "种过菜", "label": "体标"}], "register": "中性", "sense_fingerprint": "在土地上播种并照料蔬菜使其生长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd295e12-7231-4a6a-a8ef-075f24fccda5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20778, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "种菜", "is_correct": true, "explanation": "“种菜”指在土里种植蔬菜，“爷爷在院子里”的语境正合适。"}, {"text": "逛街", "is_correct": false, "explanation": "搭配：“逛街”需要在街道或商场进行，不能在院子里逛街。"}, {"text": "出国", "is_correct": false, "explanation": "语义：“出国”指离开本国，与“在院子里”的地点相冲突。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指因工作离开居住地，与“在院子里”的地点相冲突。"}], "explanations": {"种菜": "“种菜”指在土里种植蔬菜，“爷爷在院子里”的语境正合适。", "逛街": "搭配：“逛街”需要在街道或商场进行，不能在院子里逛街。", "出国": "语义：“出国”指离开本国，与“在院子里”的地点相冲突。", "出差": "语义：“出差”指因工作离开居住地，与“在院子里”的地点相冲突。"}, "sentence_index": 0, "correct_answer": "种菜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天去菜市场种菜。", "explanation": "这里应该用〈买菜〉。〈种菜〉指在土里种植蔬菜，不能在菜市场进行。"}, {"text": "他每天下午在游泳池里种菜。", "explanation": "这里应该用〈游泳〉。〈种菜〉要在土里进行，不能在游泳池里。"}, {"text": "他每天坐在办公室里种菜。", "explanation": "这里应该用〈上班〉。〈种菜〉指在土里种植蔬菜，不能在办公室里进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种菜", "is_correct": true, "explanation": "“种菜”指种植蔬菜，“知道要浇水”与种菜的过程相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”不需要浇水，与“知道要浇水”的语境相冲突。"}, {"text": "修车", "is_correct": false, "explanation": "语义：“修车”针对机械，与“知道要浇水”的语境不符。"}, {"text": "织毛衣", "is_correct": false, "explanation": "搭配：“织毛衣”的对象是毛线和衣物，不能说“知道要浇水”。"}], "explanations": {"种菜": "“种菜”指种植蔬菜，“知道要浇水”与种菜的过程相符。", "游泳": "语义：“游泳”不需要浇水，与“知道要浇水”的语境相冲突。", "修车": "语义：“修车”针对机械，与“知道要浇水”的语境不符。", "织毛衣": "搭配：“织毛衣”的对象是毛线和衣物，不能说“知道要浇水”。"}, "sentence_index": 6, "correct_answer": "种菜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天种菜去上班。", "explanation": "这里应该用〈坐车〉。〈种菜〉指种植蔬菜，不能表示出行。"}, {"text": "他每天都去邮局种菜。", "explanation": "这里应该用〈寄信〉。〈种菜〉不能在邮局进行。"}, {"text": "他每天八点在教室里种菜。", "explanation": "这里应该用〈上课〉。〈种菜〉指在土里种植蔬菜，不能在教室里进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春天到了，我们开始种了菜。", "corrected_sentence": "春天到了，我们开始种菜了。", "error_description": "错误：「了」放在「种」和「菜」之间，表示动作已经完成，与「开始」矛盾。正确：应说「开始种菜了」，「了」放在句末表示开始这一变化。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前在院子里种菜过。", "corrected_sentence": "他以前在院子里种过菜。", "error_description": "错误：体标「过」应紧跟动词，写成「种过菜」；「种菜过」把「过」放在宾语之后，语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
