INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20780, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "叶子是长在树枝上的绿色或彩色的小片。", "primary_collocate": null, "pronunciation": "yè zi", "ipa": "jɛ˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "秋天，树上的叶子变黄了。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，叶子从树枝上掉下来。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有很多红色的叶子。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在公园里捡叶子。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，树枝上长出了绿绿的叶子。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树的叶子很密，夏天很凉快。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把黄叶子放进书里。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，树上一片叶子也没有。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叶子都落光了，树枝很空。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢收集不同颜色的叶子。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "树叶", "label": "复合词"}], "register": "中性", "sense_fingerprint": "树枝上长的绿色或彩色小片，会随季节变色、掉落", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c5f7b6-97db-4c5b-be74-c6e035cd0ce7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20780, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "叶子", "is_correct": true, "explanation": "叶子：长在树枝上的绿色或彩色小片，即听到的词。"}, {"text": "椅子", "is_correct": false, "explanation": "yǐ（第三声）与 yè（第四声）声调不同，意思是椅子。"}, {"text": "椰子", "is_correct": false, "explanation": "yē（第一声）与 yè（第四声）声调不同，意思是椰子。"}, {"text": "义子", "is_correct": false, "explanation": "yì 与 yè 韵母不同（i 与 e），意思是收养的儿子。"}], "explanations": {"叶子": "叶子：长在树枝上的绿色或彩色小片，即听到的词。", "椅子": "yǐ（第三声）与 yè（第四声）声调不同，意思是椅子。", "椰子": "yē（第一声）与 yè（第四声）声调不同，意思是椰子。", "义子": "yì 与 yè 韵母不同（i 与 e），意思是收养的儿子。"}, "sentence_index": null, "correct_answer": "叶子"}, "level_3": {"options": [{"text": "叶子", "is_correct": true, "explanation": "叶子：树上的叶子会变黄并在秋天掉落，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不长在树上，也不会因秋天而变黄。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是金属工具，不长在树上，不会随季节变黄。"}, {"text": "玻璃", "is_correct": false, "explanation": "体貌：玻璃是透明的硬物，外观不会随季节变成黄色。"}], "explanations": {"叶子": "叶子：树上的叶子会变黄并在秋天掉落，符合语境。", "石头": "语义：石头不长在树上，也不会因秋天而变黄。", "钥匙": "语义：钥匙是金属工具，不长在树上，不会随季节变黄。", "玻璃": "体貌：玻璃是透明的硬物，外观不会随季节变成黄色。"}, "sentence_index": 0, "correct_answer": "叶子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他早上吃了一碗叶子。", "explanation": "这里应该用〈麦片〉。早餐吃的一碗颗粒食物是麦片，叶子不能这样当主食吃。"}, {"text": "小鸟身上长满了漂亮的叶子。", "explanation": "这里应该用〈羽毛〉。鸟身上长的是羽毛，叶子长在树枝上。"}, {"text": "这条鱼身上的叶子亮亮的。", "explanation": "这里应该用〈鳞片〉。鱼身上的小片是鳞片，叶子长在树枝上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138888af-873c-47fc-bd5e-dbe14baeca24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20780, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "叶子", "is_correct": true, "explanation": "叶子：长在树枝上的绿色或彩色小片，即听到的词。"}, {"text": "椰子", "is_correct": false, "explanation": "yē（第一声）与 yè（第四声）声调不同，意思是椰子。"}, {"text": "乐子", "is_correct": false, "explanation": "lè 与 yè 声母不同（l 与 y），意思是玩笑、乐趣。"}, {"text": "色子", "is_correct": false, "explanation": "sè 与 yè 声母不同（s 与 y），口语中指骰子。"}, {"text": "月子", "is_correct": false, "explanation": "yuè 比 yè 多一个介音 u，意思是坐月子的时期。"}], "explanations": {"叶子": "叶子：长在树枝上的绿色或彩色小片，即听到的词。", "椰子": "yē（第一声）与 yè（第四声）声调不同，意思是椰子。", "乐子": "lè 与 yè 声母不同（l 与 y），意思是玩笑、乐趣。", "色子": "sè 与 yè 声母不同（s 与 y），口语中指骰子。", "月子": "yuè 比 yè 多一个介音 u，意思是坐月子的时期。"}, "sentence_index": null, "correct_answer": "叶子"}, "level_3": {"options": [{"text": "叶子", "is_correct": true, "explanation": "叶子：小明放进书里的黄色叶子，符合语境。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能放进书里，句子不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是墙上的开口，不是可以放进书里的东西。"}, {"text": "天空", "is_correct": false, "explanation": "配价：天空不是具体的物件，不能作“放进书里”的对象。"}], "explanations": {"叶子": "叶子：小明放进书里的黄色叶子，符合语境。", "汽车": "语义：汽车是交通工具，不能放进书里，句子不通。", "窗户": "语义：窗户是墙上的开口，不是可以放进书里的东西。", "天空": "配价：天空不是具体的物件，不能作“放进书里”的对象。"}, "sentence_index": 6, "correct_answer": "叶子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书有两百张叶子。", "explanation": "这里应该用〈页〉。书里的纸叫页，叶子长在树枝上。"}, {"text": "她头上的叶子又黑又长。", "explanation": "这里应该用〈头发〉。人头上长的是头发，叶子长在树枝上。"}, {"text": "妈妈用叶子给我织了一件毛衣。", "explanation": "这里应该用〈毛线〉。织毛衣用的是毛线，叶子长在树枝上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138888af-873c-47fc-bd5e-dbe14baeca24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只叶子落在地上。", "corrected_sentence": "一片叶子落在地上。", "error_description": "错误：“一只叶子”。正确：“一片叶子”。叶子是扁平的薄片，量词用“片”，“只”多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138888af-873c-47fc-bd5e-dbe14baeca24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风一吹，叶子掉下了来。", "corrected_sentence": "风一吹，叶子掉了下来。", "error_description": "错误：“掉下了来”。正确：“掉了下来”。“了”应放在动词“掉”之后，“下来”是趋向补语，要连在一起。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138888af-873c-47fc-bd5e-dbe14baeca24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
