INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "箱子是一个方方的容器，可以用来装东西。", "primary_collocate": null, "pronunciation": "xiāng zi", "ipa": "ɕjɑŋ˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "这个箱子是方的，可以装很多东西。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用箱子装玩具。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子下面有一个大箱子。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬着一个重箱子上楼。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子满了，放不进去了。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把箱子放在门口。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只箱子里全是书。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子坏了，不能再用。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起把箱子抬进房间。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧箱子里有爷爷的照片。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "只", "label": "量词"}, {"form": "纸箱", "label": "复合词"}], "register": "中性", "sense_fingerprint": "方形的容器，用来装东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c5f7b6-97db-4c5b-be74-c6e035cd0ce7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20782, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "箱子", "is_correct": true, "explanation": "箱子：方形的收纳容器，即听到的词。"}, {"text": "巷子", "is_correct": false, "explanation": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是小巷。"}, {"text": "仙子", "is_correct": false, "explanation": "xiān 与 xiāng 韵尾不同（n 与 ng），意思是仙女。"}, {"text": "橡子", "is_correct": false, "explanation": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是橡树的果实。"}], "explanations": {"箱子": "箱子：方形的收纳容器，即听到的词。", "巷子": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是小巷。", "仙子": "xiān 与 xiāng 韵尾不同（n 与 ng），意思是仙女。", "橡子": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是橡树的果实。"}, "sentence_index": null, "correct_answer": "箱子"}, "level_3": {"options": [{"text": "箱子", "is_correct": true, "explanation": "箱子：方形的容器，可以装很多东西，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是实心的硬块，不能用来装东西，与“可以装很多东西”矛盾。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯是铺在地上的织物，不是容器，不能装东西。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是墙上的开口，不是用来装东西的。"}], "explanations": {"箱子": "箱子：方形的容器，可以装很多东西，符合语境。", "石头": "语义：石头是实心的硬块，不能用来装东西，与“可以装很多东西”矛盾。", "地毯": "语义：地毯是铺在地上的织物，不是容器，不能装东西。", "窗户": "语义：窗户是墙上的开口，不是用来装东西的。"}, "sentence_index": 0, "correct_answer": "箱子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我口渴了，用箱子喝了一点水。", "explanation": "这里应该用〈杯子〉。喝水用杯子，箱子是装东西的方形容器，不用来喝水。"}, {"text": "他把钱放进箱子，再把箱子放进裤兜里。", "explanation": "这里应该用〈钱包〉。能放进裤兜的是钱包，箱子太大，放不进裤兜。"}, {"text": "我们全家住在一个有三个卧室的箱子里。", "explanation": "这里应该用〈房子〉。人住的是房子，箱子是装东西的容器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138888af-873c-47fc-bd5e-dbe14baeca24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "箱子", "is_correct": true, "explanation": "箱子：能装东西的容器，里面可以全是书，符合语境。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子是穿在脚上的，里面不装书。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是用来插花的，不用来装书。"}, {"text": "苹果", "is_correct": false, "explanation": "体貌：苹果是实心的果实，里面没有空间装书。"}], "explanations": {"箱子": "箱子：能装东西的容器，里面可以全是书，符合语境。", "鞋子": "语义：鞋子是穿在脚上的，里面不装书。", "花瓶": "语义：花瓶是用来插花的，不用来装书。", "苹果": "体貌：苹果是实心的果实，里面没有空间装书。"}, "sentence_index": 6, "correct_answer": "箱子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下雨了，他打开箱子挡雨。", "explanation": "这里应该用〈雨伞〉。挡雨用雨伞，箱子是装东西的容器。"}, {"text": "她坐在箱子上开车去上班。", "explanation": "这里应该用〈汽车〉。开车去上班要用汽车，箱子是装东西的容器。"}, {"text": "我把汤倒进箱子里慢慢喝。", "explanation": "这里应该用〈碗〉。盛汤用碗，箱子是装东西的方形容器，不能盛汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138888af-873c-47fc-bd5e-dbe14baeca24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在床下找到一片旧箱子。", "corrected_sentence": "他在床下找到一个旧箱子。", "error_description": "错误：“一片旧箱子”。正确：“一个旧箱子”。箱子是立体的容器，量词用“个”，“片”用于扁平的薄片。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138888af-873c-47fc-bd5e-dbe14baeca24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把箱子搬了进屋里。", "corrected_sentence": "他把箱子搬进了屋里。", "error_description": "错误：“搬了进屋里”。正确：“搬进了屋里”。“搬进”是动补结构，“了”应放在“进”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138888af-873c-47fc-bd5e-dbe14baeca24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20786, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "多", "is_correct": true, "explanation": "正确：“多”与“少”（数量不多）意义相反。"}, {"text": "快", "is_correct": false, "explanation": "“快”指速度，与“少”（数量）没有反义关系。"}, {"text": "高", "is_correct": false, "explanation": "“高”指高度，与“少”的数量义没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "“轻”指重量，与“少”没有反义关系。"}], "correct_answer": "多", "explanations": {"多": "正确：“多”与“少”（数量不多）意义相反。", "快": "“快”指速度，与“少”（数量）没有反义关系。", "高": "“高”指高度，与“少”的数量义没有反义关系。", "轻": "“轻”指重量，与“少”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20786, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "多", "is_correct": true, "explanation": "正确：“多”与“少”（数量不多）意义相反。"}, {"text": "长", "is_correct": false, "explanation": "“长”的反义词是“短”，与“少”没有反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”的反义词是“薄”，与“少”没有反义关系。"}, {"text": "深", "is_correct": false, "explanation": "“深”的反义词是“浅”，与“少”没有反义关系。"}], "correct_answer": "多", "explanations": {"多": "正确：“多”与“少”（数量不多）意义相反。", "长": "“长”的反义词是“短”，与“少”没有反义关系。", "厚": "“厚”的反义词是“薄”，与“少”没有反义关系。", "深": "“深”的反义词是“浅”，与“少”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20786, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不多，数量小。", "primary_collocate": null, "pronunciation": "shǎo", "ipa": "ʂɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "今天来的人很少。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的雨水比较少。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他话少，不爱说笑。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家里的书很少，只有几本。", "target_word": "少", "complexity_tier": "T3", "furigana": "wǒ jiā lǐ de shū hěn shǎo, zhǐ yǒu jǐ běn。", "sentence_source": "generated"}, {"text": "菜里盐太少了，不好吃。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近睡得少，我很累。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的饭馆少，晚上不好找吃的。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的水果太少，不够大家吃。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天这里的雪很少。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里学生少，老师能照顾每个人。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量不多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578a203d-4358-4a88-a532-6eee781a844a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20786, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "少", "is_correct": true, "explanation": "正确答案：少（shǎo），意思是数量不多。"}, {"text": "扫", "is_correct": false, "explanation": "sǎo 与 shǎo 声母不同（s 与 sh），“扫”意思是打扫。"}, {"text": "烧", "is_correct": false, "explanation": "shāo（第一声）与 shǎo（第三声）声调不同，“烧”意思是燃烧。"}, {"text": "吵", "is_correct": false, "explanation": "chǎo 与 shǎo 声母不同（ch 与 sh），“吵”意思是吵闹。"}, {"text": "找", "is_correct": false, "explanation": "zhǎo 与 shǎo 声母不同（zh 与 sh），“找”意思是寻找。"}], "explanations": {"少": "正确答案：少（shǎo），意思是数量不多。", "扫": "sǎo 与 shǎo 声母不同（s 与 sh），“扫”意思是打扫。", "烧": "shāo（第一声）与 shǎo（第三声）声调不同，“烧”意思是燃烧。", "吵": "chǎo 与 shǎo 声母不同（ch 与 sh），“吵”意思是吵闹。", "找": "zhǎo 与 shǎo 声母不同（zh 与 sh），“找”意思是寻找。"}, "sentence_index": null, "correct_answer": "少"}, "level_3": {"options": [{"text": "少", "is_correct": true, "explanation": "正确：“今天来的人很少”，表示人数不多。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”描述速度，不能用来形容“来的人”的数量。"}, {"text": "重", "is_correct": false, "explanation": "搭配：“重”说分量，不能修饰人的数量。"}, {"text": "远", "is_correct": false, "explanation": "语义：“远”指距离，“来的人很远”语义不通。"}], "explanations": {"少": "正确：“今天来的人很少”，表示人数不多。", "快": "语义：“快”描述速度，不能用来形容“来的人”的数量。", "重": "搭配：“重”说分量，不能修饰人的数量。", "远": "语义：“远”指距离，“来的人很远”语义不通。"}, "sentence_index": 0, "correct_answer": "少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张纸很少。", "explanation": "这里应该用〈薄〉。“少”表示数量不多，纸的厚薄要用“薄”。"}, {"text": "这篇文章很少。", "explanation": "这里应该用〈好〉。“少”说数量，文章的好坏要用“好”或“差”。"}, {"text": "这个湖很少。", "explanation": "这里应该用〈深〉。“少”说的是数量，不能用来形容湖的深浅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20786, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "少", "is_correct": true, "explanation": "正确答案：少（shǎo），意思是数量不多。"}, {"text": "稍", "is_correct": false, "explanation": "shāo（第一声）与 shǎo（第三声）声调不同，“稍”意思是稍微。"}, {"text": "嫂", "is_correct": false, "explanation": "sǎo 与 shǎo 声母不同（s 与 sh），“嫂”意思是嫂子。"}, {"text": "炒", "is_correct": false, "explanation": "chǎo 与 shǎo 声母不同（ch 与 sh），“炒”意思是翻炒。"}, {"text": "哨", "is_correct": false, "explanation": "shào（第四声）与 shǎo（第三声）声调不同，“哨”意思是口哨。"}], "explanations": {"少": "正确答案：少（shǎo），意思是数量不多。", "稍": "shāo（第一声）与 shǎo（第三声）声调不同，“稍”意思是稍微。", "嫂": "sǎo 与 shǎo 声母不同（s 与 sh），“嫂”意思是嫂子。", "炒": "chǎo 与 shǎo 声母不同（ch 与 sh），“炒”意思是翻炒。", "哨": "shào（第四声）与 shǎo（第三声）声调不同，“哨”意思是口哨。"}, "sentence_index": null, "correct_answer": "少"}, "level_3": {"options": [{"text": "少", "is_correct": true, "explanation": "正确：“这里的饭馆少”，表示饭馆数量不多。"}, {"text": "乱", "is_correct": false, "explanation": "语义：“乱”形容秩序混乱，不能修饰饭馆的数量。"}, {"text": "轻", "is_correct": false, "explanation": "搭配：“轻”说分量，不能修饰“饭馆”的数量。"}, {"text": "胖", "is_correct": false, "explanation": "搭配：“胖”形容人或动物的体形，不能形容“饭馆”。"}], "explanations": {"少": "正确：“这里的饭馆少”，表示饭馆数量不多。", "乱": "语义：“乱”形容秩序混乱，不能修饰饭馆的数量。", "轻": "搭配：“轻”说分量，不能修饰“饭馆”的数量。", "胖": "搭配：“胖”形容人或动物的体形，不能形容“饭馆”。"}, "sentence_index": 6, "correct_answer": "少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山很少。", "explanation": "这里应该用〈高〉。“少”只表示数量不多，不能用来形容山的高矮。"}, {"text": "这条路很少。", "explanation": "这里应该用〈长〉。“少”不能用来形容路的长短。"}, {"text": "这盏灯很少。", "explanation": "这里应该用〈亮〉。“少”只说数量，灯的明暗要用“亮”或“暗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年的雨少很。", "corrected_sentence": "今年的雨很少。", "error_description": "错误形式：“少很”；正确形式：“很少”。程度副词“很”要放在形容词“少”前面，不能放在后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的人很的少。", "corrected_sentence": "这家店的人很少。", "error_description": "错误形式：“很的少”；正确形式：“很少”。“很”后面不能加“的”，直接说“很少”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
