INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20788, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "土是地上我们踩着的、可以种花种菜的东西。", "primary_collocate": null, "pronunciation": "tǔ", "ipa": "tʰu˨˩˦", "syllable_count": 1, "sentences": [{"text": "我们脚下踩着的是土。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地的土很黑，可以种菜。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在院子里玩土。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪以前，农民把土翻了一遍。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土里能长出花和菜。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的土不好，花长不大。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用小铲子挖了一点土。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色的土上种着小树。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚂蚁住在土里。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的土有一种特别的味道。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一堆", "label": "量词"}, {"form": "一块", "label": "量词"}], "register": "中性", "sense_fingerprint": "脚下踩着的、能种花种菜的泥土", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '840fc245-6719-4ace-a4d0-78c0a43c1a8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20788, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "土", "is_correct": true, "explanation": "土（tǔ）指脚下的泥土，是正确答案。"}, {"text": "苦", "is_correct": false, "explanation": "k 与 t 声母不同，苦 kǔ 意思是味道苦。"}, {"text": "途", "is_correct": false, "explanation": "tú（第二声）与 tǔ（第三声）声调不同，途 tú 意思是道路。"}, {"text": "兔", "is_correct": false, "explanation": "tù（第四声）与 tǔ（第三声）声调不同，兔 tù 意思是兔子。"}, {"text": "秃", "is_correct": false, "explanation": "tū（第一声）与 tǔ（第三声）声调不同，秃 tū 意思是没有头发。"}], "explanations": {"土": "土（tǔ）指脚下的泥土，是正确答案。", "苦": "k 与 t 声母不同，苦 kǔ 意思是味道苦。", "途": "tú（第二声）与 tǔ（第三声）声调不同，途 tú 意思是道路。", "兔": "tù（第四声）与 tǔ（第三声）声调不同，兔 tù 意思是兔子。", "秃": "tū（第一声）与 tǔ（第三声）声调不同，秃 tū 意思是没有头发。"}, "sentence_index": null, "correct_answer": "土"}, "level_3": {"options": [{"text": "土", "is_correct": true, "explanation": "正确：我们脚下踩着的是泥土，符合句意。"}, {"text": "云", "is_correct": false, "explanation": "语义：云在空中，不在脚下，不能被踩着。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是空间，不是可以踩着的东西。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“踩着”的宾语要是有实体的地面，不说踩着空气。"}], "explanations": {"土": "正确：我们脚下踩着的是泥土，符合句意。", "云": "语义：云在空中，不在脚下，不能被踩着。", "房间": "语义：房间是空间，不是可以踩着的东西。", "空气": "搭配：“踩着”的宾语要是有实体的地面，不说踩着空气。"}, "sentence_index": 0, "correct_answer": "土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子是用土做的，很结实。", "explanation": "这里应该用〈木头〉。桌子通常用木头做，土不能用来做桌子。"}, {"text": "她穿的这条裙子是用土做的。", "explanation": "这里应该用〈丝绸〉。裙子常用丝绸、棉布等做，土不能做衣服。"}, {"text": "他戴着一顶用土做的帽子。", "explanation": "这里应该用〈草〉。帽子常用草、布等做，土做不出能戴的帽子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20788, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "土", "is_correct": true, "explanation": "土（tǔ）指脚下的泥土，是正确答案。"}, {"text": "堵", "is_correct": false, "explanation": "d 与 t 声母不同，堵 dǔ 意思是堵塞、堵车。"}, {"text": "补", "is_correct": false, "explanation": "b 与 t 声母不同，补 bǔ 意思是补充、修补。"}, {"text": "图", "is_correct": false, "explanation": "tú（第二声）与 tǔ（第三声）声调不同，图 tú 意思是图画、地图。"}, {"text": "突", "is_correct": false, "explanation": "tū（第一声）与 tǔ（第三声）声调不同，突 tū 意思是突然。"}], "explanations": {"土": "土（tǔ）指脚下的泥土，是正确答案。", "堵": "d 与 t 声母不同，堵 dǔ 意思是堵塞、堵车。", "补": "b 与 t 声母不同，补 bǔ 意思是补充、修补。", "图": "tú（第二声）与 tǔ（第三声）声调不同，图 tú 意思是图画、地图。", "突": "tū（第一声）与 tǔ（第三声）声调不同，突 tū 意思是突然。"}, "sentence_index": null, "correct_answer": "土"}, "level_3": {"options": [{"text": "土", "is_correct": true, "explanation": "正确：她用小铲子挖了一点泥土，符合句意。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事是抽象的内容，不能用铲子挖。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星在天上，不能用小铲子挖出来。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：“挖”的对象应是物质，不说挖笑声。"}], "explanations": {"土": "正确：她用小铲子挖了一点泥土，符合句意。", "故事": "语义：故事是抽象的内容，不能用铲子挖。", "星星": "语义：星星在天上，不能用小铲子挖出来。", "笑声": "搭配：“挖”的对象应是物质，不说挖笑声。"}, "sentence_index": 6, "correct_answer": "土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬天，我们要往炉子里添土。", "explanation": "这里应该用〈煤〉。炉子烧的是煤，土不能燃烧。"}, {"text": "做饼要先把土和好。", "explanation": "这里应该用〈面粉〉。做饼要用面粉加水和面，土不能用来做饼。"}, {"text": "冬天的湖面结了一层土。", "explanation": "这里应该用〈冰〉。湖面结的是冰，土不会结成冰层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在花园里挖了一根土。", "corrected_sentence": "她在花园里挖了一块土。", "error_description": "量词错误：土是散状的，成块挖出应用“块”，“根”用于细长的东西，不能用于土。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人在路边堆了一只土。", "corrected_sentence": "工人在路边堆了一堆土。", "error_description": "量词错误：土是散状的，应说“一堆土”，“只”不能用于土。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
