INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20792, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "表示“应该”，意思是做某件事是对的。", "primary_collocate": null, "pronunciation": "yīng", "ipa": "iŋ⁵⁵", "syllable_count": 1, "sentences": [{"text": "学生应按时完成作业。", "target_word": "应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路时应看红绿灯。", "target_word": "应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到老人，我们应让座。", "target_word": "应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "借了书就应按时还。", "target_word": "应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进门前应先敲门。", "target_word": "应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有问题应问老师。", "target_word": "应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在图书馆里应保持安静。", "target_word": "应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天会下雨，出门时应带伞。", "target_word": "应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友有困难，我们应帮助他。", "target_word": "应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐车时应系好安全带。", "target_word": "应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "应该", "label": "复合"}, {"form": "应当", "label": "复合"}, {"form": "不应", "label": "否定"}, {"form": "應", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "情态动词，表示应该做某事，多用于书面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fde7ad18-0ff2-44e3-844c-df7b9ce4ca9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20792, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "应", "is_correct": true, "explanation": "正确答案：应，表示理应做某事。"}, {"text": "迎", "is_correct": false, "explanation": "yíng（第二声）与 yīng（第一声）声调不同，意思是迎接。"}, {"text": "因", "is_correct": false, "explanation": "yīn 与 yīng 的韵母不同（in 与 ing），意思是因为。"}, {"text": "冰", "is_correct": false, "explanation": "bīng 与 yīng 的声母不同（b 与 y），意思是冰。"}], "explanations": {"应": "正确答案：应，表示理应做某事。", "迎": "yíng（第二声）与 yīng（第一声）声调不同，意思是迎接。", "因": "yīn 与 yīng 的韵母不同（in 与 ing），意思是因为。", "冰": "bīng 与 yīng 的声母不同（b 与 y），意思是冰。"}, "sentence_index": null, "correct_answer": "应"}, "level_3": {"options": [{"text": "应", "is_correct": true, "explanation": "正确答案：“应”表示理应如此，与“学生”和“按时完成作业”搭配自然。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”后要接宾语，“学生把按时完成作业”不通。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢”表示有胆量，不表示理应如此。"}, {"text": "太", "is_correct": false, "explanation": "语法：“太”是程度副词，不能这样修饰“按时完成作业”。"}], "explanations": {"应": "正确答案：“应”表示理应如此，与“学生”和“按时完成作业”搭配自然。", "把": "语法：“把”后要接宾语，“学生把按时完成作业”不通。", "敢": "语义：“敢”表示有胆量，不表示理应如此。", "太": "语法：“太”是程度副词，不能这样修饰“按时完成作业”。"}, "sentence_index": 0, "correct_answer": "应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书我应看完了，可以还给你。", "explanation": "这里应该用〈已经〉。“应”表示应该，不表示动作已经完成。"}, {"text": "这个菜很应吃。", "explanation": "这里应该用〈好〉。说菜的味道要说“很好吃”，“应”表示应该，不能这样用。"}, {"text": "我不应游泳，因为没学过。", "explanation": "这里应该用〈会〉。没学过是能力问题，要用“不会”，“不应”表示不应该。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20792, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "应", "is_correct": true, "explanation": "正确答案：应，表示理应做某事。"}, {"text": "影", "is_correct": false, "explanation": "yǐng（第三声）与 yīng（第一声）声调不同，意思是影子。"}, {"text": "硬", "is_correct": false, "explanation": "yìng（第四声）与 yīng（第一声）声调不同，意思是坚硬。"}, {"text": "音", "is_correct": false, "explanation": "yīn 与 yīng 的韵母不同（in 与 ing），意思是声音。"}], "explanations": {"应": "正确答案：应，表示理应做某事。", "影": "yǐng（第三声）与 yīng（第一声）声调不同，意思是影子。", "硬": "yìng（第四声）与 yīng（第一声）声调不同，意思是坚硬。", "音": "yīn 与 yīng 的韵母不同（in 与 ing），意思是声音。"}, "sentence_index": null, "correct_answer": "应"}, "level_3": {"options": [{"text": "应", "is_correct": true, "explanation": "正确答案：“应”表示理应如此，与“在图书馆里”和“保持安静”搭配自然。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”表示被动，“在图书馆里被保持安静”不通。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能直接修饰动词“保持”，句子不通。"}, {"text": "愿", "is_correct": false, "explanation": "语义：“愿”表示愿望，不表示理应如此。"}], "explanations": {"应": "正确答案：“应”表示理应如此，与“在图书馆里”和“保持安静”搭配自然。", "被": "语法：“被”表示被动，“在图书馆里被保持安静”不通。", "很": "语法：“很”是程度副词，不能直接修饰动词“保持”，句子不通。", "愿": "语义：“愿”表示愿望，不表示理应如此。"}, "sentence_index": 6, "correct_answer": "应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我正应吃饭，你等一下。", "explanation": "这里应该用〈在〉。表示正在进行要说“正在”，“应”表示应该。"}, {"text": "我很应喝茶，每天都喝。", "explanation": "这里应该用〈爱〉。表示喜好要说“很爱”，“应”表示应该，不表示喜欢。"}, {"text": "这道题太难，我不应做。", "explanation": "这里应该用〈会〉。题难做不出是能力问题，要用“不会”，“不应”表示不应该。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "进实验室前应了戴手套。", "corrected_sentence": "进实验室前应戴手套。", "error_description": "“应”是情态动词，后面不能加“了”。正确是“应戴手套”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上课时关应手机。", "corrected_sentence": "上课时应关手机。", "error_description": "“应”是情态动词，要放在动词前面，不能放在动词和宾语之间。正确是“应关手机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
