INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20794, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "黑色是一种颜色，像夜晚的天空或黑炭的样子。", "primary_collocate": null, "pronunciation": "hēi sè", "ipa": "xei˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "我最喜欢黑色的外套。", "target_word": "黑色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的天空是黑色的。", "target_word": "黑色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着一件黑色的大衣。", "target_word": "黑色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑色的猫坐在门口。", "target_word": "黑色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支笔的颜色是黑色。", "target_word": "黑色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑色和白色放在一起很好看。", "target_word": "黑色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一双黑色的鞋。", "target_word": "黑色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的头发是黑色的。", "target_word": "黑色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑色的车停在学校门口。", "target_word": "黑色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在白纸上用黑色的笔写了字。", "target_word": "黑色", "complexity_tier": "T3", "furigana": "lǎo shī zài bái zhǐ shàng yòng hēi sè de bǐ xiě le zì。", "sentence_source": "generated"}], "morphological_forms": [{"form": "黑色素", "label": "复合词"}, {"form": "黑色幽默", "label": "复合词"}], "register": "中性", "sense_fingerprint": "像夜空或黑炭的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578a203d-4358-4a88-a532-6eee781a844a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黑色", "is_correct": true, "explanation": "正确：“黑色”是颜色名词，修饰“外套”，与“我最喜欢……的外套”相符。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“蛋糕”是食物，“蛋糕的外套”说不通，不能修饰“外套”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是小物件，不能描述外套的颜色或特征，“钥匙的外套”不成立。"}, {"text": "拖把", "is_correct": false, "explanation": "语义：“拖把”是清洁工具，“拖把的外套”说不通，不能修饰“外套”。"}], "explanations": {"黑色": "正确：“黑色”是颜色名词，修饰“外套”，与“我最喜欢……的外套”相符。", "蛋糕": "语义：“蛋糕”是食物，“蛋糕的外套”说不通，不能修饰“外套”。", "钥匙": "语义：“钥匙”是小物件，不能描述外套的颜色或特征，“钥匙的外套”不成立。", "拖把": "语义：“拖把”是清洁工具，“拖把的外套”说不通，不能修饰“外套”。"}, "sentence_index": 0, "correct_answer": "黑色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只猫的毛很黑色。", "explanation": "这里应该用〈黑〉。“黑色”是颜色名词，不能受“很”修饰；表示程度时用形容词“黑”。"}, {"text": "他把头发黑色了。", "explanation": "“黑色”不能直接作动词，表示变成黑色应说“染黑”或“变黑”。"}, {"text": "这间屋子黑色得很。", "explanation": "“黑色”不能作补语，表示程度应说“黑得很”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黑色", "is_correct": true, "explanation": "正确：“一双黑色的鞋”表示颜色，与“我想买”的语境相符。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”描述湿度，不表示颜色，不能用来说想买的鞋的特征。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”多形容声音，不说“清脆的鞋”。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”形容声音，不能修饰“鞋”。"}], "explanations": {"黑色": "正确：“一双黑色的鞋”表示颜色，与“我想买”的语境相符。", "潮湿": "语义：“潮湿”描述湿度，不表示颜色，不能用来说想买的鞋的特征。", "清脆": "搭配：“清脆”多形容声音，不说“清脆的鞋”。", "嘹亮": "搭配：“嘹亮”形容声音，不能修饰“鞋”。"}, "sentence_index": 6, "correct_answer": "黑色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车非常黑色。", "explanation": "这里应该用〈黑〉。“黑色”是颜色名词，不能受“非常”修饰；表示程度要用形容词“黑”，说“这辆车非常黑”。"}, {"text": "老师在白纸上黑色写了字。", "explanation": "“黑色”作状语时不能直接修饰动词，应说“用黑色的笔写字”。"}, {"text": "他用笔把纸黑色了。", "explanation": "“黑色”是名词，不能作动词带宾语；应说“他用笔把纸涂黑了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想要一件很黑色的衣服。", "corrected_sentence": "他想要一件黑色的衣服。", "error_description": "“黑色”是颜色名词，不能受程度副词“很”修饰，应去掉“很”，说“一件黑色的衣服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双鞋子很黑色。", "corrected_sentence": "这双鞋子很黑。", "error_description": "“黑色”是颜色名词，不能受程度副词“很”修饰；表示程度要用形容词“黑”，说“很黑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
