INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20798, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "像动物抢食物一样，用很强硬的方式拿走别人的东西。", "primary_collocate": null, "pronunciation": "lüè duó xìng", "ipa": "lɥe˥˩ two˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "大公司对小店的做法很有掠夺性。", "target_word": "掠夺性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做生意时很有掠夺性，总想抢别人的客户。", "target_word": "掠夺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种掠夺性的行为不对。", "target_word": "掠夺性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板的掠夺性手段让工人很怕。", "target_word": "掠夺性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "强盗的掠夺性很明显。", "target_word": "掠夺性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们的掠夺性做法伤害了农民。", "target_word": "掠夺性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "狼的掠夺性让羊群不安。", "target_word": "掠夺性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店用掠夺性的低价赶走别的店。", "target_word": "掠夺性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "抢别人的玩具是掠夺性行为。", "target_word": "掠夺性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王的军队有很强的掠夺性。", "target_word": "掠夺性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "掠奪性", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "强硬地抢走别人东西的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8504da67-cb87-4591-9bab-b889bffaad51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掠夺性", "is_correct": true, "explanation": "正确。“很有掠夺性”形容做法强硬地拿走别人的东西，与句意相合。"}, {"text": "慈善性", "is_correct": false, "explanation": "语义：“慈善”是帮助他人，与大公司排挤小店的做法相矛盾。"}, {"text": "幽默性", "is_correct": false, "explanation": "搭配：“幽默”多形容人或言谈，不说做法很幽默性。"}, {"text": "节能性", "is_correct": false, "explanation": "语义：“节能”指节省能源，与抢走别人东西的做法无关。"}], "explanations": {"掠夺性": "正确。“很有掠夺性”形容做法强硬地拿走别人的东西，与句意相合。", "慈善性": "语义：“慈善”是帮助他人，与大公司排挤小店的做法相矛盾。", "幽默性": "搭配：“幽默”多形容人或言谈，不说做法很幽默性。", "节能性": "语义：“节能”指节省能源，与抢走别人东西的做法无关。"}, "sentence_index": 0, "correct_answer": "掠夺性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对穷人很有掠夺性，常常把自己的钱送给别人。", "explanation": "这里应该用〈慷慨〉。掠夺性指强硬地拿走别人的东西，把钱送给穷人应说“慷慨”。"}, {"text": "这位老师的教法很有掠夺性，学生都很喜欢。", "explanation": "这里应该用〈温和〉。掠夺性指强硬地夺取，形容教法应说“温和”。"}, {"text": "他在饭桌上很有掠夺性，总是先给别人夹菜。", "explanation": "这里应该用〈谦让〉。掠夺性指强硬地拿走别人的东西，先给别人夹菜应说“谦让”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掠夺性", "is_correct": true, "explanation": "正确。狼的掠夺性使羊群害怕不安，与句意相合。"}, {"text": "温顺性", "is_correct": false, "explanation": "语义：温顺的狼不会让羊群不安，与句意矛盾。"}, {"text": "节俭性", "is_correct": false, "explanation": "搭配：“节俭”多形容人的生活习惯，不说狼的节俭性。"}, {"text": "礼貌性", "is_correct": false, "explanation": "语义：礼貌的狼不会让羊群不安，与句意相矛盾。"}], "explanations": {"掠夺性": "正确。狼的掠夺性使羊群害怕不安，与句意相合。", "温顺性": "语义：温顺的狼不会让羊群不安，与句意矛盾。", "节俭性": "搭配：“节俭”多形容人的生活习惯，不说狼的节俭性。", "礼貌性": "语义：礼貌的狼不会让羊群不安，与句意相矛盾。"}, "sentence_index": 6, "correct_answer": "掠夺性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给孩子盖被子时很有掠夺性，动作特别轻。", "explanation": "这里应该用〈轻柔〉。掠夺性指像动物抢食一样强硬地拿走别人的东西，形容盖被子的动作应说“轻柔”。"}, {"text": "这位店员很有掠夺性，总是主动帮顾客找东西。", "explanation": "这里应该用〈热情〉。掠夺性指强硬地拿走别人的东西，形容店员主动帮忙应说“热情”。"}, {"text": "他的小狗很有掠夺性，连主人的枕头都不抢。", "explanation": "这里应该用〈温顺〉。掠夺性指强硬地抢夺，形容小狗应说“温顺”，连枕头都不抢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个商人的手段非常是掠夺性。", "corrected_sentence": "那个商人的手段非常有掠夺性。", "error_description": "错误在于“非常”后面的“是”。应为“有”，应说“非常有掠夺性”；“是”不能用来描述手段的程度。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个帮派靠掠夺性地手段抢走了商店的货物。", "corrected_sentence": "那个帮派靠掠夺性的手段抢走了商店的货物。", "error_description": "错误在于“掠夺性”后面的“地”。“掠夺性”修饰名词“手段”，应用“的”；用“地”会把它当成副词，与后面的名词搭配不上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
