INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20800, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "堆肥就是把树叶、果皮等垃圾堆在一起，让它们变成肥料。", "primary_collocate": null, "pronunciation": "duī féi", "ipa": "tuei˥ fei˧˥", "syllable_count": 2, "sentences": [{"text": "爷爷用树叶做了堆肥。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把果皮放进堆肥里。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆肥能让花园里的菜长得更好。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做堆肥要把树叶和果皮放在一起。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这袋堆肥是邻居送给我的。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆肥需要几个月才能做好。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在地里撒了一些堆肥。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天把剩菜倒进堆肥里。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用堆肥种花，花开得很漂亮。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的堆肥闻起来没有臭味。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆肥箱", "label": "复合"}, {"form": "一袋堆肥", "label": "量词"}], "register": "中性", "sense_fingerprint": "垃圾堆放后变成的肥料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bacc239c-df87-4c0c-a87d-ec7f9978f1b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20800, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "堆肥", "is_correct": true, "explanation": "“堆肥”是把树叶、果皮等垃圾堆放发酵后得到的肥料，符合“用树叶做了”的句意。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：树叶不能做成雨水，句意不通。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：树叶不能包成饺子，也不能食用，句意不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：树叶不能做成手机，句意不通。"}], "explanations": {"堆肥": "“堆肥”是把树叶、果皮等垃圾堆放发酵后得到的肥料，符合“用树叶做了”的句意。", "雨水": "语义：树叶不能做成雨水，句意不通。", "饺子": "语义：树叶不能包成饺子，也不能食用，句意不通。", "手机": "语义：树叶不能做成手机，句意不通。"}, "sentence_index": 0, "correct_answer": "堆肥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农场每天用堆肥喂猪。", "explanation": "这里应该用〈饲料〉。堆肥是给土地用的肥料，不能拿来喂猪；喂猪要用饲料。"}, {"text": "工人们用水泥和堆肥砌墙。", "explanation": "这里应该用〈沙子〉。堆肥是肥料，不能用来砌墙；砌墙要用水泥和沙子。"}, {"text": "他每天用堆肥擦脸。", "explanation": "这里应该用〈毛巾〉。堆肥是肥料，不能用来擦脸；擦脸要用毛巾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "堆肥", "is_correct": true, "explanation": "“堆肥”是可以撒在地里的肥料，符合“农民在地里撒了一些”的句意。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不能撒在地里，句意不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能撒在地里，句意不通。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“撒”一般用于颗粒、粉末或种子，不说撒“书”。"}], "explanations": {"堆肥": "“堆肥”是可以撒在地里的肥料，符合“农民在地里撒了一些”的句意。", "电视": "语义：电视不能撒在地里，句意不通。", "汽车": "语义：汽车不能撒在地里，句意不通。", "书": "搭配：“撒”一般用于颗粒、粉末或种子，不说撒“书”。"}, "sentence_index": 6, "correct_answer": "堆肥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗堆肥很好吃，大家都抢着吃。", "explanation": "这里应该用〈饭〉。堆肥是给土地用的肥料，不能吃，不能说“一碗堆肥很好吃”。"}, {"text": "浴室里放着一块堆肥，用来洗手。", "explanation": "这里应该用〈肥皂〉。堆肥是肥料，不能用来洗手，洗手要用肥皂。"}, {"text": "他每天早上用堆肥刷牙。", "explanation": "这里应该用〈牙膏〉。堆肥是肥料，不能用来刷牙；刷牙要用牙膏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里有一条堆肥。", "corrected_sentence": "院子里有一堆堆肥。", "error_description": "错误：量词用错。“条”用于细长的东西，堆肥成堆，应用“堆”。应说“一堆堆肥”，不能说“一条堆肥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "邻居送给我一张堆肥。", "corrected_sentence": "邻居送给我一袋堆肥。", "error_description": "错误：量词用错。“张”用于纸、桌子等平面的东西，堆肥装在袋子里，应说“一袋堆肥”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
