INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20802, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "植物就是花、草、树等靠光合作用生长、不能自由移动的生物。", "primary_collocate": null, "pronunciation": "zhí wù", "ipa": "ʈʂʅ˧˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "花、草、树都是植物。", "target_word": "植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物需要水和阳光才能长大。", "target_word": "植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家阳台上有很多植物。", "target_word": "植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种植物只在热带生长。", "target_word": "植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去公园散步，欣赏那里的植物。", "target_word": "植物", "complexity_tier": "T3", "furigana": "zhōu mò wǒ men qù gōng yuán sàn bù, xīn shǎng nà lǐ de zhí wù", "sentence_source": "generated"}, {"text": "他每天给房间里的植物浇水。", "target_word": "植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的植物很少。", "target_word": "植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们画一种自己喜欢的植物。", "target_word": "植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种植物有毒，不要用手去摸。", "target_word": "植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天太冷，很多植物都不再长了。", "target_word": "植物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "植物园", "label": "复合"}, {"form": "植物油", "label": "复合"}], "register": "中性", "sense_fingerprint": "花、草、树等会生长的生物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4208b8-fa3e-439a-94ca-4737d9934ac5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20802, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "植物", "is_correct": true, "explanation": "正确答案。花、草、树都属于“植物”这一类。"}, {"text": "动物", "is_correct": false, "explanation": "语义：花、草、树不属于动物，“都是动物”与句子的线索矛盾。"}, {"text": "金属", "is_correct": false, "explanation": "语义：花、草、树不是金属，“都是金属”不成立。"}, {"text": "工具", "is_correct": false, "explanation": "搭配：“都是”后要接能归为同一类的词，花、草、树不能归为“工具”。"}], "explanations": {"植物": "正确答案。花、草、树都属于“植物”这一类。", "动物": "语义：花、草、树不属于动物，“都是动物”与句子的线索矛盾。", "金属": "语义：花、草、树不是金属，“都是金属”不成立。", "工具": "搭配：“都是”后要接能归为同一类的词，花、草、树不能归为“工具”。"}, "sentence_index": 0, "correct_answer": "植物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这株植物叫了一整夜，吵得大家睡不着。", "explanation": "这里应该用〈动物〉。植物不会叫，会叫的是动物。"}, {"text": "这种植物每年秋天都会南飞。", "explanation": "这里应该用〈鸟〉。植物不会迁飞，每年南飞的是鸟。"}, {"text": "这株植物每天在工厂里干活。", "explanation": "这里应该用〈工人〉。植物不会上班干活，在工厂干活的是工人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20802, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "植物", "is_correct": true, "explanation": "正确答案。沙漠里的植物可以很少，“很少”可以修饰“植物”。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙漠里到处都是沙子，“沙漠里的沙子很少”与常识矛盾。"}, {"text": "心跳", "is_correct": false, "explanation": "搭配：“心跳”不是能被“很少”修饰的事物，句子说不通。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：沙漠里阳光充足，“沙漠里的阳光很少”与常识矛盾。"}], "explanations": {"植物": "正确答案。沙漠里的植物可以很少，“很少”可以修饰“植物”。", "沙子": "语义：沙漠里到处都是沙子，“沙漠里的沙子很少”与常识矛盾。", "心跳": "搭配：“心跳”不是能被“很少”修饰的事物，句子说不通。", "阳光": "语义：沙漠里阳光充足，“沙漠里的阳光很少”与常识矛盾。"}, "sentence_index": 6, "correct_answer": "植物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种植物每天要上学。", "explanation": "这里应该用〈学生〉。植物不会上学，上学的是学生。"}, {"text": "这种植物每天要喝很多牛奶。", "explanation": "这里应该用〈小猫〉。植物靠根从土里吸收水分和养料，喝牛奶的是小猫这样的动物。"}, {"text": "这种植物下个月就要结婚了。", "explanation": "这里应该用〈人〉。植物不会结婚，结婚的是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只植物需要很多阳光。", "corrected_sentence": "这种植物需要很多阳光。", "error_description": "量词错误：“植物”要用“种”或“株”，“只”多用于动物。错误形式是“这只植物”，正确形式是“这种植物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "阳台上的植物了长得很好。", "corrected_sentence": "阳台上的植物长得很好。", "error_description": "了的位置错误：“了”不能放在主语“植物”和动词“长”之间，应删去。错误形式是“植物了长得很好”，正确形式是“植物长得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
