INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20804, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "绿色是像树叶和草那样的颜色。", "primary_collocate": null, "pronunciation": "lǜ sè", "ipa": "ly⁵¹ sɤ⁵¹", "syllable_count": 2, "sentences": [{"text": "我最喜欢的颜色是绿色。", "target_word": "绿色", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天到了，山上都是绿色。", "target_word": "绿色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她穿了一件绿色的裙子。", "target_word": "绿色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树叶是绿色的。", "target_word": "绿色", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "红色和黄色放在一起，再加一点绿色。", "target_word": "绿色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这张纸涂成绿色。", "target_word": "绿色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想要红色的，还是绿色的？", "target_word": "绿色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "绿色的草地上有很多花。", "target_word": "绿色", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天窗外全是绿色，很好看。", "target_word": "绿色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子用绿色画了一棵大树。", "target_word": "绿色", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：像树叶和草的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083b86a6-9f7b-4d1f-ab6f-174ff48943e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20804, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绿色", "is_correct": true, "explanation": "正确：绿色是颜色名词，正好回答“我最喜欢的颜色是什么”。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”指物体的外形，不是颜色，不能回答“最喜欢的颜色”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”属于味觉，与颜色无关，句子说不通。"}, {"text": "色彩", "is_correct": false, "explanation": "搭配：“色彩”是颜色的总称，“颜色是色彩”同义重复，不能具体回答这个问题。"}], "explanations": {"绿色": "正确：绿色是颜色名词，正好回答“我最喜欢的颜色是什么”。", "形状": "语义：“形状”指物体的外形，不是颜色，不能回答“最喜欢的颜色”。", "味道": "语义：“味道”属于味觉，与颜色无关，句子说不通。", "色彩": "搭配：“色彩”是颜色的总称，“颜色是色彩”同义重复，不能具体回答这个问题。"}, "sentence_index": 0, "correct_answer": "绿色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校去年绿色了操场周围的一大片土地。", "explanation": "这里应该用〈绿化〉。绿色是颜色词，不能当动词使用，表示使土地变绿要说“绿化”。"}, {"text": "我最喜欢这只绿色。", "explanation": "这里应该用〈种〉。绿色指颜色时，量词用“种”，不能用“只”。"}, {"text": "他刚进公司，还很绿色，什么都不懂。", "explanation": "此处“绿色”借指资历浅、缺乏经验，是比喻用法，不是指颜色。这里应该用〈青涩〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绿色", "is_correct": true, "explanation": "正确：与“红色的”并列，同为颜色的选择，符合语境。"}, {"text": "纸", "is_correct": false, "explanation": "语义：“纸”不是颜色，不能与“红色的”并列作选择。"}, {"text": "风", "is_correct": false, "explanation": "语义：“风”不是颜色，句子无法理解为颜色的选择。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”是颜色的总称，与具体颜色“红色的”并列重复，不能这样对举。"}], "explanations": {"绿色": "正确：与“红色的”并列，同为颜色的选择，符合语境。", "纸": "语义：“纸”不是颜色，不能与“红色的”并列作选择。", "风": "语义：“风”不是颜色，句子无法理解为颜色的选择。", "颜色": "搭配：“颜色”是颜色的总称，与具体颜色“红色的”并列重复，不能这样对举。"}, "sentence_index": 6, "correct_answer": "绿色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子用一个绿色画了一棵大树。", "explanation": "这里应该用〈种〉。绿色指颜色时，量词用“种”，不能用“个”。"}, {"text": "经理终于给了我们绿色，可以开始做这个项目。", "explanation": "此处“绿色”借指准许开展，是比喻用法，不是指颜色；这里应该用〈绿灯〉。"}, {"text": "他的心情很绿色，像春天一样。", "explanation": "此处“绿色”借指心情舒展、充满希望，是比喻用法，不是指颜色；这里应该用〈明朗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只绿色很清爽。", "corrected_sentence": "这种绿色很清爽。", "error_description": "“绿色”作颜色名词时，量词应用“种”，不能用“只”。错误形式是“这只绿色”，正确形式是“这种绿色”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把裙子绿色了。", "corrected_sentence": "他把裙子染成绿色了。", "error_description": "“绿色”作颜色名词，不能直接当动词用。错误形式“把裙子绿色了”，应说“把裙子染成绿色了”，表示使裙子变成绿色。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20806, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低效", "is_correct": true, "explanation": "“高效”与“低效”是反义词：高效指效率高，低效指效率低。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“高效”没有反义关系，“漂亮”形容外貌。"}, {"text": "柔软", "is_correct": false, "explanation": "与“高效”没有反义关系，“柔软”形容质地。"}, {"text": "清楚", "is_correct": false, "explanation": "与“高效”没有反义关系，“清楚”形容明白或清晰的程度。"}], "correct_answer": "低效", "explanations": {"低效": "“高效”与“低效”是反义词：高效指效率高，低效指效率低。", "漂亮": "与“高效”没有反义关系，“漂亮”形容外貌。", "柔软": "与“高效”没有反义关系，“柔软”形容质地。", "清楚": "与“高效”没有反义关系，“清楚”形容明白或清晰的程度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20806, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低效", "is_correct": true, "explanation": "“高效”与“低效”是反义词：高效指效率高，低效指效率低。"}, {"text": "明亮", "is_correct": false, "explanation": "与“高效”没有反义关系，“明亮”形容光线强或色彩鲜艳。"}, {"text": "干净", "is_correct": false, "explanation": "与“高效”没有反义关系，“干净”形容洁净的状态。"}, {"text": "窄", "is_correct": false, "explanation": "与“高效”没有反义关系，“窄”形容宽度小。"}], "correct_answer": "低效", "explanations": {"低效": "“高效”与“低效”是反义词：高效指效率高，低效指效率低。", "明亮": "与“高效”没有反义关系，“明亮”形容光线强或色彩鲜艳。", "干净": "与“高效”没有反义关系，“干净”形容洁净的状态。", "窄": "与“高效”没有反义关系，“窄”形容宽度小。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20806, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事快，效果好。", "primary_collocate": null, "pronunciation": "gāo xiào", "ipa": "kɑʊ̯˥ ɕiɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他工作很高效，一天就做完了。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新方法非常高效。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会要高效，不要说太多没用的话。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一个很高效的老师。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用这台机器洗衣服又快又干净，真高效。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要一种高效的学习方法。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家合作得很高效，两小时就搞定了。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高效的人会先做重要的事。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的服务很高效，十分钟就办好了。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡得很好，所以白天工作特别高效。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高效率", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事速度快、效果好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245410d8-ef7c-4e0b-b864-35d4e472cd06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20806, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高效", "is_correct": true, "explanation": "“工作很高效”说做事效率高，与“一天就做完了”前后一致。"}, {"text": "慢", "is_correct": false, "explanation": "语义：工作很慢却一天就做完了，前后矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“工作”不能用“漂亮”来形容。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：工作不能说“便宜”，与句意不通。"}], "explanations": {"高效": "“工作很高效”说做事效率高，与“一天就做完了”前后一致。", "慢": "语义：工作很慢却一天就做完了，前后矛盾。", "漂亮": "搭配：“工作”不能用“漂亮”来形容。", "便宜": "语义：工作不能说“便宜”，与句意不通。"}, "sentence_index": 0, "correct_answer": "高效"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "消防员高效跑进了火场。", "explanation": "这里应该用〈迅速〉。高效侧重做事的效率和效果，不用来形容跑动的速度。"}, {"text": "他的道歉很高效，我们和好了。", "explanation": "这里应该用〈有效〉。高效指做事快、效果好，不能用来形容道歉的作用。"}, {"text": "小狗很高效地跑回了家。", "explanation": "这里应该用〈快〉。高效强调做事的效率，形容跑动的速度要用“快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高效", "is_correct": true, "explanation": "“合作得很高效”说合作的效率高，与“两小时就搞定了”一致。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“合作”不能用“甜”来形容。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：合作没有高矮之分，不能说“合作得很矮”。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“合作”不能用“咸”来形容。"}], "explanations": {"高效": "“合作得很高效”说合作的效率高，与“两小时就搞定了”一致。", "甜": "搭配：“合作”不能用“甜”来形容。", "矮": "体貌：合作没有高矮之分，不能说“合作得很矮”。", "咸": "搭配：“合作”不能用“咸”来形容。"}, "sentence_index": 6, "correct_answer": "高效"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他身手高效，几下就爬上了树。", "explanation": "这里应该用〈敏捷〉。高效指做事的效率，不用来形容身手或动作的灵活。"}, {"text": "她的步子很高效，像跳舞一样。", "explanation": "这里应该用〈轻快〉。高效不用来形容步子或走路的样子。"}, {"text": "这只小猫的毛很高效，摸上去很舒服。", "explanation": "这里应该用〈柔软〉。高效形容做事的效率，不用来形容毛的质地，应说“柔软”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他高效的完成了任务。", "corrected_sentence": "他高效地完成了任务。", "error_description": "“的”“地”混用：“高效”作状语修饰动词“完成”，后面要加“地”，应说“高效地完成”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学习很得高效。", "corrected_sentence": "他学习得很高效。", "error_description": "补语位置错误：补语标记“得”要紧跟动词，应说“学习得很高效”，不能说“学习很得高效”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
