INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20810, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "棕色像泥土和树干一样的颜色。", "primary_collocate": null, "pronunciation": "zōng sè", "ipa": "tsʊŋ˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "泥土是棕色的。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树的树干是棕色的。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿了一件棕色的大衣。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小马有棕色的毛和白色的腿。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想用棕色的笔画树干。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水很脏，看起来是棕色的。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双棕色的鞋子很好看。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他戴着一顶棕色的帽子。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶加了咖啡，变成了棕色。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只熊的毛是棕色，不是黑色。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "深棕色", "label": "复合"}, {"form": "浅棕色", "label": "复合"}], "register": "中性", "sense_fingerprint": "棕色:名词:像泥土和树干的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f6b3972-a8a9-4c30-a116-104a85e3fab6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20810, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "棕色", "is_correct": true, "explanation": "正确：泥土的颜色是棕色，这里应填“棕色”。"}, {"text": "蓝色", "is_correct": false, "explanation": "语义：泥土不是蓝色的，“泥土是蓝色的”与常识不符。"}, {"text": "粉色", "is_correct": false, "explanation": "语义：泥土通常不是粉色的，“泥土是粉色的”与句意不符。"}, {"text": "透明", "is_correct": false, "explanation": "语义：泥土通常不是透明的，“泥土是透明的”与常识不符。"}], "explanations": {"棕色": "正确：泥土的颜色是棕色，这里应填“棕色”。", "蓝色": "语义：泥土不是蓝色的，“泥土是蓝色的”与常识不符。", "粉色": "语义：泥土通常不是粉色的，“泥土是粉色的”与句意不符。", "透明": "语义：泥土通常不是透明的，“泥土是透明的”与常识不符。"}, "sentence_index": 0, "correct_answer": "棕色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给我倒了一杯棕色。", "explanation": "这里应该用〈牛奶〉。棕色是颜色，不能当作饮料的名称。"}, {"text": "他的性格很棕色。", "explanation": "这里应该用〈开朗〉。形容性格要说“开朗”等词，棕色只表示颜色，不能用来形容性格。"}, {"text": "这棵树的棕色很高。", "explanation": "这里应该用〈高度〉。说树的高矮要用“高度”，棕色只表示颜色，不能用来说明高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "棕色", "is_correct": true, "explanation": "正确：“这双棕色的鞋子很好看”，棕色修饰鞋子的颜色，这里应填“棕色”。"}, {"text": "泥土", "is_correct": false, "explanation": "语义：鞋子不会由泥土构成，“泥土的鞋子”与句中的“很好看”不搭。"}, {"text": "液体", "is_correct": false, "explanation": "语义：鞋子不是液体制品，“液体的鞋子”句意不通。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：鞋子不是音乐，“这双音乐的鞋子”句意不通。"}], "explanations": {"棕色": "正确：“这双棕色的鞋子很好看”，棕色修饰鞋子的颜色，这里应填“棕色”。", "泥土": "语义：鞋子不会由泥土构成，“泥土的鞋子”与句中的“很好看”不搭。", "液体": "语义：鞋子不是液体制品，“液体的鞋子”句意不通。", "音乐": "语义：鞋子不是音乐，“这双音乐的鞋子”句意不通。"}, "sentence_index": 6, "correct_answer": "棕色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座雕像是用棕色做的。", "explanation": "这里应该用〈石头〉。棕色是颜色，不能说明雕像是用什么材料做成的。"}, {"text": "这首曲子的棕色很响亮。", "explanation": "这里应该用〈音量〉。形容声音的大小要说“音量”，棕色只表示颜色，不能用来形容声音。"}, {"text": "这碗面的棕色很香。", "explanation": "这里应该用〈香味〉。形容食物的气味要说“香味”，棕色只表示颜色，不能用来形容气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这盒颜料里有一只棕色。", "corrected_sentence": "这盒颜料里有一种棕色。", "error_description": "量词错误：“棕色”作颜色名词时用量词“种”，“只”只用于动物等单个个体，不能用来计量颜色。正确应为“一种棕色”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把旧椅子刷了成棕色。", "corrected_sentence": "他把旧椅子刷成了棕色。", "error_description": "补语结构错误：“刷成”是结果补语，“了”应放在“成”之后，不能拆开写成“刷了成”。正确应为“刷成了棕色”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20814, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失衡", "is_correct": true, "explanation": "“平衡”与“失衡”是反义词：平衡指保持稳定，失衡指失去稳定。"}, {"text": "桌子", "is_correct": false, "explanation": "与“平衡”没有反义关系，“桌子”是家具。"}, {"text": "河流", "is_correct": false, "explanation": "与“平衡”没有反义关系，“河流”是地理事物。"}, {"text": "房屋", "is_correct": false, "explanation": "与“平衡”没有反义关系，“房屋”指建筑物。"}], "correct_answer": "失衡", "explanations": {"失衡": "“平衡”与“失衡”是反义词：平衡指保持稳定，失衡指失去稳定。", "桌子": "与“平衡”没有反义关系，“桌子”是家具。", "河流": "与“平衡”没有反义关系，“河流”是地理事物。", "房屋": "与“平衡”没有反义关系，“房屋”指建筑物。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20814, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失衡", "is_correct": true, "explanation": "“平衡”与“失衡”是反义词：平衡指保持稳定，失衡指失去稳定。"}, {"text": "窗户", "is_correct": false, "explanation": "与“平衡”没有反义关系，“窗户”是建筑部件。"}, {"text": "书包", "is_correct": false, "explanation": "与“平衡”没有反义关系，“书包”是装东西的用具。"}, {"text": "黑板", "is_correct": false, "explanation": "与“平衡”没有反义关系，“黑板”是教学用具。"}], "correct_answer": "失衡", "explanations": {"失衡": "“平衡”与“失衡”是反义词：平衡指保持稳定，失衡指失去稳定。", "窗户": "与“平衡”没有反义关系，“窗户”是建筑部件。", "书包": "与“平衡”没有反义关系，“书包”是装东西的用具。", "黑板": "与“平衡”没有反义关系，“黑板”是教学用具。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20814, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物体或身体保持稳定、不倒下的状态。", "primary_collocate": null, "pronunciation": "píng héng", "ipa": "pʰiŋ˧˥ xɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小孩骑自行车时很难保持平衡。", "target_word": "平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他脚下一滑，失去了平衡。", "target_word": "平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走在细木头上要保持平衡。", "target_word": "平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她张开双手，帮自己保持平衡。", "target_word": "平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船太小，人一多就会失去平衡。", "target_word": "平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人走路慢，是为了不失去平衡。", "target_word": "平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂技演员头上顶着碗，却不失去平衡。", "target_word": "平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手扶着墙，才找回平衡。", "target_word": "平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪地很滑，我走几步就失去平衡。", "target_word": "平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在摇晃的车上，要抓紧扶手保持平衡。", "target_word": "平衡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平衡感", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体或身体保持稳定、不倒下的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245410d8-ef7c-4e0b-b864-35d4e472cd06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20814, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平衡", "is_correct": true, "explanation": "“保持平衡”是常见搭配，指骑车时身体不倒，句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以“保持”的状态，“保持石头”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“保持”不能与“年龄”组合，不说“保持年龄”。"}, {"text": "毛巾", "is_correct": false, "explanation": "语义：毛巾不能被“保持”，与骑自行车的语境无关。"}], "explanations": {"平衡": "“保持平衡”是常见搭配，指骑车时身体不倒，句意通顺。", "石头": "语义：石头不是可以“保持”的状态，“保持石头”说不通。", "年龄": "搭配：“保持”不能与“年龄”组合，不说“保持年龄”。", "毛巾": "语义：毛巾不能被“保持”，与骑自行车的语境无关。"}, "sentence_index": 0, "correct_answer": "平衡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用平衡把书架修好了。", "explanation": "这里应该用〈修理〉。平衡指物体或身体保持稳定、不倒下的状态，不能表示修理的动作。"}, {"text": "他去超市买平衡。", "explanation": "这里应该用〈东西〉。平衡指状态，是抽象的，不是能买的东西。"}, {"text": "这盆花很平衡，一天就开了三朵。", "explanation": "这里应该用〈茂盛〉。平衡指保持不倒的状态，形容植物生长旺盛要用“茂盛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平衡", "is_correct": true, "explanation": "“不失去平衡”指杂技演员保持身体稳定，句意通顺。"}, {"text": "影子", "is_correct": false, "explanation": "语义：顶碗表演的语境中，“影子”与保持稳定无关，“不失去影子”说不通。"}, {"text": "性别", "is_correct": false, "explanation": "语义：“性别”不能被“失去”，与表演的语境不符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：顶碗表演不会改变身高，不能说“不失去身高”。"}], "explanations": {"平衡": "“不失去平衡”指杂技演员保持身体稳定，句意通顺。", "影子": "语义：顶碗表演的语境中，“影子”与保持稳定无关，“不失去影子”说不通。", "性别": "语义：“性别”不能被“失去”，与表演的语境不符。", "身高": "体貌：顶碗表演不会改变身高，不能说“不失去身高”。"}, "sentence_index": 6, "correct_answer": "平衡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他三个月平衡了十公斤体重。", "explanation": "这里应该用〈减轻〉。“平衡”指保持不倒的状态，表示体重减少要用“减轻”。"}, {"text": "他把平衡放进了书包。", "explanation": "这里应该用〈东西〉。平衡指保持不倒的状态，是抽象的，不能像物品一样放进书包。"}, {"text": "这座房子的墙很平衡，颜色也很漂亮。", "explanation": "这里应该用〈结实〉。平衡指保持不倒的状态，形容墙的坚固要用“结实”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小猫摔倒后，很快又找了回平衡。", "corrected_sentence": "小猫摔倒后，很快又找回了平衡。", "error_description": "补语位置错误：“找回”是动补结构，“回”要紧跟“找”，应说“找回了平衡”，不能说“找了回平衡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他双手张开，努力打开平衡。", "corrected_sentence": "他双手张开，努力保持平衡。", "error_description": "动词搭配错误：“平衡”常和“保持”搭配，不能说“打开平衡”。应说“保持平衡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
