INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20816, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生物身体里发生的化学变化。", "primary_collocate": null, "pronunciation": "shēng huà", "ipa": "ʂɤŋ˥ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "身体里每时每刻都有生化反应。", "target_word": "生化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭后，食物在胃里发生生化变化。", "target_word": "生化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植物晒太阳时，叶子里有生化反应。", "target_word": "生化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发烧会改变身体里的生化反应。", "target_word": "生化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酒喝多了，肝脏的生化反应会变慢。", "target_word": "生化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "种子发芽时，里面有复杂的生化变化。", "target_word": "生化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生化反应让我们的身体有力气。", "target_word": "生化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种药会影响细胞里的生化反应。", "target_word": "生化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天小动物睡觉，身体的生化反应变慢了。", "target_word": "生化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虫子长大，要靠身体里的生化变化。", "target_word": "生化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "生化反应", "label": "复合"}, {"form": "生化变化", "label": "复合"}], "register": "中性", "sense_fingerprint": "生物体内发生的化学变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfd7af12-1a73-462f-9399-277b88dbbcd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20816, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生化", "is_correct": true, "explanation": "正确：“生化反应”指生物体内的化学反应，与句意相符。"}, {"text": "文学", "is_correct": false, "explanation": "语义：身体里发生的是化学反应，“文学”与此无关。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：“反应”前一般接化学、生理、过敏等，不接“数学”。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：身体内的变化不是音乐，句意不通。"}], "explanations": {"生化": "正确：“生化反应”指生物体内的化学反应，与句意相符。", "文学": "语义：身体里发生的是化学反应，“文学”与此无关。", "数学": "搭配：“反应”前一般接化学、生理、过敏等，不接“数学”。", "音乐": "语义：身体内的变化不是音乐，句意不通。"}, "sentence_index": 0, "correct_answer": "生化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家研发了生化武器。", "explanation": "此处的“生化”修饰“武器”，指生化武器，不指生物体内的化学变化。"}, {"text": "这杯水里发生了生化变化。", "explanation": "这里应该用〈化学〉。生化专指生物体内的化学变化，水不是生物体，应说化学变化。"}, {"text": "他每天跑步，生化很健康。", "explanation": "这里应该用〈生活〉。“生活很健康”说日常习惯，“生化”不能描述日常习惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生化", "is_correct": true, "explanation": "正确：“生化反应”指体内的化学反应，能为身体提供能量，与句意相符。"}, {"text": "政治", "is_correct": false, "explanation": "语义：句子说的是身体的能量来源，“政治”与此无关。"}, {"text": "交通", "is_correct": false, "explanation": "搭配：“反应”前接化学、生理等，不说“交通反应”。"}, {"text": "股票", "is_correct": false, "explanation": "语义：“股票反应”指市场波动，与身体有力气无关。"}], "explanations": {"生化": "正确：“生化反应”指体内的化学反应，能为身体提供能量，与句意相符。", "政治": "语义：句子说的是身体的能量来源，“政治”与此无关。", "交通": "搭配：“反应”前接化学、生理等，不说“交通反应”。", "股票": "语义：“股票反应”指市场波动，与身体有力气无关。"}, "sentence_index": 6, "correct_answer": "生化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "植物需要阳光才能生化。", "explanation": "这里应该用〈生长〉。植物长大用生长；生化不是“长大”的意思。"}, {"text": "医院买了一台新的生化分析仪。", "explanation": "此处的“生化”修饰“分析仪”，指生化分析仪这种仪器，不指体内的化学变化。"}, {"text": "他的情感得到了生化。", "explanation": "这里应该用〈升华〉。情感、精神得到提高用升华；生化不表示这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "食物在胃里经过了一条生化反应。", "corrected_sentence": "食物在胃里经过了一系列生化反应。", "error_description": "错误形式：“一条生化反应”；正确形式：“一系列生化反应”。“条”用于细长的条状事物，不用于“反应”；此处也可改用“一种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种药把细胞里的生化反应慢减了。", "corrected_sentence": "这种药把细胞里的生化反应减慢了。", "error_description": "错误形式：“慢减”；正确形式：“减慢”。表示“变慢”的动补结构应为动词在前、结果补语在后，即“减慢”，不能颠倒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
