INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20820, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20820, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西刚做好或刚摘下来，没有变坏。", "primary_collocate": null, "pronunciation": "xīn xiān", "ipa": "ɕin˥ ɕiɛn˥", "syllable_count": 2, "sentences": [{"text": "这条鱼很新鲜。", "target_word": "新鲜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我要买新鲜的水果。", "target_word": "新鲜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "早上的牛奶最新鲜。", "target_word": "新鲜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "菜市场的蔬菜都很新鲜。", "target_word": "新鲜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些菜是早上刚摘的，很新鲜。", "target_word": "新鲜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个面包是今天做的，很新鲜。", "target_word": "新鲜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鱼不新鲜了，别买了。", "target_word": "新鲜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈每天去市场买新鲜的肉。", "target_word": "新鲜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的鱼很新鲜，所以客人特别多。", "target_word": "新鲜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱里放着新鲜的牛奶和鸡蛋。", "target_word": "新鲜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不新鲜", "label": "否定"}, {"form": "新鲜度", "label": "复合"}, {"form": "新鮮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "新鲜|食物刚做好或刚摘下来，没有变坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e7fa8c-7e28-4a9f-9f73-de782ccd99f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20820, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新鲜", "is_correct": true, "explanation": "新鲜：东西刚做好或刚摘下来，没有变坏。可以用来形容鱼。"}, {"text": "好听", "is_correct": false, "explanation": "搭配：“好听”说的是声音或音乐，不能说鱼好听。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不能用来形容鱼。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：鱼没有高兴的情绪，句子说不通。"}], "explanations": {"新鲜": "新鲜：东西刚做好或刚摘下来，没有变坏。可以用来形容鱼。", "好听": "搭配：“好听”说的是声音或音乐，不能说鱼好听。", "响亮": "搭配：“响亮”形容声音，不能用来形容鱼。", "高兴": "语义：鱼没有高兴的情绪，句子说不通。"}, "sentence_index": 0, "correct_answer": "新鲜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩很新鲜，考了全班第一。", "explanation": "这里应该用〈好〉。新鲜只用于刚做好或刚摘下、没有变坏的东西，不能用来形容成绩；成绩好要用〈好〉。"}, {"text": "这张旧床用了十年，还很新鲜。", "explanation": "这里应该用〈结实〉。新鲜只用于刚做好或刚摘下、没有变坏的东西，不能说用旧的东西还没坏；东西用久了还没坏，要用〈结实〉。"}, {"text": "他的身体很新鲜，一年到头都不生病。", "explanation": "这里应该用〈健康〉。新鲜只说刚做好或刚摘下的东西没有变坏，不能形容人的身体；身体好要用〈健康〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新鲜", "is_correct": true, "explanation": "新鲜：东西刚做好或刚摘下来，没有变坏。“鱼不新鲜了”说的是鱼已经变坏。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”说的是人或环境，不能用来形容鱼的状态。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或地方，不能用来形容鱼。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：鱼没有温柔的性格，句子说不通。"}], "explanations": {"新鲜": "新鲜：东西刚做好或刚摘下来，没有变坏。“鱼不新鲜了”说的是鱼已经变坏。", "安静": "搭配：“安静”说的是人或环境，不能用来形容鱼的状态。", "热闹": "搭配：“热闹”形容场面或地方，不能用来形容鱼。", "温柔": "语义：鱼没有温柔的性格，句子说不通。"}, "sentence_index": 6, "correct_answer": "新鲜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衬衫刚洗过，很新鲜。", "explanation": "这里应该用〈干净〉。新鲜指食物没有变坏；衣服洗过后干净，要用〈干净〉。"}, {"text": "他的字很新鲜，写得又快又好。", "explanation": "这里应该用〈工整〉。新鲜只用于刚做好或刚摘下、没有变坏的东西，不能形容字迹；字写得规范整齐要用〈工整〉。"}, {"text": "他的心肠很新鲜，总是愿意帮助别人。", "explanation": "这里应该用〈好〉。新鲜形容刚做好或刚摘下、没有变坏的东西，不能用来形容人的心肠；说人善良、乐于助人要说“心肠很〈好〉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块肉是今天早上买的，的新鲜。", "corrected_sentence": "这块肉是今天早上买的，很新鲜。", "error_description": "错误：“的”误用为程度副词位置。正确：“很新鲜”。形容词作谓语前应用程度副词“很”，不能用结构助词“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这盒牛奶已经没新鲜了，别喝了。", "corrected_sentence": "这盒牛奶已经不新鲜了，别喝了。", "error_description": "错误：“没新鲜了”。正确：“不新鲜了”。“没”不能直接修饰形容词“新鲜”，表示食物变坏要用“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20822, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20822, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "草屑就是很小的碎草片，比如割草后落在地上的小草叶。", "primary_collocate": null, "pronunciation": "cǎo xiè", "ipa": "tsʰau˨˩˦ ɕie˥˩", "syllable_count": 2, "sentences": [{"text": "小狗在草地上滚了一身草屑。", "target_word": "草屑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸割草，我帮他扫草屑。", "target_word": "草屑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "草屑粘在我的袜子上。", "target_word": "草屑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他拍掉裤子上的草屑。", "target_word": "草屑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一阵风吹起地上的草屑。", "target_word": "草屑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "割草机停了，院子里全是草屑。", "target_word": "草屑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子手里抓着一把草屑。", "target_word": "草屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把草屑装进袋子里。", "target_word": "草屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草屑沾到了她的白鞋上。", "target_word": "草屑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后，路边的草屑湿湿的。", "target_word": "草屑", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆", "label": "量词"}, {"form": "把", "label": "量词"}], "register": "中性", "sense_fingerprint": "割草后落在地上的小碎草叶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8504da67-cb87-4591-9bab-b889bffaad51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "草屑", "is_correct": true, "explanation": "草屑：指割草后落下的细碎草片，与“草地”的语境相符。"}, {"text": "金币", "is_correct": false, "explanation": "语义：草地上不会有金币，“滚了一身金币”不符合语境。"}, {"text": "玻璃碴", "is_correct": false, "explanation": "语义：玻璃碴锋利，小狗在草地上不会滚得一身玻璃碴。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线是金属导线，小狗不会在草地上滚得一身电线，句意不通。"}], "explanations": {"草屑": "草屑：指割草后落下的细碎草片，与“草地”的语境相符。", "金币": "语义：草地上不会有金币，“滚了一身金币”不符合语境。", "玻璃碴": "语义：玻璃碴锋利，小狗在草地上不会滚得一身玻璃碴。", "电线": "语义：电线是金属导线，小狗不会在草地上滚得一身电线，句意不通。"}, "sentence_index": 0, "correct_answer": "草屑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在草地上摘了一把草屑。", "explanation": "这里应该用〈草叶〉。草屑是细碎的碎片，摘不成一片完整的叶子，要说草叶。"}, {"text": "他把草屑拔了出来。", "explanation": "这里应该用〈草根〉。草根长在土里可以拔出，草屑是碎片，拔不出来。"}, {"text": "他用草屑捆好了柴火。", "explanation": "这里应该用〈草绳〉。捆绑需要有韧性的长条材料，草屑是碎片，做不到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "草屑", "is_correct": true, "explanation": "草屑：一把细碎的草屑可以用手抓住，与“一把”相符，句意通顺。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡易碎，孩子不会随手抓着一把灯泡。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车又大又重，孩子不可能用手抓着“一把汽车”。"}, {"text": "钢筋", "is_correct": false, "explanation": "搭配：钢筋是建筑材料，“一把钢筋”不常见，与“抓着”的动作不协调。"}], "explanations": {"草屑": "草屑：一把细碎的草屑可以用手抓住，与“一把”相符，句意通顺。", "灯泡": "语义：灯泡易碎，孩子不会随手抓着一把灯泡。", "汽车": "语义：汽车又大又重，孩子不可能用手抓着“一把汽车”。", "钢筋": "搭配：钢筋是建筑材料，“一把钢筋”不常见，与“抓着”的动作不协调。"}, "sentence_index": 6, "correct_answer": "草屑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每周修剪草屑。", "explanation": "这里应该用〈草坪〉。修剪的是长着的草坪，草屑已是碎片，不能修剪。"}, {"text": "她把草屑夹进书里做标本。", "explanation": "这里应该用〈花瓣〉。花瓣薄而完整，可以压成标本，草屑只是碎片，不能这样用。"}, {"text": "院子里开满了草屑。", "explanation": "这里应该用〈花〉。“开满”用于花朵，草屑不会开放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的衣服上沾了一只草屑。", "corrected_sentence": "他的衣服上沾了一撮草屑。", "error_description": "“草屑”的量词应用“撮”或“堆”，不能用“只”，“只”一般用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的衣服上满沾了草屑。", "corrected_sentence": "他的衣服上沾满了草屑。", "error_description": "“满”是“沾”的结果补语，必须紧跟在“沾”之后，应说“沾满了草屑”；“满沾了”把补语提到动词前，是错误语序。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20824, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
