INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20834, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能让植物和动物生长的、像糖一样的东西。", "primary_collocate": null, "pronunciation": "tàn yuán", "ipa": "tʰan˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "糖是细菌的碳源。", "target_word": "碳源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "动物从食物里得到碳源。", "target_word": "碳源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有碳源，小草长不大。", "target_word": "碳源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种细菌最爱吃的碳源是糖。", "target_word": "碳源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，碳源就是像糖一样的东西。", "target_word": "碳源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜂蜜里的糖，是小虫很好的碳源。", "target_word": "碳源", "complexity_tier": "T3", "furigana": "tàn yuán", "sentence_source": "generated"}, {"text": "妈妈在花盆里加了一点糖，给土里的细菌补充碳源。", "target_word": "碳源", "complexity_tier": "T3", "furigana": "tàn yuán", "sentence_source": "generated"}, {"text": "我们给小虫准备了一点糖，作为碳源。", "target_word": "碳源", "complexity_tier": "T3", "furigana": "tàn yuán", "sentence_source": "generated"}, {"text": "植物需要光，也需要碳源。", "target_word": "碳源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "缺少碳源，动物就会没有力气。", "target_word": "碳源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "让动植物生长的像糖一样的东西（通俗讲法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f6b3972-a8a9-4c30-a116-104a85e3fab6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20834, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "碳源", "is_correct": true, "explanation": "正确：碳源（tàn yuán），指能让动植物生长的、像糖一样的东西。"}, {"text": "半圆", "is_correct": false, "explanation": "bàn 与 tàn 声母不同（b / t），声调相同，意思是半圆。"}, {"text": "万元", "is_correct": false, "explanation": "wàn 与 tàn 只有声母不同（w / t），声调相同，意思是一万块钱。"}, {"text": "太原", "is_correct": false, "explanation": "tài 与 tàn 只有韵尾不同（i 与 n），声调相同，是山西省的省会。"}], "explanations": {"碳源": "正确：碳源（tàn yuán），指能让动植物生长的、像糖一样的东西。", "半圆": "bàn 与 tàn 声母不同（b / t），声调相同，意思是半圆。", "万元": "wàn 与 tàn 只有声母不同（w / t），声调相同，意思是一万块钱。", "太原": "tài 与 tàn 只有韵尾不同（i 与 n），声调相同，是山西省的省会。"}, "sentence_index": null, "correct_answer": "碳源"}, "level_3": {"options": [{"text": "碳源", "is_correct": true, "explanation": "正确：糖是细菌可以利用的碳源，与“像糖一样的东西”的释义一致。"}, {"text": "氮源", "is_correct": false, "explanation": "语义：糖不含氮，不能说是细菌的氮源。"}, {"text": "水分", "is_correct": false, "explanation": "语义：糖不是水分，“糖是细菌的水分”说不通。"}, {"text": "光照", "is_correct": false, "explanation": "语义：光照不是物质，糖不能是细菌的光照。"}], "explanations": {"碳源": "正确：糖是细菌可以利用的碳源，与“像糖一样的东西”的释义一致。", "氮源": "语义：糖不含氮，不能说是细菌的氮源。", "水分": "语义：糖不是水分，“糖是细菌的水分”说不通。", "光照": "语义：光照不是物质，糖不能是细菌的光照。"}, "sentence_index": 0, "correct_answer": "碳源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸每天开碳源去上班。", "explanation": "这里应该用〈汽车〉。碳源是让生物生长的物质，不能开着去上班。"}, {"text": "妈妈每天喝一杯碳源。", "explanation": "这里应该用〈糖水〉。碳源指能让生物生长、像糖一样的东西，不是可以直接喝的饮料，喝一杯应说“糖水”。"}, {"text": "我想知道这个消息的碳源。", "explanation": "这里应该用〈来源〉。碳源特指生物获得碳的物质，不能指消息的出处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20834, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "碳源", "is_correct": true, "explanation": "正确：碳源（tàn yuán），指能让动植物生长的、像糖一样的东西。"}, {"text": "汤圆", "is_correct": false, "explanation": "tāng 与 tàn 声母相同，但韵母（ang / an）和声调不同，意思是一种用糯米做的圆形食品。"}, {"text": "单元", "is_correct": false, "explanation": "dān 与 tàn 声母不同（d / t），声调也不同，意思是课本或楼房里的一个部分。"}, {"text": "汉源", "is_correct": false, "explanation": "hàn 与 tàn 只有声母不同（h 与 t），声调相同，是四川省的一个县名。"}], "explanations": {"碳源": "正确：碳源（tàn yuán），指能让动植物生长的、像糖一样的东西。", "汤圆": "tāng 与 tàn 声母相同，但韵母（ang / an）和声调不同，意思是一种用糯米做的圆形食品。", "单元": "dān 与 tàn 声母不同（d / t），声调也不同，意思是课本或楼房里的一个部分。", "汉源": "hàn 与 tàn 只有声母不同（h 与 t），声调相同，是四川省的一个县名。"}, "sentence_index": null, "correct_answer": "碳源"}, "level_3": {"options": [{"text": "碳源", "is_correct": true, "explanation": "正确：糖可以作为细菌可利用的碳源，句中补充的正是这种物质。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：氧气不含碳，不是碳源，句中要填的是碳源。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是细菌需要补充的物质。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是细菌需要补充的物质，句意不通。"}], "explanations": {"碳源": "正确：糖可以作为细菌可利用的碳源，句中补充的正是这种物质。", "氧气": "语义：氧气不含碳，不是碳源，句中要填的是碳源。", "玩具": "语义：玩具不是细菌需要补充的物质。", "课本": "语义：课本不是细菌需要补充的物质，句意不通。"}, "sentence_index": 6, "correct_answer": "碳源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很有碳源，敢一个人走夜路。", "explanation": "这里应该用〈勇气〉。碳源指能让生物生长、像糖一样的东西，不能用来表示人的胆量，应说“勇气”。"}, {"text": "这件衣服的碳源很贵。", "explanation": "这里应该用〈价格〉。碳源指能让生物生长、像糖一样的东西，不能用来说衣服的价钱，应说“价格”。"}, {"text": "这篇文章的碳源很清楚。", "explanation": "这里应该用〈出处〉。碳源特指生物获得碳的物质，不能指文章的出处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "糖很碳源。", "corrected_sentence": "糖是很好的碳源。", "error_description": "“碳源”是名词，不能直接受“很”修饰，应说“是很好的碳源”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "缺少着碳源，小虫就会没有力气。", "corrected_sentence": "缺少碳源，小虫就会没有力气。", "error_description": "“缺少”后不能接“着”表示持续，此处应删去“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
