INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20842, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "一个东西在空间里占的地方有多大。", "primary_collocate": null, "pronunciation": "tǐ jī", "ipa": "tʰi˨˩˦ tɕi˥", "syllable_count": 2, "sentences": [{"text": "手机的体积越来越小了。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个书架体积太大，放不进房间。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西瓜的体积比苹果大得多。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放东西进盒子以前，先看看它的体积。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆车体积很大，停不进小车位。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想买一台体积小一点的电脑。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个包体积太小，放不下我的书。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象的体积比老虎大很多。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水杯体积不大，可以放进包里。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用尺子量了箱子的体积。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "体积比", "label": "复合"}, {"form": "體積", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西在空间里占地方的大小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3509aa1-4a67-4a10-8fe3-c2b181bf7e77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20842, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "体积", "is_correct": true, "explanation": "正确：体积 tǐjī 指物体所占空间的大小。"}, {"text": "题记", "is_correct": false, "explanation": "tí（第二声）与 tǐ（第三声）、jì（第四声）与 jī（第一声）声调都不同，意思是题写在书画或器物上的文字。"}, {"text": "梯级", "is_correct": false, "explanation": "tī（第一声）与 tǐ（第三声）声调不同，jí（第二声）与 jī（第一声）声调也不同，意思是梯级。"}, {"text": "提及", "is_correct": false, "explanation": "tí（第二声）与 tǐ（第三声）声调不同，jí（第二声）与 jī（第一声）声调也不同，意思是提到。"}], "explanations": {"体积": "正确：体积 tǐjī 指物体所占空间的大小。", "题记": "tí（第二声）与 tǐ（第三声）、jì（第四声）与 jī（第一声）声调都不同，意思是题写在书画或器物上的文字。", "梯级": "tī（第一声）与 tǐ（第三声）声调不同，jí（第二声）与 jī（第一声）声调也不同，意思是梯级。", "提及": "tí（第二声）与 tǐ（第三声）声调不同，jí（第二声）与 jī（第一声）声调也不同，意思是提到。"}, "sentence_index": null, "correct_answer": "体积"}, "level_3": {"options": [{"text": "体积", "is_correct": true, "explanation": "正确：手机越来越小，说的是它占的空间变小，应该用“体积”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色可以说深浅，但不能说“越来越小”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”一般说高低、涨跌，不与“小”搭配。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道说浓淡，不能用来描述手机越来越小。"}], "explanations": {"体积": "正确：手机越来越小，说的是它占的空间变小，应该用“体积”。", "颜色": "语义：颜色可以说深浅，但不能说“越来越小”。", "价格": "搭配：“价格”一般说高低、涨跌，不与“小”搭配。", "味道": "语义：味道说浓淡，不能用来描述手机越来越小。"}, "sentence_index": 0, "correct_answer": "体积"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个包的体积很贵，我没舍得买。", "explanation": "这里应该用〈价格〉。贵和便宜说的是价格，体积指物体占的空间，不能用来说贵贱。"}, {"text": "这家店离我家的体积很远。", "explanation": "这里应该用〈距离〉。远近要说距离，体积不能表示两地之间的远近。"}, {"text": "这盏灯的体积很亮。", "explanation": "这里应该用〈亮度〉。明暗说的是亮度，体积只指物体占的空间大小，不能说亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7f0748-37a2-4643-a9f5-6c5c410a975b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20842, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "体积", "is_correct": true, "explanation": "正确：体积 tǐjī 指物体所占空间的大小。"}, {"text": "地基", "is_correct": false, "explanation": "dì（第四声）与 tǐ（第三声）声母与声调都不同，意思是地基。"}, {"text": "体系", "is_correct": false, "explanation": "xì（第四声）与 jī（第一声）声母不同（x 与 j），声调也不同，意思是体系。"}, {"text": "题记", "is_correct": false, "explanation": "tí（第二声）与 tǐ（第三声）、jì（第四声）与 jī（第一声）声调都不同，意思是题写在书画或器物上的文字。"}], "explanations": {"体积": "正确：体积 tǐjī 指物体所占空间的大小。", "地基": "dì（第四声）与 tǐ（第三声）声母与声调都不同，意思是地基。", "体系": "xì（第四声）与 jī（第一声）声母不同（x 与 j），声调也不同，意思是体系。", "题记": "tí（第二声）与 tǐ（第三声）、jì（第四声）与 jī（第一声）声调都不同，意思是题写在书画或器物上的文字。"}, "sentence_index": null, "correct_answer": "体积"}, "level_3": {"options": [{"text": "体积", "is_correct": true, "explanation": "正确：包太小，说的是它所占的空间小，应该用“体积”。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”说高低，不说“太小”，包的温度也不这样描述。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：包没有年龄，不能说它太小。"}, {"text": "声音", "is_correct": false, "explanation": "语义：包不会发出声音，说不上声音太小。"}], "explanations": {"体积": "正确：包太小，说的是它所占的空间小，应该用“体积”。", "温度": "搭配：“温度”说高低，不说“太小”，包的温度也不这样描述。", "年龄": "语义：包没有年龄，不能说它太小。", "声音": "语义：包不会发出声音，说不上声音太小。"}, "sentence_index": 6, "correct_answer": "体积"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这锅汤的体积很烫，不能马上喝。", "explanation": "这里应该用〈温度〉。烫和热说的是温度，体积只指物体占的空间，不能用来说烫。"}, {"text": "这根绳子的体积有三米。", "explanation": "这里应该用〈长度〉。米是长度单位，体积要用立方米或升，不能说三米。"}, {"text": "这次活动的体积很大，报纸上都在报道。", "explanation": "这里应该用〈影响〉。事情的作用大小要说影响，体积只指物体占的空间，不能用来形容活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7f0748-37a2-4643-a9f5-6c5c410a975b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台洗衣机体积的很大，放不进阳台。", "corrected_sentence": "这台洗衣机体积很大，放不进阳台。", "error_description": "错误：“体积的很大”，“的”放错了位置。正确：“体积很大”，“体积”后直接接“很大”，中间不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7f0748-37a2-4643-a9f5-6c5c410a975b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个包的体积得不大，可以放进行李箱里。", "corrected_sentence": "这个包的体积不大，可以放进行李箱里。", "error_description": "错误：“体积得不大”，“得”放错了位置。正确：“这个包的体积不大”，“体积”后直接接谓语“不大”，中间不加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7f0748-37a2-4643-a9f5-6c5c410a975b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
