INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20852, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "非常喜欢，特别想得到。", "primary_collocate": null, "pronunciation": "shì", "ipa": "ʂʐ̩˥˩", "syllable_count": 1, "sentences": [{"text": "弟弟嗜糖，口袋里总有几块糖。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外婆嗜酸，每顿饭都要吃酸菜。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫嗜鱼，一闻到鱼味就跑过来。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嗜赌，家里的钱都输光了。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王嗜棋，一有空就找人下棋。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥嗜肉，没有肉就吃不下饭。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她嗜甜食，看见蛋糕就想买。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶嗜咸，菜里总要多放盐。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明嗜书，一进书店就不想走。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这孩子嗜冰淇淋，冬天也要吃。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "嗜好", "label": "复合"}], "register": "书面", "sense_fingerprint": "非常喜欢某物、一见就想得到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6400fda1-5aa5-4407-a552-0ac0924ed60e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20852, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嗜", "is_correct": true, "explanation": "嗜（第四声）表示特别喜欢，是正确答案。"}, {"text": "十", "is_correct": false, "explanation": "shí（第二声）与 shì 声调不同，意思是数字十。"}, {"text": "狮", "is_correct": false, "explanation": "shī（第一声）与 shì 声调不同，意思是狮子。"}, {"text": "使", "is_correct": false, "explanation": "shǐ（第三声）与 shì 声调不同，意思是让、使得。"}, {"text": "寺", "is_correct": false, "explanation": "sì（第四声）与 shì 声母不同（s 与 sh），意思是寺庙。"}], "explanations": {"嗜": "嗜（第四声）表示特别喜欢，是正确答案。", "十": "shí（第二声）与 shì 声调不同，意思是数字十。", "狮": "shī（第一声）与 shì 声调不同，意思是狮子。", "使": "shǐ（第三声）与 shì 声调不同，意思是让、使得。", "寺": "sì（第四声）与 shì 声母不同（s 与 sh），意思是寺庙。"}, "sentence_index": null, "correct_answer": "嗜"}, "level_3": {"options": [{"text": "嗜", "is_correct": true, "explanation": "“弟弟嗜糖”表示弟弟特别喜欢吃糖，口袋里总备着糖，句意成立。"}, {"text": "恶", "is_correct": false, "explanation": "语义：“恶”表示厌恶，“弟弟恶糖”与“口袋里总有几块糖”不协调。"}, {"text": "厌", "is_correct": false, "explanation": "语义：“厌”表示讨厌，与口袋里常备糖的情形矛盾。"}, {"text": "怕", "is_correct": false, "explanation": "搭配：“怕”后直接接“糖”表示害怕，不表示喜好，与口袋里常备糖的语境不符。"}], "explanations": {"嗜": "“弟弟嗜糖”表示弟弟特别喜欢吃糖，口袋里总备着糖，句意成立。", "恶": "语义：“恶”表示厌恶，“弟弟恶糖”与“口袋里总有几块糖”不协调。", "厌": "语义：“厌”表示讨厌，与口袋里常备糖的情形矛盾。", "怕": "搭配：“怕”后直接接“糖”表示害怕，不表示喜好，与口袋里常备糖的语境不符。"}, "sentence_index": 0, "correct_answer": "嗜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他嗜了一个澡，然后就睡了。", "explanation": "这里应该用〈洗〉。“嗜”表示非常喜欢或特别想得到，不能表示“洗澡”这种具体动作。"}, {"text": "他嗜了一杯茶，然后就出门了。", "explanation": "“嗜”只表示强烈喜爱，不能表示“喝一杯”这种具体动作，这里应该用〈喝〉。"}, {"text": "他嗜了一下桌子，然后就出门了。", "explanation": "这里应该用〈擦〉。“嗜”表示非常喜欢或特别想得到，不能表示“擦桌子”这种具体动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20852, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "嗜", "is_correct": true, "explanation": "嗜（第四声）表示特别喜欢，是正确答案。"}, {"text": "四", "is_correct": false, "explanation": "sì（第四声）与 shì 声母不同（s 与 sh），意思是数字四。"}, {"text": "食", "is_correct": false, "explanation": "shí（第二声）与 shì 声调不同，意思是吃、食物。"}, {"text": "诗", "is_correct": false, "explanation": "shī（第一声）与 shì 声调不同，意思是诗。"}, {"text": "始", "is_correct": false, "explanation": "shǐ（第三声）与 shì 声调不同，意思是开始。"}], "explanations": {"嗜": "嗜（第四声）表示特别喜欢，是正确答案。", "四": "sì（第四声）与 shì 声母不同（s 与 sh），意思是数字四。", "食": "shí（第二声）与 shì 声调不同，意思是吃、食物。", "诗": "shī（第一声）与 shì 声调不同，意思是诗。", "始": "shǐ（第三声）与 shì 声调不同，意思是开始。"}, "sentence_index": null, "correct_answer": "嗜"}, "level_3": {"options": [{"text": "嗜", "is_correct": true, "explanation": "“她嗜甜食”表示她特别喜欢甜食，见到蛋糕就想买，句意一致。"}, {"text": "拒", "is_correct": false, "explanation": "语义：“拒”表示拒绝，与“看见蛋糕就想买”的喜爱矛盾。"}, {"text": "忌", "is_correct": false, "explanation": "语义：“忌”表示避开，与见到蛋糕就想买的语境冲突。"}, {"text": "畏", "is_correct": false, "explanation": "语域：“畏”是文言色彩很重的词，与口语化的描述不符，且与语境矛盾。"}], "explanations": {"嗜": "“她嗜甜食”表示她特别喜欢甜食，见到蛋糕就想买，句意一致。", "拒": "语义：“拒”表示拒绝，与“看见蛋糕就想买”的喜爱矛盾。", "忌": "语义：“忌”表示避开，与见到蛋糕就想买的语境冲突。", "畏": "语域：“畏”是文言色彩很重的词，与口语化的描述不符，且与语境矛盾。"}, "sentence_index": 6, "correct_answer": "嗜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这孩子很嗜妈妈，每天都要黏着她。", "explanation": "这里应该用〈喜欢〉。“嗜”的对象应是事物或活动，不能指人，表示对人的喜爱不能用“嗜”。"}, {"text": "这孩子嗜了一块冰淇淋，然后就去睡觉了。", "explanation": "这里应该用〈吃〉。“嗜”表示特别喜爱，不能表示“吃掉”这种具体动作。"}, {"text": "朋友嗜了我一本小说，我很感谢。", "explanation": "这里应该用〈借〉。“嗜”没有借出东西的意思，不能带“我”和“一本小说”两个宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他酒嗜，每天都要喝一瓶。", "corrected_sentence": "他嗜酒，每天都要喝一瓶。", "error_description": "错误：“酒嗜”；正确：“嗜酒”。“嗜”是动词，宾语应放在它后面，不能倒装。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她嗜不甜，只爱吃水果。", "corrected_sentence": "她不嗜甜，只爱吃水果。", "error_description": "错误：“嗜不甜”；正确：“不嗜甜”。否定词“不”应放在“嗜”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
