INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20854, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一群喜欢很热的水和土、在高温环境中生活的微生物。", "primary_collocate": null, "pronunciation": "shì rè jūn qún", "ipa": "ʂɻ̩˥˩ ɻɤ˥˩ tɕyn˥ tɕʰyn˧˥", "syllable_count": 4, "sentences": [{"text": "嗜热菌群喜欢住在很热的泉水里。", "target_word": "嗜热菌群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热土里住着许多嗜热菌群。", "target_word": "嗜热菌群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，嗜热菌群喜欢热水和热土。", "target_word": "嗜热菌群", "complexity_tier": "T3", "furigana": "shì rè jūn qún", "sentence_source": "generated"}, {"text": "冷水里找不到嗜热菌群，它们怕冷。", "target_word": "嗜热菌群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温泉边的热土里有很多嗜热菌群。", "target_word": "嗜热菌群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嗜热菌群不喜欢冷，只爱热水和热土。", "target_word": "嗜热菌群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在热土里看到了很多嗜热菌群。", "target_word": "嗜热菌群", "complexity_tier": "T3", "furigana": "shì rè jūn qún", "sentence_source": "generated"}, {"text": "把土放进热水里，嗜热菌群就醒了。", "target_word": "嗜热菌群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些嗜热菌群在热泉里过得很开心。", "target_word": "嗜热菌群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嗜热菌群怕冷，所以住在热的地方。", "target_word": "嗜热菌群", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "嗜热菌", "label": "复合"}, {"form": "一种嗜热菌群", "label": "量词"}], "register": "通用", "sense_fingerprint": "喜欢很热的水和土的微生物群", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15b67bf2-74fa-4403-bbdd-e606d254aaf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嗜热菌群", "is_correct": true, "explanation": "正确：指喜欢很热的水和土的微生物群，与句中“喜欢住在很热的泉水里”相符。"}, {"text": "冷水鱼", "is_correct": false, "explanation": "语义：冷水鱼怕热，不会喜欢住在很热的泉水里，与句意矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“住”要求有生命的主语，石头不能住，也谈不上喜欢。"}, {"text": "北极熊", "is_correct": false, "explanation": "语义：北极熊生活在寒冷地区，与句中“很热的泉水”的环境矛盾。"}], "explanations": {"嗜热菌群": "正确：指喜欢很热的水和土的微生物群，与句中“喜欢住在很热的泉水里”相符。", "冷水鱼": "语义：冷水鱼怕热，不会喜欢住在很热的泉水里，与句意矛盾。", "石头": "搭配：“住”要求有生命的主语，石头不能住，也谈不上喜欢。", "北极熊": "语义：北极熊生活在寒冷地区，与句中“很热的泉水”的环境矛盾。"}, "sentence_index": 0, "correct_answer": "嗜热菌群"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "嗜热菌群喜欢住在冰天雪地里。", "explanation": "这里应该用〈嗜冷菌群〉。嗜热菌群喜欢很热的环境，不能用来形容住在冰天雪地里的生物。"}, {"text": "北极的冰水里住着很多嗜热菌群。", "explanation": "这里应该用〈嗜冷菌群〉。嗜热菌群生活在高温环境中，冰冷的北极冰水里的是嗜冷菌群。"}, {"text": "嗜热菌群最怕热，一遇到高温就会死去。", "explanation": "这里与嗜热菌群喜欢高温的本义相反，应该用〈嗜冷菌群〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嗜热菌群", "is_correct": true, "explanation": "正确：指喜欢很热的水和土的微生物群，与句中“在热土里看到”相符。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块遇热会融化，热土里不会有很多冰块。"}, {"text": "企鹅", "is_correct": false, "explanation": "语义：企鹅怕热，不会大量出现在热土里。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气看不见，不能说“看到了很多空气”。"}], "explanations": {"嗜热菌群": "正确：指喜欢很热的水和土的微生物群，与句中“在热土里看到”相符。", "冰块": "语义：冰块遇热会融化，热土里不会有很多冰块。", "企鹅": "语义：企鹅怕热，不会大量出现在热土里。", "空气": "搭配：空气看不见，不能说“看到了很多空气”。"}, "sentence_index": 6, "correct_answer": "嗜热菌群"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "泉水边爬着一条嗜热菌群。", "explanation": "这里应该用〈种〉。〈条〉用于细长的东西，不能用来计量菌群。"}, {"text": "土里埋着一台嗜热菌群。", "explanation": "这里应该用〈种〉。〈台〉用于机器，不能用来计量菌群。"}, {"text": "我在花园里看到一棵嗜热菌群。", "explanation": "这里应该用〈种〉。〈棵〉用于植物，不能用来计量菌群。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草丛里有一条嗜热菌群。", "corrected_sentence": "草丛里有一种嗜热菌群。", "error_description": "量词错误：“条”用于细长的东西，嗜热菌群应使用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙角的石缝里住着一把嗜热菌群。", "corrected_sentence": "墙角的石缝里住着一种嗜热菌群。", "error_description": "量词错误：“把”用于有柄的物品，嗜热菌群应使用量词“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
