INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20858, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "碳氮比是泥土、肥料等东西里碳和氮的多少比例。", "primary_collocate": null, "pronunciation": "tàn dàn bǐ", "ipa": "tʰan⁵¹ tan⁵¹ pi²¹⁴", "syllable_count": 3, "sentences": [{"text": "这块地的碳氮比是多少？", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "泥土的碳氮比太高，菜长得慢。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用仪器测了泥土的碳氮比。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "碳氮比低，说明泥土里氮多。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秸秆的碳氮比很高。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种菜前要先了解碳氮比。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把碳氮比调到合适的范围。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老农说碳氮比对庄稼很重要。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "碳氮比不对，肥料就白放了。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上讲过泥土的碳氮比怎么算。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "C/N比", "label": "简称"}], "register": "科技", "sense_fingerprint": "泥土、肥料、秸秆等里碳和氮的比例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3509aa1-4a67-4a10-8fe3-c2b181bf7e77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20858, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "碳氮比", "is_correct": true, "explanation": "正确：问“这块地的碳氮比是多少”，问的是碳和氮的比值，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：问“多少”一般用于数量，不能问“味道是多少”，应该问“什么味道”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：一块地没有声音的多少，这个问法说不通。"}, {"text": "姓名", "is_correct": false, "explanation": "语义：地没有姓名，不能问它的姓名是多少。"}], "explanations": {"碳氮比": "正确：问“这块地的碳氮比是多少”，问的是碳和氮的比值，符合句意。", "味道": "搭配：问“多少”一般用于数量，不能问“味道是多少”，应该问“什么味道”。", "声音": "语义：一块地没有声音的多少，这个问法说不通。", "姓名": "语义：地没有姓名，不能问它的姓名是多少。"}, "sentence_index": 0, "correct_answer": "碳氮比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地的碳氮比很强。", "explanation": "这里应该用〈肥力〉。强弱说的是土地的肥沃程度，碳氮比只是比值，不能说强。"}, {"text": "这块地的碳氮比偏碱。", "explanation": "这里应该用〈酸碱度〉。偏酸、偏碱说的是酸碱度，碳氮比是比值，不能用酸碱来说。"}, {"text": "这块地的碳氮比很深。", "explanation": "这里应该用〈颜色〉。深浅说的是颜色，碳氮比是比值，不能说深浅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7f0748-37a2-4643-a9f5-6c5c410a975b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "碳氮比", "is_correct": true, "explanation": "正确：“把碳氮比调到合适的范围”，调的是碳和氮的比值，符合句意。"}, {"text": "血型", "is_correct": false, "explanation": "语义：血型是固定的，不能调到合适的范围。"}, {"text": "性别", "is_correct": false, "explanation": "语义：性别是固定的，不能调整，也不存在合适的范围。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“调到合适的范围”一般接比例、温度、浓度等，不接“年龄”。"}], "explanations": {"碳氮比": "正确：“把碳氮比调到合适的范围”，调的是碳和氮的比值，符合句意。", "血型": "语义：血型是固定的，不能调到合适的范围。", "性别": "语义：性别是固定的，不能调整，也不存在合适的范围。", "年龄": "搭配：“调到合适的范围”一般接比例、温度、浓度等，不接“年龄”。"}, "sentence_index": 6, "correct_answer": "碳氮比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这袋肥料的碳氮比很便宜。", "explanation": "这里应该用〈价格〉。便宜和贵说的是价格，碳氮比是比值，不能用来说便宜。"}, {"text": "这根木头的碳氮比有两米。", "explanation": "这里应该用〈长度〉。米是长度单位，碳氮比是比值，不能用米来算。"}, {"text": "这堆肥的碳氮比升到六十度。", "explanation": "这里应该用〈温度〉。升到几度说的是温度，碳氮比是比值，不会升到几度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7f0748-37a2-4643-a9f5-6c5c410a975b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块地碳氮比的很高，种的菜长得慢。", "corrected_sentence": "这块地碳氮比很高，种的菜长得慢。", "error_description": "错误：“碳氮比的很高”，“的”放错了位置。正确：“碳氮比很高”，“碳氮比”后直接接“很高”，中间不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7f0748-37a2-4643-a9f5-6c5c410a975b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要先碳氮比调好。", "corrected_sentence": "我们要先把碳氮比调好。", "error_description": "错误：缺少“把”。“碳氮比调好”中宾语放在动词前却没有“把”，不成句；应为“把碳氮比调好”。正确：“我们要先把碳氮比调好。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7f0748-37a2-4643-a9f5-6c5c410a975b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20862, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "流出", "is_correct": true, "explanation": "反义：流出指液体等从里面流到外面，与“流入”方向相反。"}, {"text": "停留", "is_correct": false, "explanation": "停留指暂时停在某处，与“流入”的移动义无反义关系。"}, {"text": "保存", "is_correct": false, "explanation": "保存指保持不失，与“流入”无反义关系。"}, {"text": "聚集", "is_correct": false, "explanation": "聚集指集中到一起，与“流入”不构成反义。"}], "correct_answer": "流出", "explanations": {"流出": "反义：流出指液体等从里面流到外面，与“流入”方向相反。", "停留": "停留指暂时停在某处，与“流入”的移动义无反义关系。", "保存": "保存指保持不失，与“流入”无反义关系。", "聚集": "聚集指集中到一起，与“流入”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
