INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20862, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "水或别的东西流到某个地方。", "primary_collocate": null, "pronunciation": "liú rù", "ipa": "ljoʊ˧˥ ɻu˥˩", "syllable_count": 2, "sentences": [{"text": "这条小河流入一个大湖。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，水流入了院子。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤洒了，流入了他的鞋里。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的雪水流入河里，河水变高了。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水从屋顶流入房间，地板都湿了。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家旁边的小河流入大江。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下水道坏了，脏水流入路边的小沟。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽水倒得太快，流入了桌子的缝里。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水从缺口流入船里，船慢慢沉了。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几条小溪流入同一个水库。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流入了", "label": "体标"}, {"form": "流入过", "label": "体标"}, {"form": "流入量", "label": "复合"}], "register": "中性", "sense_fingerprint": "水或别的东西流到某个地方里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b46612-8cc8-4c8a-ad20-a3f56ae151b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20862, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "溜入", "is_correct": false, "explanation": "溜入 liū rù 与 流入 liú rù 第一个音节声调不同（第一声与第二声），意思是悄悄进入。"}, {"text": "留住", "is_correct": false, "explanation": "留住 liú zhù 与 流入 liú rù 第二个音节声母不同（zh 与 r），意思是保留、不让离开。"}, {"text": "流露", "is_correct": false, "explanation": "流露 liú lù 与 流入 liú rù 第二个音节声母不同（l 与 r），意思是不自觉地表现出来。"}, {"text": "流入", "is_correct": true, "explanation": "正确答案：流入 liú rù，指水或别的东西流到某个地方里面。"}], "explanations": {"溜入": "溜入 liū rù 与 流入 liú rù 第一个音节声调不同（第一声与第二声），意思是悄悄进入。", "留住": "留住 liú zhù 与 流入 liú rù 第二个音节声母不同（zh 与 r），意思是保留、不让离开。", "流露": "流露 liú lù 与 流入 liú rù 第二个音节声母不同（l 与 r），意思是不自觉地表现出来。", "流入": "正确答案：流入 liú rù，指水或别的东西流到某个地方里面。"}, "sentence_index": null, "correct_answer": "流入"}, "level_3": {"options": [{"text": "流入", "is_correct": true, "explanation": "正确：流入指小河流进大湖，与句意相符。"}, {"text": "跳入", "is_correct": false, "explanation": "语义：“跳入”的主体须能跳，小河不能跳进大湖。"}, {"text": "游入", "is_correct": false, "explanation": "语义：“游”需要有生命的主体，小河不能游入大湖。"}, {"text": "倒入", "is_correct": false, "explanation": "配价：“倒入”需要有人或器具施动，小河不能充当倒的主体。"}], "explanations": {"流入": "正确：流入指小河流进大湖，与句意相符。", "跳入": "语义：“跳入”的主体须能跳，小河不能跳进大湖。", "游入": "语义：“游”需要有生命的主体，小河不能游入大湖。", "倒入": "配价：“倒入”需要有人或器具施动，小河不能充当倒的主体。"}, "sentence_index": 0, "correct_answer": "流入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他流入了房间，正在找东西。", "explanation": "这里应该用〈走进〉。流入指水或别的东西流到某处，人自己走进房间要说“走进”。"}, {"text": "蛇流入了草丛，很快就不见了。", "explanation": "这里应该用〈钻入〉。流入指水或别的东西流到某处，蛇是自己爬动的动物，钻进草丛要说“钻入”。"}, {"text": "石头流入了湖里，咚的一声。", "explanation": "这里应该用〈落入〉。流入指水或别的东西流到某处，石头自己掉下去、发出“咚”的声音，应说“落入”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流入", "is_correct": true, "explanation": "正确：流入表示脏水流进路边的小沟，与“下水道坏了”的语境相符。"}, {"text": "驶入", "is_correct": false, "explanation": "语义：“驶”的主体须是车船等交通工具，脏水不能驶入小沟。"}, {"text": "运入", "is_correct": false, "explanation": "配价：“运入”需要有人或车辆把东西运进去，脏水不能充当运送的主体。"}, {"text": "爬入", "is_correct": false, "explanation": "语义：“爬”的主体须是能爬行的生物，脏水不能爬进小沟。"}], "explanations": {"流入": "正确：流入表示脏水流进路边的小沟，与“下水道坏了”的语境相符。", "驶入": "语义：“驶”的主体须是车船等交通工具，脏水不能驶入小沟。", "运入": "配价：“运入”需要有人或车辆把东西运进去，脏水不能充当运送的主体。", "爬入": "语义：“爬”的主体须是能爬行的生物，脏水不能爬进小沟。"}, "sentence_index": 6, "correct_answer": "流入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车流入了隧道，很快就不见了。", "explanation": "这里应该用〈驶入〉。流入指水或别的东西流到某处，汽车是自己开进隧道的，应说“驶入”。"}, {"text": "他一进门就流入了沙发里，半天没动。", "explanation": "这里应该用〈坐进〉。流入指水或别的东西流到某处，人自己坐进沙发要说“坐进”。"}, {"text": "孩子们流入了操场，玩得很开心。", "explanation": "这里应该用〈跑进〉。流入指水或别的东西流到某处，人跑进操场要说“跑进”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海水顺着裂缝流入进了舱里。", "corrected_sentence": "海水顺着裂缝流入了舱里。", "error_description": "错误：“流入”本身已含“进入”的意思，后面又加了“进”，形成重复。正确应说“流入了舱里”或“流进了舱里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里，雨水流入了一小沟。", "corrected_sentence": "夜里，雨水流入了一条小沟。", "error_description": "错误：量词遗漏。“一”和“小沟”之间缺少量词，应说“一条小沟”。正确应为“雨水流入了一条小沟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20864, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
