INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20864, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一大堆东西堆在一起，像一座小山。", "primary_collocate": null, "pronunciation": "duī tǐ", "ipa": "twei˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "院子里有一个很大的堆体，里面都是旧木头。", "target_word": "堆体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，堆体上的落叶都湿了。", "target_word": "堆体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个堆体像一座小山，比房子还高。", "target_word": "堆体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们不要爬上那个堆体，很危险。", "target_word": "堆体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工地东边有一个沙子堆体，旁边停着卡车。", "target_word": "堆体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，堆体上的纸片飞了起来。", "target_word": "堆体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把箱子放在堆体旁边，然后走开了。", "target_word": "堆体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个堆体是用旧报纸堆成的。", "target_word": "堆体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "堆体越来越大，快要碰到屋顶了。", "target_word": "堆体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要再往堆体上放东西了。", "target_word": "堆体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "一大堆东西堆成小山的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15b67bf2-74fa-4403-bbdd-e606d254aaf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20864, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "堆体", "is_correct": true, "explanation": "正确：指堆在院子里的一大堆东西，里面装着旧木头。"}, {"text": "体形", "is_correct": false, "explanation": "语义：“体形”指人或动物的身材形状，不能说院子里有很大的体形，里面都是木头。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：“成绩”指工作或学习的结果，院子里堆的是实物，不能说很大的成绩。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”指人的数量，不能说院子里有很大的人口。"}], "explanations": {"堆体": "正确：指堆在院子里的一大堆东西，里面装着旧木头。", "体形": "语义：“体形”指人或动物的身材形状，不能说院子里有很大的体形，里面都是木头。", "成绩": "语义：“成绩”指工作或学习的结果，院子里堆的是实物，不能说很大的成绩。", "人口": "语义：“人口”指人的数量，不能说院子里有很大的人口。"}, "sentence_index": 0, "correct_answer": "堆体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子里有一条堆体，里面都是旧木头。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，不用于堆起来的物体。"}, {"text": "我们的堆体正在研发新产品。", "explanation": "这里应该用〈团队〉。“堆体”指堆起来的物料，不指一起工作的人，研发产品的群体要说“团队”。"}, {"text": "他干了一整天活，堆体消耗很大。", "explanation": "这里应该用〈体力〉。“堆体”指堆起来的物料，不指人的力气，消耗的力气要说“体力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "堆体", "is_correct": true, "explanation": "正确：指堆起来的东西，可以作箱子所在的地点。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛是人的器官，不能作“放在……旁边”的地点。"}, {"text": "思想", "is_correct": false, "explanation": "语义：“思想”是抽象概念，没有旁边可以放箱子。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“放在……旁边”要求具体的地点，不能用表示程度的“温度”。"}], "explanations": {"堆体": "正确：指堆起来的东西，可以作箱子所在的地点。", "眼睛": "语义：眼睛是人的器官，不能作“放在……旁边”的地点。", "思想": "语义：“思想”是抽象概念，没有旁边可以放箱子。", "温度": "搭配：“放在……旁边”要求具体的地点，不能用表示程度的“温度”。"}, "sentence_index": 6, "correct_answer": "堆体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家门口有一颗堆体，很大。", "explanation": "这里应该用〈个〉。“颗”用于粒状、圆形的小东西，不用于堆体。"}, {"text": "我们要考虑堆体的利益。", "explanation": "这里应该用〈整体〉。“堆体”指堆起来的物料，不指全体或整体，考虑整体利益要说“整体”。"}, {"text": "他每天锻炼，堆体很健康。", "explanation": "这里应该用〈身体〉。“堆体”指堆起来的物料，不指人的身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人堆体旁边放了一把铲子。", "corrected_sentence": "工人在堆体旁边放了一把铲子。", "error_description": "介词缺失：“堆体旁边”作放置的地点，前面应加介词“在”，应说“工人在堆体旁边放了一把铲子”。去掉“在”，“堆体旁边”会被误当作主语，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子里有一颗堆体，是用旧轮胎堆成的。", "corrected_sentence": "院子里有一个堆体，是用旧轮胎堆成的。", "error_description": "量词错误：“堆体”应用“个”。“颗”用于粒状、圆形的小东西，不能说“一颗堆体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20868, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20868, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20868, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让病毒死掉，不能害人。", "primary_collocate": null, "pronunciation": "miè huó", "ipa": "mjɛ˥˩ xwo˧˥", "syllable_count": 2, "sentences": [{"text": "医生说，这种药能灭活病毒。", "target_word": "灭活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开水能灭活水里的病毒和细菌。", "target_word": "灭活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种疫苗是用灭活的病毒做成的。", "target_word": "灭活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳光里的紫外线能灭活一些病毒。", "target_word": "灭活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用酒精灭活了手上的病毒。", "target_word": "灭活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把病毒灭活以后，它就不能害人了。", "target_word": "灭活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病毒怕热，煮一煮就能灭活。", "target_word": "灭活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作人员先灭活病毒，再把它送到实验室。", "target_word": "灭活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗手液能灭活手上的大部分病毒。", "target_word": "灭活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种病毒经过灭活，就不会再让人生病。", "target_word": "灭活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "灭活了", "label": "体标"}, {"form": "灭活过", "label": "体标"}, {"form": "灭活疫苗", "label": "复合"}], "register": "中性", "sense_fingerprint": "让病毒失去活性，不再害人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15b67bf2-74fa-4403-bbdd-e606d254aaf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咀嚼", "is_correct": false, "explanation": "搭配：咀嚼用于食物，不能用于病毒。"}, {"text": "繁殖", "is_correct": false, "explanation": "语义：繁殖是数量增多，与药物能让病毒失效的语境相反。"}, {"text": "灭活", "is_correct": true, "explanation": "正确。灭活指使病毒失去活性，与药物的作用相符。"}, {"text": "传播", "is_correct": false, "explanation": "语义：传播是扩散，与“这种药能”使病毒失效的语境相反。"}], "explanations": {"咀嚼": "搭配：咀嚼用于食物，不能用于病毒。", "繁殖": "语义：繁殖是数量增多，与药物能让病毒失效的语境相反。", "灭活": "正确。灭活指使病毒失去活性，与药物的作用相符。", "传播": "语义：传播是扩散，与“这种药能”使病毒失效的语境相反。"}, "sentence_index": 0, "correct_answer": "灭活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳光里的紫外线能灭活一些灰尘。", "explanation": "这里应该用〈清除〉。灭活只用于使病毒或微生物失去活性，灰尘要用清除。"}, {"text": "猎人灭活了一只老虎。", "explanation": "这里应该用〈杀死〉。灭活只用于病毒或微生物，老虎是动物，应用杀死。"}, {"text": "风一吹，蜡烛就灭活了。", "explanation": "这里应该用〈吹灭〉。灭活不用于火焰，风吹熄蜡烛应用吹灭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消化", "is_correct": false, "explanation": "搭配：消化用于食物，不能用于病毒。"}, {"text": "灭活", "is_correct": true, "explanation": "正确。煮沸能使病毒失去活性，与“怕热”和“煮一煮”搭配。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻是降温保存，与“煮一煮”的加热语境相反。"}, {"text": "晾干", "is_correct": false, "explanation": "语义：晾干是自然风干，与“煮一煮”的加热语境不符。"}], "explanations": {"消化": "搭配：消化用于食物，不能用于病毒。", "灭活": "正确。煮沸能使病毒失去活性，与“怕热”和“煮一煮”搭配。", "冷冻": "语义：冷冻是降温保存，与“煮一煮”的加热语境相反。", "晾干": "语义：晾干是自然风干，与“煮一煮”的加热语境不符。"}, "sentence_index": 6, "correct_answer": "灭活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场大火很快被灭活了。", "explanation": "这里应该用〈扑灭〉。灭活只用于微生物或病毒，大火应用扑灭。"}, {"text": "球队灭活了对手。", "explanation": "这里应该用〈击败〉。灭活不用于人或队伍，击败对手应用击败。"}, {"text": "这场地震灭活了整个小镇。", "explanation": "这里应该用〈毁灭〉。灭活只用于微生物或病毒，地震摧毁小镇应用毁灭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生说，这种药能病毒灭活。", "corrected_sentence": "医生说，这种药能把病毒灭活。", "error_description": "错误：“灭活”的宾语“病毒”前缺少“把”，直接放在动词前不通。正确：“能把病毒灭活”，用“把”字句引出宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批细菌很怕热，用开水煮一煮就能了灭活。", "corrected_sentence": "这批细菌很怕热，用开水煮一煮就能灭活。", "error_description": "错误：「了」插在动词「灭活」之前，写成「能了灭活」，不通。正确：「能灭活」，「能」后直接接动词，不加「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
