INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20870, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20870, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "街巷就是城市里的小路，人们可以在上面走路或骑车。", "primary_collocate": null, "pronunciation": "jiē xiàng", "ipa": "tɕjɛ˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我家附近的街巷很安静，适合骑车。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街巷太窄，大车进不来。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢骑车穿过城里的小街巷。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚饭后，爷爷常在街巷里走一走。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街巷里有很多小店，卖早饭和水果。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班以后，他骑车穿过几条街巷回家。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些街巷很复杂，新来的人容易迷路。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在街巷里骑自行车，妈妈在后面看着。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街巷两边种着树，夏天很凉快。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在老城的街巷里迷了路。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "城市里可以走路骑车的小路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c5209d6-189a-4b08-9be6-981d2b1ec05c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20870, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "街巷", "is_correct": true, "explanation": "街巷是城市里可以步行或骑车的小路，与“适合骑车”相符。"}, {"text": "楼房", "is_correct": false, "explanation": "语义：楼房上不能骑车，与“适合骑车”的后半句矛盾。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流上不能骑车，句子所说的骑车场所不可能是河流。"}, {"text": "商场", "is_correct": false, "explanation": "搭配：“商场”一般不与“安静”搭配，人流多，也不以骑车为主要用途。"}], "explanations": {"街巷": "街巷是城市里可以步行或骑车的小路，与“适合骑车”相符。", "楼房": "语义：楼房上不能骑车，与“适合骑车”的后半句矛盾。", "河流": "语义：河流上不能骑车，句子所说的骑车场所不可能是河流。", "商场": "搭配：“商场”一般不与“安静”搭配，人流多，也不以骑车为主要用途。"}, "sentence_index": 0, "correct_answer": "街巷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把小船停在街巷上，等着涨潮。", "explanation": "这里应该用〈码头〉。街巷是城里的小路，船不能停在上面，要停在码头。"}, {"text": "这条街巷跨越了大河，很壮观。", "explanation": "这里应该用〈桥〉。街巷是城里的小路，不能跨越大河；跨河的建筑是桥，不是街巷。"}, {"text": "这条街巷每天有很多火车进站。", "explanation": "这里应该用〈车站〉。街巷是城里的小路，没有铁路，不能有火车进站；这里把“街巷”误用为车站。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "街巷", "is_correct": true, "explanation": "街巷是城镇中的小路，新来的人在里面容易迷路，与“复杂”相符。"}, {"text": "门窗", "is_correct": false, "explanation": "语义：门窗不会让人迷路，句子的后半句无法成立。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本没有可以走错的路线，与“新来的人容易迷路”矛盾。"}, {"text": "乐曲", "is_correct": false, "explanation": "搭配：“迷路”不用于乐曲，乐曲的“复杂”指结构，无法与“迷路”搭配。"}], "explanations": {"街巷": "街巷是城镇中的小路，新来的人在里面容易迷路，与“复杂”相符。", "门窗": "语义：门窗不会让人迷路，句子的后半句无法成立。", "书本": "语义：书本没有可以走错的路线，与“新来的人容易迷路”矛盾。", "乐曲": "搭配：“迷路”不用于乐曲，乐曲的“复杂”指结构，无法与“迷路”搭配。"}, "sentence_index": 6, "correct_answer": "街巷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飞机停在街巷里，乘客正在登机。", "explanation": "这里应该用〈机场〉。街巷是城里的小路，飞机不能停在街巷里，登机要去机场。"}, {"text": "夏天我们去街巷里游泳，水很蓝。", "explanation": "这里应该用〈海边〉。街巷是城里的小路，没有水，不能在里面游泳。"}, {"text": "一万人坐在街巷里看足球比赛。", "explanation": "这里应该用〈体育场〉。街巷是城里的小路，不能坐一万人看比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家门口有一块街巷，很安静。", "corrected_sentence": "我家门口有一条街巷，很安静。", "error_description": "量词错误：街巷是线状的，应用量词“条”，“块”用于块状或面状事物，不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在老城找到了一把街巷。", "corrected_sentence": "我们在老城找到了一条街巷。", "error_description": "量词错误：“把”用于有柄的器具，街巷是线状的，应用量词“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20872, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降至", "is_correct": true, "explanation": "正确：与“升至”相反，指物体由高处向低处移动到某一位置。"}, {"text": "抵达", "is_correct": false, "explanation": "语义：“抵达”指到达某地，与“升至”没有反义关系。"}, {"text": "停留", "is_correct": false, "explanation": "语义：“停留”指暂时不动，与“升至”没有反义关系。"}, {"text": "保持", "is_correct": false, "explanation": "语义：“保持”表示不变，与“升至”没有反义关系。"}], "correct_answer": "降至", "explanations": {"降至": "正确：与“升至”相反，指物体由高处向低处移动到某一位置。", "抵达": "语义：“抵达”指到达某地，与“升至”没有反义关系。", "停留": "语义：“停留”指暂时不动，与“升至”没有反义关系。", "保持": "语义：“保持”表示不变，与“升至”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20872, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降至", "is_correct": true, "explanation": "正确：与“升至”相反，指物体由高处向低处移动到某一位置。"}, {"text": "到达", "is_correct": false, "explanation": "语义：“到达”指到了某个地点，与“升至”没有反义关系。"}, {"text": "逗留", "is_correct": false, "explanation": "语义：“逗留”指暂时停下，与“升至”没有反义关系。"}, {"text": "静止", "is_correct": false, "explanation": "语义：“静止”指不动，与“升至”没有反义关系。"}], "correct_answer": "降至", "explanations": {"降至": "正确：与“升至”相反，指物体由高处向低处移动到某一位置。", "到达": "语义：“到达”指到了某个地点，与“升至”没有反义关系。", "逗留": "语义：“逗留”指暂时停下，与“升至”没有反义关系。", "静止": "语义：“静止”指不动，与“升至”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20872, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从低处到高处。", "primary_collocate": null, "pronunciation": "shēng zhì", "ipa": "ʂɤŋ˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "国旗慢慢升至杆顶。", "target_word": "升至", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "太阳升至半空，天亮了。", "target_word": "升至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气球升至十米高的地方。", "target_word": "升至", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电梯很快升至二十层。", "target_word": "升至", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火箭升至太空后，很快看不见了。", "target_word": "升至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月亮升至树顶，院子里很亮。", "target_word": "升至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "无人机升至五十米，开始拍照。", "target_word": "升至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工地的吊篮慢慢升至屋顶。", "target_word": "升至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热气球升至云层上面。", "target_word": "升至", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机升至高空后，窗外全是白云。", "target_word": "升至", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "升至了", "label": "体标"}], "register": "中性", "sense_fingerprint": "物体从低处移动到较高的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15b67bf2-74fa-4403-bbdd-e606d254aaf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20872, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "升至", "is_correct": true, "explanation": "正确：“升至”指物体从低处到达较高的位置。"}, {"text": "升值", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，“升值”意思是价值上涨。"}, {"text": "声势", "is_correct": false, "explanation": "zh 与 sh 声母不同，“声势”意思是气势、声威。"}, {"text": "神志", "is_correct": false, "explanation": "shēng 与 shén 韵尾不同（ng 与 n），“神志”意思是意识。"}, {"text": "生吃", "is_correct": false, "explanation": "chī 与 zhì 声母（ch/zh）和声调（第一声/第四声）都不同，“生吃”意思是不煮就吃。"}], "explanations": {"升至": "正确：“升至”指物体从低处到达较高的位置。", "升值": "zhì（第四声）与 zhí（第二声）声调不同，“升值”意思是价值上涨。", "声势": "zh 与 sh 声母不同，“声势”意思是气势、声威。", "神志": "shēng 与 shén 韵尾不同（ng 与 n），“神志”意思是意识。", "生吃": "chī 与 zhì 声母（ch/zh）和声调（第一声/第四声）都不同，“生吃”意思是不煮就吃。"}, "sentence_index": null, "correct_answer": "升至"}, "level_3": {"options": [{"text": "升至", "is_correct": true, "explanation": "正确：指国旗从下向上升到杆顶。"}, {"text": "落至", "is_correct": false, "explanation": "语义：“落”是向下，国旗从下往上升的意思与“落至杆顶”相反。"}, {"text": "降至", "is_correct": false, "explanation": "语义：“降”是向下降，国旗不能降到杆顶。"}, {"text": "升值", "is_correct": false, "explanation": "搭配：“升值”指价值增加，不用于国旗的位移。"}], "explanations": {"升至": "正确：指国旗从下向上升到杆顶。", "落至": "语义：“落”是向下，国旗从下往上升的意思与“落至杆顶”相反。", "降至": "语义：“降”是向下降，国旗不能降到杆顶。", "升值": "搭配：“升值”指价值增加，不用于国旗的位移。"}, "sentence_index": 0, "correct_answer": "升至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "船慢慢升至海底。", "explanation": "这里应该用〈沉到〉。“升至”表示向上，船向海底沉是向下，要说“沉到”。"}, {"text": "石头慢慢升至山脚。", "explanation": "这里应该用〈滚到〉。「升至」表示向上，石头从高处到山脚是向下，要说「滚到」。"}, {"text": "火车从北京升至上海。", "explanation": "这里应该用〈驶往〉。“升至”表示向上，从北京到上海是水平移动，要说“驶往”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20872, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "升至", "is_correct": true, "explanation": "正确：“升至”指物体从低处到达较高的位置。"}, {"text": "生事", "is_correct": false, "explanation": "zh 与 sh 声母不同，“生事”意思是找麻烦。"}, {"text": "圣旨", "is_correct": false, "explanation": "shēng（第一声）与 shèng（第四声）声调不同，zhì 与 zhǐ 声调也不同，“圣旨”意思是皇帝的命令。"}, {"text": "升势", "is_correct": false, "explanation": "zh 与 sh 声母不同，“升势”意思是上升的趋势。"}, {"text": "生纸", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，“生纸”意思是未加工的纸。"}], "explanations": {"升至": "正确：“升至”指物体从低处到达较高的位置。", "生事": "zh 与 sh 声母不同，“生事”意思是找麻烦。", "圣旨": "shēng（第一声）与 shèng（第四声）声调不同，zhì 与 zhǐ 声调也不同，“圣旨”意思是皇帝的命令。", "升势": "zh 与 sh 声母不同，“升势”意思是上升的趋势。", "生纸": "zhì（第四声）与 zhǐ（第三声）声调不同，“生纸”意思是未加工的纸。"}, "sentence_index": null, "correct_answer": "升至"}, "level_3": {"options": [{"text": "升至", "is_correct": true, "explanation": "正确：指无人机从低处升到五十米的高度。"}, {"text": "悬浮", "is_correct": false, "explanation": "配价：“悬浮”是不及物动词，不能直接带“五十米”作目标，要说“悬浮在五十米处”。"}, {"text": "升温", "is_correct": false, "explanation": "搭配：“升温”指温度升高，无人机是向上移动，不说升温到高度。"}, {"text": "升级", "is_correct": false, "explanation": "搭配：“升级”指等级提高，不能接“五十米”这样的高度。"}], "explanations": {"升至": "正确：指无人机从低处升到五十米的高度。", "悬浮": "配价：“悬浮”是不及物动词，不能直接带“五十米”作目标，要说“悬浮在五十米处”。", "升温": "搭配：“升温”指温度升高，无人机是向上移动，不说升温到高度。", "升级": "搭配：“升级”指等级提高，不能接“五十米”这样的高度。"}, "sentence_index": 6, "correct_answer": "升至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飞机升至北京后，窗外全是白云。", "explanation": "这里应该用〈抵达〉。“升至”后面接的是高度或数值，不能是城市名。"}, {"text": "潜水员慢慢升至水底。", "explanation": "这里应该用〈下沉〉。“升至”表示向上，潜水员去水底是向下，要说“下沉”。"}, {"text": "飞机从高空升至地面。", "explanation": "这里应该用〈降落〉。“升至”表示向上，从高空到地面是向下，要说“降至”或“降落”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "热气球慢慢升至到山顶。", "corrected_sentence": "热气球慢慢升至山顶。", "error_description": "错误：“升至”的“至”已经表示“到”，后面再加“到”就重复了。正确：“热气球慢慢升至山顶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "无人机升至二十个米时，开始拍照。", "corrected_sentence": "无人机升至二十米时，开始拍照。", "error_description": "量词错误：“米”是长度单位，前面不能加“个”，应说“升至二十米”，不说“二十个米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eedc6175-dc96-4c8b-b3ba-85cb14ebfd07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
