INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20874, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "只属于一个人或一个地方的，别人不能有。", "primary_collocate": null, "pronunciation": "zhuān shǔ", "ipa": "ʈʂwan˥ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个杯子是我的专属杯子，别人不用。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小花园是奶奶专属的地方。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一把专属的椅子，别人不能坐。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我的专属座位，请你坐别处。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶是这个山村专属的特产，别的地方没有。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间是女儿专属的，哥哥不能进。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每只猫都有专属的小碗。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路是学校专属的，外面的车不能走。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名字是我们公司专属的，别人不能用。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个密码是你专属的，不要告诉别人。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "专属的", "label": "定语形式"}, {"form": "專屬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "只属于一个人或一个地方，别人不能有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c5209d6-189a-4b08-9be6-981d2b1ec05c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20874, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专属", "is_correct": true, "explanation": "正确答案。专属指只属于某一个人，与「我的」相合，且与「别人不用」一致。"}, {"text": "公共", "is_correct": false, "explanation": "语义：「公共」指大家共有，与「我的」所属关系相矛盾，也与「别人不用」相矛盾。"}, {"text": "公用", "is_correct": false, "explanation": "语义：「公用」指供大家使用，与「我的」相矛盾，且与「别人不用」相矛盾。"}, {"text": "通用", "is_correct": false, "explanation": "搭配：「通用」多修饰标准、软件，不说「我的通用杯子」。"}], "explanations": {"专属": "正确答案。专属指只属于某一个人，与「我的」相合，且与「别人不用」一致。", "公共": "语义：「公共」指大家共有，与「我的」所属关系相矛盾，也与「别人不用」相矛盾。", "公用": "语义：「公用」指供大家使用，与「我的」相矛盾，且与「别人不用」相矛盾。", "通用": "搭配：「通用」多修饰标准、软件，不说「我的通用杯子」。"}, "sentence_index": 0, "correct_answer": "专属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这把专属的钥匙借给了全班同学，大家都能用。", "explanation": "这里应该用〈共用〉。专属指不与他人共享，借给全班同学就不能说专属。"}, {"text": "这个广场是专属场所，谁都可以去。", "explanation": "这里应该用〈公共〉。专属指不与他人共享，而广场谁都可以去，不能说专属。"}, {"text": "这部电影很专属，很多人都在看。", "explanation": "这里应该用〈热门〉。专属强调不与他人共享，不能用来说很多人都在看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20874, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专属", "is_correct": true, "explanation": "正确答案。专属指只属于某一只猫，与「每只猫都有」相合，且与「小碗」相合。"}, {"text": "共同", "is_correct": false, "explanation": "语义：「共同」指大家共有，与「每只猫都有」各自拥有的意思相矛盾。"}, {"text": "集体", "is_correct": false, "explanation": "语义：「集体」指大家共同所有，与「每只猫都有」各自拥有的意思相矛盾。"}, {"text": "巨大", "is_correct": false, "explanation": "体貌：「巨大」形容体形，与「小碗」的“小”相矛盾。"}], "explanations": {"专属": "正确答案。专属指只属于某一只猫，与「每只猫都有」相合，且与「小碗」相合。", "共同": "语义：「共同」指大家共有，与「每只猫都有」各自拥有的意思相矛盾。", "集体": "语义：「集体」指大家共同所有，与「每只猫都有」各自拥有的意思相矛盾。", "巨大": "体貌：「巨大」形容体形，与「小碗」的“小”相矛盾。"}, "sentence_index": 6, "correct_answer": "专属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这类小吃在城里很专属，随处都能买到。", "explanation": "这里应该用〈常见〉。专属指只属于一个人或一个地方、别人不能有，不能用来说某种小吃随处都能买到。"}, {"text": "这项技术在全国很专属，已经普遍推广了。", "explanation": "这里应该用〈普遍〉。专属指只属于一个人或一个地方、别人不能有，不能用来说某项技术已经普遍推广。"}, {"text": "这本书很专属，大家都能买到。", "explanation": "这里应该用〈畅销〉。专属指不与他人共享，不能用来说书卖得好、大家都能买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那把椅子是他很专属的，别人不能坐。", "corrected_sentence": "那把椅子是他专属的，别人不能坐。", "error_description": "程度副词误用：“专属”表示只属于某人，没有程度之分，不能受“很”修饰，应去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把钥匙是他专属，别人不能用。", "corrected_sentence": "这把钥匙是他专属的，别人不能用。", "error_description": "漏掉“的”：「专属」作谓语时通常要加“的”，应说“这把钥匙是他专属的”，与同类句“这个房间是女儿专属的”一致。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
