INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20876, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20876, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "修道士住的房子，他们在里面学习、祈祷和劳动。", "primary_collocate": null, "pronunciation": "xiū dào yuàn", "ipa": "ɕjoʊ˥ taʊ˥˩ ɥɛn˥˩", "syllable_count": 3, "sentences": [{"text": "修道士们在修道院里学习、祈祷和劳动。", "target_word": "修道院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座修道院有一个很大的图书馆。", "target_word": "修道院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修道院的墙很高，外面的人看不到里面。", "target_word": "修道院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在修道院里学会了做面包。", "target_word": "修道院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山谷里有一座很老的修道院。", "target_word": "修道院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每到中午，修道院的钟就会响。", "target_word": "修道院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修女们把花园里的菜送到修道院的厨房。", "target_word": "修道院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨的时候，我们在修道院门口躲雨。", "target_word": "修道院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座修道院里住着二十多位修士。", "target_word": "修道院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修道院的生活很简单，每个人都要工作。", "target_word": "修道院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "修士们学习、祈祷、劳动并生活的建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b46612-8cc8-4c8a-ad20-a3f56ae151b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20876, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修道院", "is_correct": true, "explanation": "修道院是修士们学习、祈祷和劳动的建筑，符合句意。"}, {"text": "体育馆", "is_correct": false, "explanation": "语义：体育馆是运动场所，不是修士学习和祈祷的地方。"}, {"text": "游泳池", "is_correct": false, "explanation": "搭配：“学习、祈祷和劳动”不搭配游泳池这样的地方。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园是饲养动物的地方，不适合修士学习、祈祷和劳动。"}], "explanations": {"修道院": "修道院是修士们学习、祈祷和劳动的建筑，符合句意。", "体育馆": "语义：体育馆是运动场所，不是修士学习和祈祷的地方。", "游泳池": "搭配：“学习、祈祷和劳动”不搭配游泳池这样的地方。", "动物园": "语义：动物园是饲养动物的地方，不适合修士学习、祈祷和劳动。"}, "sentence_index": 0, "correct_answer": "修道院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在修道院里玩滑梯。", "explanation": "这里应该用〈游乐场〉。修道院是修士生活的地方，不是孩子们玩滑梯的场所。"}, {"text": "他在修道院里取了一千块钱。", "explanation": "这里应该用〈银行〉。修道院不办理存取款，取钱要去银行。"}, {"text": "他每天在修道院里踢足球。", "explanation": "这里应该用〈足球场〉。修道院是修行的场所，不是踢足球的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修道院", "is_correct": true, "explanation": "修道院是有厨房的建筑，修女们可以把菜送到那里，符合句意。"}, {"text": "鞋店", "is_correct": false, "explanation": "语义：鞋店是卖鞋的地方，与把菜送到厨房的情境不符。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“厨房”一般不设在教室里，“教室的厨房”不搭配。"}, {"text": "停车场", "is_correct": false, "explanation": "语义：停车场是停放车辆的地方，不设厨房，菜不会送到那里。"}], "explanations": {"修道院": "修道院是有厨房的建筑，修女们可以把菜送到那里，符合句意。", "鞋店": "语义：鞋店是卖鞋的地方，与把菜送到厨房的情境不符。", "教室": "搭配：“厨房”一般不设在教室里，“教室的厨房”不搭配。", "停车场": "语义：停车场是停放车辆的地方，不设厨房，菜不会送到那里。"}, "sentence_index": 6, "correct_answer": "修道院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅客们在修道院里排队登机。", "explanation": "这里应该用〈机场〉。修道院不是登机的地方，乘飞机要去机场。"}, {"text": "这位运动员每天在修道院里游泳两个小时。", "explanation": "这里应该用〈游泳馆〉。修道院不是游泳场所，游泳要去游泳馆。"}, {"text": "周末我们在修道院里看电影。", "explanation": "这里应该用〈电影院〉。修道院不放映电影，看电影要去电影院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山上有一只修道院，住着很多修士。", "corrected_sentence": "山上有一座修道院，住着很多修士。", "error_description": "量词错误：“修道院”是建筑，应说“一座修道院”，不能说“一只修道院”（“只”多用于动物）。正确形式是“一座修道院”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "修女们在修道院上做饭。", "corrected_sentence": "修女们在修道院里做饭。", "error_description": "方位错误：“修道院”是建筑，应用方位词“里”，不能用“上”。“在……上”多用于桌面、墙面等表面，不能说“在修道院上”。正确形式是“在修道院里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
