INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20878, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "书和杂志等，给人看的东西。", "primary_collocate": null, "pronunciation": "chū bǎn wù", "ipa": "tʂʰu˥ pan˨˩˦ u˥˩", "syllable_count": 3, "sentences": [{"text": "书和杂志都是出版物。", "target_word": "出版物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家书店卖很多种出版物。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里有很多出版物，我常去看书。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸、杂志和书，都是常见的出版物。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种出版物是给孩子看的，里面有很多图画。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧出版物都送给了学校。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每个月都买几种新出版物。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些出版物放在书架的最上面。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出版物太多了，我一时不知道选哪本。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报亭里的出版物有报纸，也有杂志。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "批", "label": "量词"}, {"form": "电子出版物", "label": "复合"}], "register": "中性", "sense_fingerprint": "书、杂志等供人阅读的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a75c456c-0a28-4657-b2af-ed1ca1e72345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20878, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出版物", "is_correct": true, "explanation": "出版物指书刊等供人阅读的东西，与“书和杂志”同属一类，符合句意。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物是吃的东西，与书和杂志不属于同一类。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物是生物，不能与书和杂志归为一类。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具是桌子、椅子等用品，不是供人阅读的东西，不能与书和杂志归为一类。"}], "explanations": {"出版物": "出版物指书刊等供人阅读的东西，与“书和杂志”同属一类，符合句意。", "食物": "语义：食物是吃的东西，与书和杂志不属于同一类。", "动物": "语义：动物是生物，不能与书和杂志归为一类。", "家具": "语义：家具是桌子、椅子等用品，不是供人阅读的东西，不能与书和杂志归为一类。"}, "sentence_index": 0, "correct_answer": "出版物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去出版物买书。", "explanation": "这里应该用〈书店〉。书店是卖书的地方，出版物是书刊本身，不是店铺。"}, {"text": "我每天早上都喝出版物。", "explanation": "这里应该用〈饮料〉。饮料可以喝，出版物是书刊，不能用来喝。"}, {"text": "这位出版物每天给病人看病。", "explanation": "这里应该用〈医生〉。医生给病人看病，出版物是书刊，不能看病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出版物", "is_correct": true, "explanation": "出版物可以购买，“每个月都买几种新出版物”符合“买”的搭配。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能用“买几种新”来描述，也不属于出版物。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能买，也不能说“买几种新天气”。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：“买”的对象不能是月亮，搭配不通。"}], "explanations": {"出版物": "出版物可以购买，“每个月都买几种新出版物”符合“买”的搭配。", "空气": "语义：空气不能用“买几种新”来描述，也不属于出版物。", "天气": "语义：天气是自然现象，不能买，也不能说“买几种新天气”。", "月亮": "搭配：“买”的对象不能是月亮，搭配不通。"}, "sentence_index": 6, "correct_answer": "出版物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每天去出版物吃午饭。", "explanation": "这里应该用〈食堂〉。食堂是吃饭的地方，出版物是书刊，不能用来吃午饭。"}, {"text": "妈妈用出版物洗衣服。", "explanation": "这里应该用〈肥皂〉。肥皂才用来洗衣服，出版物是书刊，不能用来洗衣服。"}, {"text": "这位出版物很会做菜。", "explanation": "这里应该用〈厨师〉。厨师会做菜，出版物是书刊，不会做菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了几只出版物。", "corrected_sentence": "我买了几本出版物。", "error_description": "“只”用于动物或成对物中的单个，书刊作为出版物应该用“本”计数，应说“几本出版物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们送给我一首出版物。", "corrected_sentence": "他们送给我一本出版物。", "error_description": "量词错误：“首”用于诗词、歌曲，不用于书刊；书刊应用“本”计数，应说“一本出版物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20880, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贫乏", "is_correct": true, "explanation": "贫乏指知识、经验等缺少，与“丰富”构成反义。"}, {"text": "清澈", "is_correct": false, "explanation": "清澈形容水或光线透明，与“丰富”的内容、经验义不构成反义。"}, {"text": "严厉", "is_correct": false, "explanation": "严厉形容态度或要求，与内容、经验无关，不是“丰富”的反义词。"}, {"text": "沉重", "is_correct": false, "explanation": "沉重形容分量大或心情压抑，与“丰富”不构成反义。"}], "correct_answer": "贫乏", "explanations": {"贫乏": "贫乏指知识、经验等缺少，与“丰富”构成反义。", "清澈": "清澈形容水或光线透明，与“丰富”的内容、经验义不构成反义。", "严厉": "严厉形容态度或要求，与内容、经验无关，不是“丰富”的反义词。", "沉重": "沉重形容分量大或心情压抑，与“丰富”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20880, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贫乏", "is_correct": true, "explanation": "贫乏指知识、经验等缺少，与“丰富”构成反义。"}, {"text": "狭窄", "is_correct": false, "explanation": "狭窄形容空间或道路窄小，与“丰富”不构成反义。"}, {"text": "温和", "is_correct": false, "explanation": "温和形容性情或态度不激烈，与“丰富”不构成反义。"}, {"text": "轻松", "is_correct": false, "explanation": "轻松形容心情或负担少，与“丰富”的内容、经验义不构成反义。"}], "correct_answer": "贫乏", "explanations": {"贫乏": "贫乏指知识、经验等缺少，与“丰富”构成反义。", "狭窄": "狭窄形容空间或道路窄小，与“丰富”不构成反义。", "温和": "温和形容性情或态度不激烈，与“丰富”不构成反义。", "轻松": "轻松形容心情或负担少，与“丰富”的内容、经验义不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20880, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（知识、经验、内容、营养等）种类多或数量大。", "primary_collocate": null, "pronunciation": "fēng fù", "ipa": "fəŋ˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "他当老师二十年了，经验很丰富。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的内容很丰富，值得一看。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生的知识非常丰富。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "橙子里的维生素很丰富。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的想象力很丰富，常常画出奇怪的东西。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目内容丰富，大人孩子都爱看。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的工作经验丰富，所以公司请她当经理。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "豆腐的营养很丰富，对身体好。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行让他的人生经历变得丰富了。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位演员的表情很丰富，一看就懂。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "丰富多彩", "label": "复合"}, {"form": "豐富", "label": "繁体"}], "register": "中性", "sense_fingerprint": "经验、知识、内容等方面有很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a75c456c-0a28-4657-b2af-ed1ca1e72345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丰富", "is_correct": true, "explanation": "丰富指经验多，与“经验很”搭配，符合句意。"}, {"text": "安静", "is_correct": false, "explanation": "语义：安静形容环境或声音，不能用来形容经验。"}, {"text": "辣", "is_correct": false, "explanation": "语义：辣形容味道，不能用来形容经验。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：陡峭形容山坡，不能与“经验”搭配。"}], "explanations": {"丰富": "丰富指经验多，与“经验很”搭配，符合句意。", "安静": "语义：安静形容环境或声音，不能用来形容经验。", "辣": "语义：辣形容味道，不能用来形容经验。", "陡峭": "搭配：陡峭形容山坡，不能与“经验”搭配。"}, "sentence_index": 0, "correct_answer": "丰富"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的身材很丰富。", "explanation": "这里应该用〈丰满〉。丰满形容身材饱满，丰富形容的是内容、经验等方面的多，不用于身材。"}, {"text": "这座桥很丰富。", "explanation": "这里应该用〈坚固〉。坚固形容物体结实，丰富指内容或经验多，不能形容桥。"}, {"text": "这间房子很丰富。", "explanation": "这里应该用〈宽敞〉。宽敞形容空间大，丰富指内容、经验等方面的多，不能形容房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丰富", "is_correct": true, "explanation": "丰富指经验多，与“所以公司请她当经理”的语境相符。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：柔软形容质地，不能用来形容工作经验。"}, {"text": "咸", "is_correct": false, "explanation": "语义：咸形容味道，不能用来形容经验。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：清脆形容声音或口感，不能用来形容经验。"}], "explanations": {"丰富": "丰富指经验多，与“所以公司请她当经理”的语境相符。", "柔软": "搭配：柔软形容质地，不能用来形容工作经验。", "咸": "语义：咸形容味道，不能用来形容经验。", "清脆": "语义：清脆形容声音或口感，不能用来形容经验。"}, "sentence_index": 6, "correct_answer": "丰富"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子很丰富。", "explanation": "这里应该用〈结实〉。结实形容物体坚固，丰富不用于形容椅子。"}, {"text": "这位司机的速度很丰富。", "explanation": "这里应该用〈快〉。快形容速度，丰富指内容或经验多，不能形容速度。"}, {"text": "这盏灯很丰富。", "explanation": "这里应该用〈明亮〉。明亮形容光线强，丰富指内容或经验多，不能形容灯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位工程师的经验非常很丰富。", "corrected_sentence": "这位工程师的经验非常丰富。", "error_description": "“非常”和“很”不能同时修饰“丰富”，应只用其一，说“经验非常丰富”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在这个行业的经验很丰富过。", "corrected_sentence": "他在这个行业的经验很丰富。", "error_description": "体标错误：形容词短语“很丰富”之后不能接“过”，应去掉“过”，说“经验很丰富”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
