INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20882, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "论著是专门写出来的书或文章，讲一个重要的道理。", "primary_collocate": null, "pronunciation": "lùn zhù", "ipa": "lwən˥˩ tʂu˥˩", "syllable_count": 2, "sentences": [{"text": "这是一部讲经济道理的论著。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一部论著，讲怎样教育孩子。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部论著说明了保护环境的重要性。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们推荐了一部有名的论著。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者的论著，我读了两遍。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的论著讲的是中国古代的教育。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部论著里有很多有用的道理。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想借几部历史方面的论著。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本论著写得很清楚，学生也能看懂。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生写了十多部论著。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "本", "label": "量词"}, {"form": "論著", "label": "繁体"}], "register": "书面", "sense_fingerprint": "专门写成的、讲重要道理的书或文章", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a75c456c-0a28-4657-b2af-ed1ca1e72345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20882, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "字典", "is_correct": false, "explanation": "语义：“字典”是收录字词的工具书，不“讲经济道理”，与句意不符。"}, {"text": "论著", "is_correct": true, "explanation": "填入〈论著〉：专门写出来、讲道理的著作，与“讲经济道理”搭配，符合句意。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：“菜谱”讲的是烹饪方法，不讲经济道理，与“讲……道理”的对象不符。"}, {"text": "乐谱", "is_correct": false, "explanation": "搭配：“讲……道理”的对象应是说理的文字，乐谱只是音符，不能这样说。"}], "explanations": {"字典": "语义：“字典”是收录字词的工具书，不“讲经济道理”，与句意不符。", "论著": "填入〈论著〉：专门写出来、讲道理的著作，与“讲经济道理”搭配，符合句意。", "菜谱": "语义：“菜谱”讲的是烹饪方法，不讲经济道理，与“讲……道理”的对象不符。", "乐谱": "搭配：“讲……道理”的对象应是说理的文字，乐谱只是音符，不能这样说。"}, "sentence_index": 0, "correct_answer": "论著"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老师家里的宠物是一部论著。", "explanation": "这里应该用〈动物〉。论著是讲一个重要道理的书面著作，不是动物，不能当宠物。"}, {"text": "天冷了，他把这部论著穿在身上去上班。", "explanation": "这里应该用〈大衣〉。论著是讲道理的书面著作，不能穿在身上，御寒应该穿大衣。"}, {"text": "他是我们班最有名的论著。", "explanation": "这里应该用〈学生〉。论著是书，不能用来指人，描述人应用“学生”等词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20882, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食谱", "is_correct": false, "explanation": "搭配：“有很多有用的道理”一般用于说理的书，食谱只有配料和步骤，说不通。"}, {"text": "电话簿", "is_correct": false, "explanation": "语义：电话簿只记录号码，不含道理，与“有很多有用的道理”不符。"}, {"text": "账本", "is_correct": false, "explanation": "语义：账本记录收支，不讲道理，与句意不符。"}, {"text": "论著", "is_correct": true, "explanation": "填入〈论著〉：学术著作，里面可以有很多有用的道理，与“这部”搭配，符合句意。"}], "explanations": {"食谱": "搭配：“有很多有用的道理”一般用于说理的书，食谱只有配料和步骤，说不通。", "电话簿": "语义：电话簿只记录号码，不含道理，与“有很多有用的道理”不符。", "账本": "语义：账本记录收支，不讲道理，与句意不符。", "论著": "填入〈论著〉：学术著作，里面可以有很多有用的道理，与“这部”搭配，符合句意。"}, "sentence_index": 6, "correct_answer": "论著"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这十多部论著是他一生的午饭。", "explanation": "这里应该用〈食物〉。论著是讲道理的书面著作，不是食物，不能当午饭。"}, {"text": "他一生写了十多部论著，每部都讲了一个爱情故事。", "explanation": "这里应该用〈小说〉。论著专指学术著作，不讲爱情故事，讲故事应该用〈小说〉。"}, {"text": "他一生用十多部论著盖了一座房子。", "explanation": "这里应该用〈砖头〉。论著是书，不能当作建材盖房子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师写了一只论著，讲的是中国的历史。", "corrected_sentence": "这位老师写了一本论著，讲的是中国的历史。", "error_description": "量词错误：“论著”是成书的著作，应用“部”或“本”计量，不能用“只”。应说“一本论著”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没看完这部的论著，下周再接着看。", "corrected_sentence": "我还没看完这部论著，下周再接着看。", "error_description": "助词错误：指示词加量词“这部”后直接接名词，不加“的”，应说“这部论著”，不能说“这部的论著”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
