INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20884, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人说好要见面，但没定下具体时间。", "primary_collocate": null, "pronunciation": "yuē", "ipa": "ɥe˥", "syllable_count": 1, "sentences": [{"text": "我约了老同学，以后找时间见面。", "target_word": "约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们约好了，有空再见面。", "target_word": "约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李想约我见面，可是没说几点。", "target_word": "约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他约我下次见面，时间还没定。", "target_word": "约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和老王约过，改天一起吃饭。", "target_word": "约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她约了几个朋友，什么时候见面还不知道。", "target_word": "约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有空吗？我想约你见个面。", "target_word": "约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们约着以后再找机会见面。", "target_word": "约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先约他，时间以后再商量。", "target_word": "约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家约好了要聚一聚，只是没定日子。", "target_word": "约", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "约了", "label": "体标"}, {"form": "约过", "label": "体标"}, {"form": "约着", "label": "体标"}, {"form": "预约", "label": "复合"}, {"form": "約", "label": "繁体"}], "register": "中性", "sense_fingerprint": "约某人：说好要见面，时间未定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3509aa1-4a67-4a10-8fe3-c2b181bf7e77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20884, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约", "is_correct": true, "explanation": "“我约了老同学，以后找时间见面”中，“约”表示事先说好见面，只有它符合语境。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与“以后找时间见面”的约定矛盾。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”一般不用来带人作宾语，“修了老同学”搭配不当。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能带“老同学”作宾语表示见面的约定。"}], "explanations": {"约": "“我约了老同学，以后找时间见面”中，“约”表示事先说好见面，只有它符合语境。", "扔": "语义：“扔”表示丢弃，与“以后找时间见面”的约定矛盾。", "修": "搭配：“修”一般不用来带人作宾语，“修了老同学”搭配不当。", "洗": "搭配：“洗”不能带“老同学”作宾语表示见面的约定。"}, "sentence_index": 0, "correct_answer": "约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我约了一箱牛奶，给孩子喝。", "explanation": "这里应该用〈买〉。“约”表示两人说好见面，买牛奶要用“买”。"}, {"text": "我约了一张去上海的机票，下周出发。", "explanation": "这里应该用〈订〉。“约”表示两人说好见面，订机票要用“订”。"}, {"text": "他约了那本书，下周还给我。", "explanation": "这里应该用〈借〉。“约”用于与人商定见面，借书要用“借”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7f0748-37a2-4643-a9f5-6c5c410a975b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约", "is_correct": true, "explanation": "“我想约你见个面”中，“约”表示约定见面，只有它符合语境。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”表示责骂，与“见个面”的约定意思不符。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”表示殴打，与“见个面”的约定意思不符。"}, {"text": "拖", "is_correct": false, "explanation": "语义：“拖”表示拉动或拖延，不表示事先说好见面，与“见个面”的约定意思不符。"}], "explanations": {"约": "“我想约你见个面”中，“约”表示约定见面，只有它符合语境。", "骂": "语义：“骂”表示责骂，与“见个面”的约定意思不符。", "打": "语义：“打”表示殴打，与“见个面”的约定意思不符。", "拖": "语义：“拖”表示拉动或拖延，不表示事先说好见面，与“见个面”的约定意思不符。"}, "sentence_index": 6, "correct_answer": "约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他约了两天假，下周回老家。", "explanation": "这里应该用〈请〉。“约”表示两人说好见面，请假要用“请”。"}, {"text": "他约了一台新冰箱，下周一送货。", "explanation": "这里应该用〈买〉。“约”表示两人说好见面，买冰箱要用“买”。"}, {"text": "他们约了这把伞，明天还要用。", "explanation": "这里应该用〈借〉。“约”表示两人说好见面，借东西要用“借”，“明天还要用”也说明是借来的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7f0748-37a2-4643-a9f5-6c5c410a975b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我约了了小李下午见面。", "corrected_sentence": "我约了小李下午见面。", "error_description": "“了”重复：动词“约”后只用一个“了”，写成“约了了小李”是错误的，应为“约了小李下午见面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7f0748-37a2-4643-a9f5-6c5c410a975b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家约好好了周末聚一聚。", "corrected_sentence": "大家约好了周末聚一聚。", "error_description": "补语“好”重复：“约好了”中“好”只用一次，写成“约好好了”是错误的，应为“约好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7f0748-37a2-4643-a9f5-6c5c410a975b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
