INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20888, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "篇幅短小、装订成册的薄书，常用来介绍或说明事情。", "primary_collocate": null, "pronunciation": "xiǎo cè zi", "ipa": "ɕjaʊ˨˩˦ tsʰɤ˥˩ tsɨ", "syllable_count": 3, "sentences": [{"text": "桌子上有一本小册子。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小册子介绍了这个城市的历史。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的小册子很薄，也很轻。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天读一点小册子上的故事。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院门口有很多介绍健康知识的小册子。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把小册子放在书包里。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每个学生一本小册子。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小册子是妹妹的。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在小册子上写了自己的名字。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小册子又小又薄，放在口袋里很方便。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "小冊子", "label": "繁体"}], "register": "中性", "sense_fingerprint": "页数少、薄薄的一本，用来介绍、说明的小书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a75c456c-0a28-4657-b2af-ed1ca1e72345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20888, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "西瓜", "is_correct": false, "explanation": "搭配：“本”用于书册，西瓜应说“个”。"}, {"text": "小册子", "is_correct": true, "explanation": "“桌子上有一本小册子”中，“本”与“小册子”搭配，小册子是能放在桌上的小书。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是能放在桌子上的实物，句子不成立。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“本”不用于钥匙，钥匙应说“把”或“串”。"}], "explanations": {"西瓜": "搭配：“本”用于书册，西瓜应说“个”。", "小册子": "“桌子上有一本小册子”中，“本”与“小册子”搭配，小册子是能放在桌上的小书。", "天气": "语义：天气不是能放在桌子上的实物，句子不成立。", "钥匙": "搭配：“本”不用于钥匙，钥匙应说“把”或“串”。"}, "sentence_index": 0, "correct_answer": "小册子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上喝这本小册子。", "explanation": "这里应该用〈牛奶〉。牛奶可以喝，小册子是印刷品，不能喝。"}, {"text": "这本小册子有一千多页，要用两只手才能拿起来。", "explanation": "这里应该用〈字典〉。小册子是小小的薄书，不会有一千多页，那样厚的书要用“字典”。"}, {"text": "下雨了，我打开一本小册子挡雨。", "explanation": "这里应该用〈雨伞〉。雨伞用来挡雨，小册子是薄薄的小书，不能当伞用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饼干", "is_correct": false, "explanation": "搭配：饼干用“包”或“袋”，不用“本”。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不是书册，老师不会把闹钟当教材发给每个学生。"}, {"text": "小册子", "is_correct": true, "explanation": "“一本小册子”与“老师给每个学生”搭配，小册子是可以发给学生的小书。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是书，不能作为教材发给学生。"}], "explanations": {"饼干": "搭配：饼干用“包”或“袋”，不用“本”。", "闹钟": "语义：闹钟不是书册，老师不会把闹钟当教材发给每个学生。", "小册子": "“一本小册子”与“老师给每个学生”搭配，小册子是可以发给学生的小书。", "石头": "语义：石头不是书，不能作为教材发给学生。"}, "sentence_index": 6, "correct_answer": "小册子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这本小册子当早饭吃掉了。", "explanation": "这里应该用〈三明治〉。“吃”的对象是食物，小册子是印刷品，不能当早饭吃。"}, {"text": "晚会上他表演了一个小册子。", "explanation": "这里应该用〈节目〉。“表演”的对象是节目、角色，小册子不能被表演。"}, {"text": "他每天骑这本小册子去学校。", "explanation": "这里应该用〈自行车〉。自行车可以骑，小册子是印刷品，不能骑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那只小册子送给了老师。", "corrected_sentence": "他把那本小册子送给了老师。", "error_description": "错误：“小册子”应用量词“本”，不能用“只”（“只”用于动物等）。应说“那本小册子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天晚上都吃小册子。", "corrected_sentence": "我每天晚上都读小册子。", "error_description": "搭配错误：“吃”的对象应是食物，小册子是印刷品，不能吃，应说“读”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20890, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缺乏", "is_correct": true, "explanation": "正确：“缺乏”与“富含”意思相反，指某物里某种成分很少或没有。"}, {"text": "移动", "is_correct": false, "explanation": "移动：动词，与“富含”的意义无关。"}, {"text": "购买", "is_correct": false, "explanation": "购买：动词，与“富含”的意义无关。"}, {"text": "欣赏", "is_correct": false, "explanation": "欣赏：动词，与“富含”的意义无关。"}], "correct_answer": "缺乏", "explanations": {"缺乏": "正确：“缺乏”与“富含”意思相反，指某物里某种成分很少或没有。", "移动": "移动：动词，与“富含”的意义无关。", "购买": "购买：动词，与“富含”的意义无关。", "欣赏": "欣赏：动词，与“富含”的意义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20890, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缺乏", "is_correct": true, "explanation": "正确：“缺乏”与“富含”意思相反，指某物里某种成分不足。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论：动词，与“富含”的意义无关。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：动词，与“富含”的意义无关。"}, {"text": "倾听", "is_correct": false, "explanation": "倾听：动词，与“富含”的意义无关。"}], "correct_answer": "缺乏", "explanations": {"缺乏": "正确：“缺乏”与“富含”意思相反，指某物里某种成分不足。", "讨论": "讨论：动词，与“富含”的意义无关。", "旅行": "旅行：动词，与“富含”的意义无关。", "倾听": "倾听：动词，与“富含”的意义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20890, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "东西里有很多，比如汤里有很多肉。", "primary_collocate": null, "pronunciation": "fù hán", "ipa": "fu˥˩ xan˧˥", "syllable_count": 2, "sentences": [{"text": "这种豆子富含蛋白质，是素食者的好选择。", "target_word": "富含", "complexity_tier": "T3", "furigana": "zhè zhǒng dòu zi fù hán dàn bái zhì, shì sù shí zhě de hǎo xuǎn zé.", "sentence_source": "generated"}, {"text": "这种核桃富含油脂，每天吃一小把就好。", "target_word": "富含", "complexity_tier": "T3", "furigana": "zhè zhǒng hé tao fù hán yóu zhī, měi tiān chī yì xiǎo bǎ jiù hǎo.", "sentence_source": "generated"}, {"text": "水果里富含水分。", "target_word": "富含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯果汁富含糖，小孩别喝太多。", "target_word": "富含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红薯富含纤维，有助于消化。", "target_word": "富含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种米富含营养，孩子爱吃。", "target_word": "富含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑木耳富含铁，经常吃对身体有好处。", "target_word": "富含", "complexity_tier": "T3", "furigana": "hēi mù ěr fù hán tiě, jīng cháng chī duì shēn tǐ yǒu hǎo chù.", "sentence_source": "generated"}, {"text": "西瓜富含水分，夏天吃最好。", "target_word": "富含", "complexity_tier": "T3", "furigana": "xī guā fù hán shuǐ fèn, xià tiān chī zuì hǎo.", "sentence_source": "generated"}, {"text": "小米富含镁，对睡眠有帮助。", "target_word": "富含", "complexity_tier": "T3", "furigana": "xiǎo mǐ fù hán měi, duì shuì mián yǒu bāng zhù.", "sentence_source": "generated"}, {"text": "花生油富含不饱和脂肪酸，适合炒菜。", "target_word": "富含", "complexity_tier": "T3", "furigana": "huā shēng yóu fù hán bù bǎo hé zhī fáng suān, shì hé chǎo cài.", "sentence_source": "generated"}], "morphological_forms": [{"form": "富含着", "label": "体标"}], "register": "书面", "sense_fingerprint": "富含:动词:东西里有很多某样东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f6b3972-a8a9-4c30-a116-104a85e3fab6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "富含", "is_correct": true, "explanation": "正确：“富含”表示豆子里蛋白质多，与“是素食者的好选择”相符。"}, {"text": "缺乏", "is_correct": false, "explanation": "语义：“缺乏蛋白质”与“素食者的好选择”的句意相悖。"}, {"text": "消化", "is_correct": false, "explanation": "配价：“消化”要求有消化能力的主语，豆子不能消化蛋白质。"}, {"text": "分解", "is_correct": false, "explanation": "语义：“分解”会使蛋白质被破坏，与“是素食者的好选择”的句意相悖。"}], "explanations": {"富含": "正确：“富含”表示豆子里蛋白质多，与“是素食者的好选择”相符。", "缺乏": "语义：“缺乏蛋白质”与“素食者的好选择”的句意相悖。", "消化": "配价：“消化”要求有消化能力的主语，豆子不能消化蛋白质。", "分解": "语义：“分解”会使蛋白质被破坏，与“是素食者的好选择”的句意相悖。"}, "sentence_index": 0, "correct_answer": "富含"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校富含二十个班级。", "explanation": "这里应该用〈有〉。富含只说某物里含有大量成分，学校的班级不是成分，应说“有二十个班级”。"}, {"text": "这个水瓶富含一升水。", "explanation": "这里应该用〈装着〉。富含讲的是某物的成分，水瓶里的水不是成分，应说“装着一升水”。"}, {"text": "农场富含十头牛。", "explanation": "这里应该用〈拥有〉。富含不用于说明场所拥有动物，应说“拥有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "富含", "is_correct": true, "explanation": "正确：“富含”表示黑木耳里铁多，与“对身体有好处”相符。"}, {"text": "蒸发", "is_correct": false, "explanation": "搭配：“蒸发”一般用于水分等液体，不说“蒸发铁”。"}, {"text": "排斥", "is_correct": false, "explanation": "语义：“排斥”是推开、拒绝的意思，“排斥铁”与“对身体有好处”的句意相悖。"}, {"text": "倒出", "is_correct": false, "explanation": "搭配：“倒出”用于液体或颗粒，不说“倒出铁”。"}], "explanations": {"富含": "正确：“富含”表示黑木耳里铁多，与“对身体有好处”相符。", "蒸发": "搭配：“蒸发”一般用于水分等液体，不说“蒸发铁”。", "排斥": "语义：“排斥”是推开、拒绝的意思，“排斥铁”与“对身体有好处”的句意相悖。", "倒出": "搭配：“倒出”用于液体或颗粒，不说“倒出铁”。"}, "sentence_index": 6, "correct_answer": "富含"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个广场富含一百张长椅。", "explanation": "这里应该用〈设有〉。富含说的是某物里含有的成分，长椅不是成分，应说“设有”。"}, {"text": "他富含经验。", "explanation": "这里应该用〈富有〉。富有可用于经验、学识等抽象的事物；“富含经验”不自然，应说“富有经验”。"}, {"text": "这家公司富含一百名员工。", "explanation": "这里应该用〈拥有〉。富含说的是某物里含有的成分，员工不是成分，应说“拥有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "紫薯富含过花青素，常吃对眼睛好。", "corrected_sentence": "紫薯富含花青素，常吃对眼睛好。", "error_description": "错误：“富含”是状态动词，不能加表示经历的助词“过”，应删去“过”，说“紫薯富含花青素”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "核桃富含过亚麻酸，适合早上吃。", "corrected_sentence": "核桃富含亚麻酸，适合早上吃。", "error_description": "错误：“富含”是状态动词，不能加表示经历的助词“过”，应删去“过”，说“核桃富含亚麻酸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0153e33-fc8c-43ae-87de-00b8b3114fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
