INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20892, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "非常想要得到某样东西。", "primary_collocate": null, "pronunciation": "kě qiú", "ipa": "kʰɤ˨˩˦ tɕʰjoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "沙漠里的旅人渴求一口清水。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗渴求着主人的拥抱。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他渴求一份稳定的工作，已经找了很久。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子渴求关爱，常常主动靠近大人。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人渴求健康，每天按时吃药。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她渴求过一个属于自己的房间。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民渴求一场及时雨，田里的土都干了。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把所有的钱都花光了，仍然渴求更多。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的孩子渴求新书，眼睛里满是期待。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她渴求着一个温暖的家。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "渴求着", "label": "体标：着"}, {"form": "渴求过", "label": "体标：过"}, {"form": "渴求了", "label": "体标：了"}], "register": "书面", "sense_fingerprint": "非常想要得到某样东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b713ff2c-e8ec-4a37-94c3-89752342a172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "渴求", "is_correct": true, "explanation": "「渴求」指迫切想要，与沙漠中缺水、急需清水的语境相合。"}, {"text": "厌恶", "is_correct": false, "explanation": "语义：「厌恶」是反感，与沙漠里急需清水的处境相反。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：「嫌弃」是看不上，与旅人急需清水的语境矛盾。"}, {"text": "轻视", "is_correct": false, "explanation": "搭配：「轻视」的对象多是人或看法，不说「轻视一口清水」。"}], "explanations": {"渴求": "「渴求」指迫切想要，与沙漠中缺水、急需清水的语境相合。", "厌恶": "语义：「厌恶」是反感，与沙漠里急需清水的处境相反。", "嫌弃": "语义：「嫌弃」是看不上，与旅人急需清水的语境矛盾。", "轻视": "搭配：「轻视」的对象多是人或看法，不说「轻视一口清水」。"}, "sentence_index": 0, "correct_answer": "渴求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我渴求你明天来一趟，帮我看看。", "explanation": "这里应该用〈请求〉。「渴求」表示自己迫切想要，不用于请别人来做某事。"}, {"text": "他渴求把那本书送给朋友。", "explanation": "这里应该用〈打算〉。「渴求」表示迫切想得到某样东西，不能用来表示把东西送给别人，说要送出去应用「打算」。"}, {"text": "我渴求明天不下雨，好去郊游。", "explanation": "这里应该用〈希望〉。「渴求」的宾语一般是具体的东西或目标，不接「明天不下雨」这类句子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "渴求", "is_correct": true, "explanation": "「渴求」指迫切想要，与「及时雨」和「土都干了」所表达的急需相合。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：「拒绝」是不接受，与田里的土已经干了、急需雨水的语境矛盾。"}, {"text": "躲避", "is_correct": false, "explanation": "语义：「躲避」表示避开，与急需及时雨的语境不符。"}, {"text": "忽视", "is_correct": false, "explanation": "搭配：「忽视」后接的多是人或事物，不常说「忽视一场雨」。"}], "explanations": {"渴求": "「渴求」指迫切想要，与「及时雨」和「土都干了」所表达的急需相合。", "拒绝": "语义：「拒绝」是不接受，与田里的土已经干了、急需雨水的语境矛盾。", "躲避": "语义：「躲避」表示避开，与急需及时雨的语境不符。", "忽视": "搭配：「忽视」后接的多是人或事物，不常说「忽视一场雨」。"}, "sentence_index": 6, "correct_answer": "渴求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈渴求我们早点回家吃饭。", "explanation": "这里应该用〈催促〉。「渴求」表示自己迫切想要，不用于催别人做事。"}, {"text": "我们在门口渴求你。", "explanation": "这里应该用〈等待〉。「渴求」指迫切想得到，不表示在某处耐心等候某人。"}, {"text": "老师渴求我们把作业交上来。", "explanation": "这里应该用〈要求〉。「渴求」表示自己迫切想得到某样东西，不能用来让别人做某事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在渴求过一个能听他说话的人。", "corrected_sentence": "他正在渴求着一个能听他说话的人。", "error_description": "体标「过」用错：「正在」表示动作进行中，「过」表示曾经有过，二者不能共现，应用「着」，说「正在渴求着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在渴求了一位能陪他下棋的朋友。", "corrected_sentence": "他正在渴求着一位能陪他下棋的朋友。", "error_description": "体标「了」用错：「正在」表示进行中，不能与表示完成的「了」共现，应用「着」，说「正在渴求着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
