INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20894, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大家一起让事情变得更公平、更自由。", "primary_collocate": null, "pronunciation": "mín zhǔ huà", "ipa": "min˧˥ ʈʂu˨˩˦ xua˥˩", "syllable_count": 3, "sentences": [{"text": "公司开始民主化，每个人都能提意见。", "target_word": "民主化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班级要民主化，大家一起决定规则。", "target_word": "民主化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的事越来越民主化了，大家都能投票。", "target_word": "民主化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想让课堂民主化，请学生一起定规矩。", "target_word": "民主化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个家庭很早就民主化了，孩子也能参加讨论。", "target_word": "民主化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把小区的管理民主化。", "target_word": "民主化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俱乐部民主化以后，会员可以投票选会长。", "target_word": "民主化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想让学校民主化，先要听听学生的想法。", "target_word": "民主化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的组织一直在民主化，规则越来越公平。", "target_word": "民主化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室民主化后，大家的心情好多了。", "target_word": "民主化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "民主化了", "label": "体标"}], "register": "书面", "sense_fingerprint": "民主化|动词|大家一起让事情变得更公平更自由", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dab0c558-bacf-42b5-ac45-3bf523f0ba2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民主化", "is_correct": true, "explanation": "正确。“公司开始民主化”指让决策向全体员工开放，与“每个人都能提意见”一致。"}, {"text": "垄断", "is_correct": false, "explanation": "语义：“垄断”是独占，与“每个人都能提意见”的意思相反。"}, {"text": "保密", "is_correct": false, "explanation": "语义：“保密”是封闭信息，与“每个人都能提意见”冲突。"}, {"text": "管理", "is_correct": false, "explanation": "配价：“管理”后面需要带宾语（管理什么），单说“公司开始管理”语义不完整。"}], "explanations": {"民主化": "正确。“公司开始民主化”指让决策向全体员工开放，与“每个人都能提意见”一致。", "垄断": "语义：“垄断”是独占，与“每个人都能提意见”的意思相反。", "保密": "语义：“保密”是封闭信息，与“每个人都能提意见”冲突。", "管理": "配价：“管理”后面需要带宾语（管理什么），单说“公司开始管理”语义不完整。"}, "sentence_index": 0, "correct_answer": "民主化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要民主化食堂的饭菜。", "explanation": "这里应该用〈改善〉。“民主化”指让事情或组织变得更公平自由，饭菜的质量要说“改善”。"}, {"text": "这篇文章的字数需要民主化。", "explanation": "这里应该用〈增加〉。字数的多少要说“增加”，“民主化”不能用于数量。"}, {"text": "医生说他的身体民主化得很好。", "explanation": "这里应该用〈恢复〉。身体的状况要说“恢复”，“民主化”只用于让事情变得公平自由。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民主化", "is_correct": true, "explanation": "正确。俱乐部民主化之后，会员才能投票选会长，“民主化”与句中的投票一致。"}, {"text": "解散", "is_correct": false, "explanation": "语义：俱乐部解散后就无法投票选会长，与句意冲突。"}, {"text": "垄断", "is_correct": false, "explanation": "语义：“垄断”是独占，会员无法投票，与句意相反。"}, {"text": "闭关", "is_correct": false, "explanation": "搭配：“闭关”多用于“闭关自守”“闭关锁国”，不能直接说“俱乐部闭关”。"}], "explanations": {"民主化": "正确。俱乐部民主化之后，会员才能投票选会长，“民主化”与句中的投票一致。", "解散": "语义：俱乐部解散后就无法投票选会长，与句意冲突。", "垄断": "语义：“垄断”是独占，会员无法投票，与句意相反。", "闭关": "搭配：“闭关”多用于“闭关自守”“闭关锁国”，不能直接说“俱乐部闭关”。"}, "sentence_index": 6, "correct_answer": "民主化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这块石头民主化了。", "explanation": "这里应该用〈搬〉。石头是物体，移动它要说“搬”，“民主化”指让事情或组织变得更公平自由。"}, {"text": "这份报告的颜色民主化了。", "explanation": "这里应该用〈变〉。颜色的改变要说“变”，“民主化”不指颜色的变化。"}, {"text": "两国的矛盾不断民主化。", "explanation": "这里应该用〈激化〉。矛盾加深要说“激化”，“民主化”表示向公平自由转变，句意完全相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校的管理越来越民主化着。", "corrected_sentence": "学校的管理越来越民主化了。", "error_description": "错误：“越来越……”表示变化已经发生，句末要用“了”，不能用表示持续状态的“着”。应说“越来越民主化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班正在民主化了。", "corrected_sentence": "我们班正在民主化。", "error_description": "错误：“正在”表示动作进行中，不能与“了”同用。应去掉“了”，说“正在民主化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
