INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20896, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西或钱从一个地方传到另一个地方。", "primary_collocate": null, "pronunciation": "liú tōng", "ipa": "ljoʊ˧˥ tʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这种货币在全国流通。", "target_word": "流通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路不好，货物就很难流通。", "target_word": "流通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱在市场上流通，经济才会好。", "target_word": "流通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种旧钱已经不能流通了。", "target_word": "流通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物在两个城市之间流通。", "target_word": "流通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新路修好以后，水果流通得很快。", "target_word": "流通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的东西流通得很慢。", "target_word": "流通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场上流通着各种各样的商品。", "target_word": "流通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱不流通，生意就做不大。", "target_word": "流通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想让更多的钱流通起来。", "target_word": "流通", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流通了", "label": "体标"}, {"form": "流通着", "label": "体标"}], "register": "中性", "sense_fingerprint": "商品或钱在不同地方之间流动传递", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f52a17a-78f7-4fb3-bb7f-3ca4d49b212e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20896, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流通", "is_correct": true, "explanation": "正确：货币在全国各地传递使用，符合句意。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”用于生物，货币不生长。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：货币不会睡觉，与句意不符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：货币不会生病，与句意不符。"}], "explanations": {"流通": "正确：货币在全国各地传递使用，符合句意。", "生长": "搭配：“生长”用于生物，货币不生长。", "睡觉": "语义：货币不会睡觉，与句意不符。", "生病": "语义：货币不会生病，与句意不符。"}, "sentence_index": 0, "correct_answer": "流通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "很多农民工在城市里流通。", "explanation": "这里应该用〈流动〉。流动指人或物不固定地移动，农民工到各城市务工要说流动，不说流通。"}, {"text": "这首歌在年轻人中很流通。", "explanation": "这里应该用〈流行〉。流通只用于货物、钱币，歌曲受欢迎要说流行。"}, {"text": "这篇文章读起来很流通。", "explanation": "这里应该用〈流畅〉。流畅形容文字、语言读起来顺，文章读起来顺要说流畅；流通指东西或钱从一地传到另一地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流通", "is_correct": true, "explanation": "正确：村子里的东西在各处传递得慢，符合句意。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：东西不会吃饭，与句意不符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：东西不会唱歌，与句意不符。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：“发烧”用于人或动物，不说东西发烧。"}], "explanations": {"流通": "正确：村子里的东西在各处传递得慢，符合句意。", "吃饭": "语义：东西不会吃饭，与句意不符。", "唱歌": "语义：东西不会唱歌，与句意不符。", "发烧": "搭配：“发烧”用于人或动物，不说东西发烧。"}, "sentence_index": 6, "correct_answer": "流通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "疾病在城市里迅速流通。", "explanation": "这里应该用〈传播〉。疾病的扩散要说传播，流通只用于货物、钱币。"}, {"text": "泪水从他的脸上流通下来。", "explanation": "这里应该用〈流淌〉。液体顺着往下流要说流淌，流通指货物、钱币的传递。"}, {"text": "这家公司的老客户不断流通。", "explanation": "这里应该用〈流失〉。客户离开、数量减少要说流失，流通不用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "货物流通地很快。", "corrected_sentence": "货物流通得很快。", "error_description": "补语前应用“得”，不用“地”。“地”修饰动词，“得”连接动词与补语，应说“流通得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种货币曾经在全国流通着过。", "corrected_sentence": "这种货币曾经在全国流通过。", "error_description": "“着”和“过”不能同时用在同一动词后，应说“流通过”，不说“流通着过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
