INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20900, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人说不一样的话，都想让别人听自己的。", "primary_collocate": null, "pronunciation": "zhēng biàn", "ipa": "[ʈʂɤŋ˥ pjɛn˥˩]", "syllable_count": 2, "sentences": [{"text": "弟弟和姐姐又在争辩了。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了玩什么游戏而争辩。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别争辩了，快吃饭吧。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人争辩得脸都红了。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想和你争辩这件事。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们争辩着该去哪儿玩。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们争辩了一个晚上。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈听见孩子们在争辩。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间不要为小事争辩。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他俩争辩谁先到了教室。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "争辩了", "label": "体标"}, {"form": "争辩着", "label": "体标"}, {"form": "争辩过", "label": "体标"}], "register": "中性", "sense_fingerprint": "两人说法不同，都想让对方听自己的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b713ff2c-e8ec-4a37-94c3-89752342a172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20900, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "争辩", "is_correct": true, "explanation": "正确。争辩指两个人说法不同，都想让对方听自己的。"}, {"text": "政变", "is_correct": false, "explanation": "「zhèng（第四声）与 zhēng（第一声）声调不同，意思是武力推翻政权」。"}, {"text": "生变", "is_correct": false, "explanation": "「shēng 与 zhēng 声母不同（sh 与 zh），意思是出现变化」。"}, {"text": "整编", "is_correct": false, "explanation": "「zhěng（第三声）与 zhēng 声调不同，biān 与 biàn 声调也不同，意思是整顿编制」。"}], "explanations": {"争辩": "正确。争辩指两个人说法不同，都想让对方听自己的。", "政变": "「zhèng（第四声）与 zhēng（第一声）声调不同，意思是武力推翻政权」。", "生变": "「shēng 与 zhēng 声母不同（sh 与 zh），意思是出现变化」。", "整编": "「zhěng（第三声）与 zhēng 声调不同，biān 与 biàn 声调也不同，意思是整顿编制」。"}, "sentence_index": null, "correct_answer": "争辩"}, "level_3": {"options": [{"text": "争辩", "is_correct": true, "explanation": "正确。「弟弟和姐姐又在……了」说的是两人说法不同、互相争论，只有「争辩」符合。"}, {"text": "辞职", "is_correct": false, "explanation": "语义：辞职是放弃工作的职位，孩子之间的口角不能用它表示。"}, {"text": "投资", "is_correct": false, "explanation": "语义：投资指投入资金以求收益，与两个孩子之间的争论无关。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚是成年人的事，与两个孩子的争论无关。"}], "explanations": {"争辩": "正确。「弟弟和姐姐又在……了」说的是两人说法不同、互相争论，只有「争辩」符合。", "辞职": "语义：辞职是放弃工作的职位，孩子之间的口角不能用它表示。", "投资": "语义：投资指投入资金以求收益，与两个孩子之间的争论无关。", "结婚": "语义：结婚是成年人的事，与两个孩子的争论无关。"}, "sentence_index": 0, "correct_answer": "争辩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上在公园里争辩半个小时，身体越来越好。", "explanation": "这里应该用〈锻炼〉。争辩指两人说法不同、互相说理，不能表示运动健身。"}, {"text": "她为了这次考试每天认真争辩，终于考出了好成绩。", "explanation": "这里应该用〈复习〉。复习指把学过的内容再学一遍；争辩指用道理互相说服，不能用于温习功课。"}, {"text": "他一个人坐在床上争辩了很久。", "explanation": "争辩需要至少两方持不同意见、互相说理，一个人独自说话不能叫争辩，应说〈自言自语〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "争辩", "is_correct": true, "explanation": "正确。「他们……了一个晚上」说的是两人长时间互相说理，只有「争辩」符合。"}, {"text": "发射", "is_correct": false, "explanation": "语义：发射指把火箭或信号送出去，不能表示他们之间的说理。"}, {"text": "运输", "is_correct": false, "explanation": "语义：运输指把货物从一地运到另一地，与两人之间的说理无关。"}, {"text": "颁布", "is_correct": false, "explanation": "语义：颁布的对象是法规或政令，不能用来描述两人的争论。"}], "explanations": {"争辩": "正确。「他们……了一个晚上」说的是两人长时间互相说理，只有「争辩」符合。", "发射": "语义：发射指把火箭或信号送出去，不能表示他们之间的说理。", "运输": "语义：运输指把货物从一地运到另一地，与两人之间的说理无关。", "颁布": "语义：颁布的对象是法规或政令，不能用来描述两人的争论。"}, "sentence_index": 6, "correct_answer": "争辩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里争辩了一桌好菜。", "explanation": "这里应该用〈做〉。争辩指两人说法不同、互相说理，不能表示做饭。"}, {"text": "他在操场上大声争辩了一首歌。", "explanation": "这里应该用〈唱〉。唱指用声音表现歌曲；争辩指用道理互相说服，不能用来形容唱歌。"}, {"text": "大家在商场门口争辩打折商品。", "explanation": "这里应该用〈抢购〉。抢购指争着买，争辩用于讲道理，不能用来形容争着买东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他俩正在争辩了，谁也不让谁。", "corrected_sentence": "他俩正在争辩着，谁也不让谁。", "error_description": "时态错误：「正在」表示进行中，句中要用「着」，不能用「了」，应说「正在争辩着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们争辩深夜才停下来。", "corrected_sentence": "他们争辩到深夜才停下来。", "error_description": "补语错误：表示争论持续到某个时间，要用「到」，应说「争辩到深夜」，这里缺少「到」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20902, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "整体", "is_correct": true, "explanation": "“整体”与“部分”构成反义，指全部而不是一小块。"}, {"text": "角落", "is_correct": false, "explanation": "“角落”指边角的地方，与“部分”不构成反义。"}, {"text": "碎片", "is_correct": false, "explanation": "“碎片”指破碎的小块，与“部分”不构成反义。"}, {"text": "细节", "is_correct": false, "explanation": "“细节”指细小的情节或要点，与“部分”不构成反义。"}], "correct_answer": "整体", "explanations": {"整体": "“整体”与“部分”构成反义，指全部而不是一小块。", "角落": "“角落”指边角的地方，与“部分”不构成反义。", "碎片": "“碎片”指破碎的小块，与“部分”不构成反义。", "细节": "“细节”指细小的情节或要点，与“部分”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20902, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "整体", "is_correct": true, "explanation": "“整体”与“部分”构成反义，指全部而不是一小块。"}, {"text": "边缘", "is_correct": false, "explanation": "“边缘”指物体的边沿，与“部分”不构成反义。"}, {"text": "片段", "is_correct": false, "explanation": "“片段”指完整内容中的一段，与“部分”不构成反义。"}, {"text": "零件", "is_correct": false, "explanation": "“零件”指机器中的组成件，与“部分”不构成反义。"}], "correct_answer": "整体", "explanations": {"整体": "“整体”与“部分”构成反义，指全部而不是一小块。", "边缘": "“边缘”指物体的边沿，与“部分”不构成反义。", "片段": "“片段”指完整内容中的一段，与“部分”不构成反义。", "零件": "“零件”指机器中的组成件，与“部分”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20902, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "整体中的一小块。", "primary_collocate": null, "pronunciation": "bù fen", "ipa": "pu˥˩ fən", "syllable_count": 2, "sentences": [{"text": "这本书的第一部分很有意思。", "target_word": "部分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我只看了电影的一部分。", "target_word": "部分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车的这个部分坏了，要修一下。", "target_word": "部分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章分为三个部分。", "target_word": "部分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们吃了蛋糕的一部分。", "target_word": "部分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把工资的一部分寄给了家里。", "target_word": "部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你读一下这段话的最后一部分。", "target_word": "部分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班只有一部分同学去过上海。", "target_word": "部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试中最难的部分是作文。", "target_word": "部分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间的这个部分很暗，需要多装一盏灯。", "target_word": "部分", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大部分", "label": "复合"}, {"form": "小部分", "label": "复合"}], "register": "中性", "sense_fingerprint": "整体中的一块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb662756-0b78-4edf-9c5e-051c04c57dff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20902, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "部分", "is_correct": true, "explanation": "正确答案。“部分”指整体中的一块，与“这本书的第一”及“很有意思”相符。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指人或动物的温度，不能作书的组成部分。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：“雨水”指降下的雨，不能作书的组成部分。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“这本书的第一”后接“鞋子”搭配不通。"}], "explanations": {"部分": "正确答案。“部分”指整体中的一块，与“这本书的第一”及“很有意思”相符。", "体温": "语义：“体温”指人或动物的温度，不能作书的组成部分。", "雨水": "语义：“雨水”指降下的雨，不能作书的组成部分。", "鞋子": "搭配：“这本书的第一”后接“鞋子”搭配不通。"}, "sentence_index": 0, "correct_answer": "部分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都要喝一杯部分。", "explanation": "“部分”指整体中的一块，不是饮料，不能“喝一杯”。"}, {"text": "我每天坐部分去学校。", "explanation": "“部分”不是交通工具，不能“坐”，这里误用了它的含义。"}, {"text": "这个部分会唱歌，声音很好听。", "explanation": "“部分”指整体中的一块，不是人或动物，不能“唱歌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "部分", "is_correct": true, "explanation": "正确答案。“部分”指整体中的一块，与“这段话的最后”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能作这段话的最后组成部分。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指价钱，与这段话的内容不相符。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”不能与“这段话的最后”搭配。"}], "explanations": {"部分": "正确答案。“部分”指整体中的一块，与“这段话的最后”相符。", "颜色": "语义：“颜色”不能作这段话的最后组成部分。", "价格": "语义：“价格”指价钱，与这段话的内容不相符。", "脚步": "搭配：“脚步”不能与“这段话的最后”搭配。"}, "sentence_index": 6, "correct_answer": "部分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把蛋糕部分成三块。", "explanation": "“部分”是名词，不能作动词表示切开。切分东西要用“分”，这里误用了“部分”的词性和含义。"}, {"text": "他在财务部分工作。", "explanation": "这里应该用〈部门〉。“部分”指整体中的一小块，不指机构或单位，指财务机构要用“部门”。"}, {"text": "他参加了部分，每天训练很辛苦。", "explanation": "这里应该用〈部队〉。“部分”指整体中的一小块，不能指军队这类组织。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把工资的一只部分寄回了老家。", "corrected_sentence": "他把工资的一部分寄回了老家。", "error_description": "量词错误：“只”多用于动物，不能修饰“部分”，正确为“一部分”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇论文的一座部分还没有写完。", "corrected_sentence": "这篇论文的一部分还没有写完。", "error_description": "量词错误：“座”用于山、房屋等大型固定的东西，不能修饰“部分”，正确为“这篇论文的一部分”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
