INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20906, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示完全没有、一点也不，用在动词或形容词前，强调否定。", "primary_collocate": null, "pronunciation": "háo bù", "ipa": "[xɑʊ˧˥ pu˥˩]", "syllable_count": 2, "sentences": [{"text": "听到坏消息，他毫不惊讶。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她毫不留情地指出了我的错误。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子毫不怕生。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人毫不动摇地坚持着自己的想法。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毫不隐瞒地说出了真相。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这样的批评，我毫不在意。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队毫不松懈，继续练习。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她毫不迟疑地接过了电话。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥毫不让步，我也不让。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法毫不复杂，一学就会。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，用在动词或形容词前，表示完全不、一点也不", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b713ff2c-e8ec-4a37-94c3-89752342a172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20906, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毫不", "is_correct": true, "explanation": "正确：“毫不惊讶”即一点也不惊讶，与“听到坏消息”的语境相合。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续，与“听到坏消息”时的瞬间反应不合。"}, {"text": "拼命", "is_correct": false, "explanation": "语义：“拼命”表示竭力，与“惊讶”这种不由自主的反应冲突。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行，与“听到”的瞬间反应冲突。"}], "explanations": {"毫不": "正确：“毫不惊讶”即一点也不惊讶，与“听到坏消息”的语境相合。", "一直": "语义：“一直”表示持续，与“听到坏消息”时的瞬间反应不合。", "拼命": "语义：“拼命”表示竭力，与“惊讶”这种不由自主的反应冲突。", "正在": "体貌：“正在”表示进行，与“听到”的瞬间反应冲突。"}, "sentence_index": 0, "correct_answer": "毫不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对这件事毫不理由。", "explanation": "这里应该用〈没有〉。毫不不能修饰名词“理由”，应说“对这件事没有理由”。"}, {"text": "她毫不勇气。", "explanation": "这里应该用〈缺乏〉。毫不不能修饰名词“勇气”，应说“她缺乏勇气”。"}, {"text": "这件事毫不道理。", "explanation": "这里应该用〈毫无〉。毫不不能修饰名词“道理”，应说“这件事毫无道理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毫不", "is_correct": true, "explanation": "正确：“毫不松懈”即一点也不松懈，与“继续练习”的语境相合。"}, {"text": "极力", "is_correct": false, "explanation": "搭配：“极力”多修饰努力类动作，不与“松懈”这种状态搭配。"}, {"text": "连忙", "is_correct": false, "explanation": "语义：“连忙”表示急速行动，与“松懈”的状态冲突。"}, {"text": "猛然", "is_correct": false, "explanation": "语义：“猛然”表示突发动作，与“松懈”这一持续状态不合。"}], "explanations": {"毫不": "正确：“毫不松懈”即一点也不松懈，与“继续练习”的语境相合。", "极力": "搭配：“极力”多修饰努力类动作，不与“松懈”这种状态搭配。", "连忙": "语义：“连忙”表示急速行动，与“松懈”的状态冲突。", "猛然": "语义：“猛然”表示突发动作，与“松懈”这一持续状态不合。"}, "sentence_index": 6, "correct_answer": "毫不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对这件事毫不把握。", "explanation": "这里应该用〈毫无〉。毫不不能修饰名词“把握”，应说“对这件事毫无把握”。"}, {"text": "这个孩子毫不胆量。", "explanation": "这里应该用〈毫无〉。毫不不能修饰名词“胆量”，应说“这个孩子毫无胆量”。"}, {"text": "这个问题毫不难度。", "explanation": "这里应该用〈毫无〉。毫不不能修饰名词“难度”，应说“这个问题毫无难度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他毫不不慌张地走进了教室。", "corrected_sentence": "他毫不慌张地走进了教室。", "error_description": "错误：“毫不”已表示完全否定，句中又多加了一个“不”，形成多余的双重否定，应说“毫不慌张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家毫不犹豫的同意了。", "corrected_sentence": "大家毫不犹豫地同意了。", "error_description": "错误：“毫不犹豫”修饰动词“同意”时，应用“地”，这里误用了“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20908, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "感性", "is_correct": true, "explanation": "感性：指凭感情、直觉行事，与“理性”相对。"}, {"text": "花园", "is_correct": false, "explanation": "花园是地方名词，与理性没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流是自然事物，与理性没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户是建筑部件，与理性没有反义关系。"}], "correct_answer": "感性", "explanations": {"感性": "感性：指凭感情、直觉行事，与“理性”相对。", "花园": "花园是地方名词，与理性没有反义关系。", "河流": "河流是自然事物，与理性没有反义关系。", "窗户": "窗户是建筑部件，与理性没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c77f923-ef68-4ed7-867a-938d8a19ded9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20908, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "感性", "is_correct": true, "explanation": "感性：指凭感情、直觉行事，与“理性”相对。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子是家具，与理性没有反义关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "雨伞是日用品，与理性没有反义关系。"}, {"text": "草地", "is_correct": false, "explanation": "草地是地面景物，与理性没有反义关系。"}], "correct_answer": "感性", "explanations": {"感性": "感性：指凭感情、直觉行事，与“理性”相对。", "桌子": "桌子是家具，与理性没有反义关系。", "雨伞": "雨伞是日用品，与理性没有反义关系。", "草地": "草地是地面景物，与理性没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c77f923-ef68-4ed7-867a-938d8a19ded9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20908, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "理性就是遇到事情时，先想一想，不随便发脾气。", "primary_collocate": null, "pronunciation": "lǐ xìng", "ipa": "li˨˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "遇到问题时，我们要用理性想一想。", "target_word": "理性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他生气的时候，常常失去理性。", "target_word": "理性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买东西时，要有理性，不要乱花钱。", "target_word": "理性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吵架的时候，理性比愤怒更有用。", "target_word": "理性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她做决定很有理性，从不冲动。", "target_word": "理性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遇到大事，请你保持理性。", "target_word": "理性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子还小，理性不够，常常发脾气。", "target_word": "理性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，理性可以帮我们做出好决定。", "target_word": "理性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话很有理性，大家都很放心。", "target_word": "理性", "complexity_tier": "T3", "furigana": "lǐ xìng", "sentence_source": "generated"}, {"text": "先让心情平静，再用理性想办法。", "target_word": "理性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "理性思考", "label": "复合"}], "register": "中性", "sense_fingerprint": "理性|abstract|遇事先想一想，不随便发脾气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e58ebd77-3151-49ee-b9a9-0c05033cddf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20908, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理性", "is_correct": true, "explanation": "理性：指遇事冷静思考，与句中“先想一想”相符，可以放进空格。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性情或发怒的表现，不是思考的方式，“用脾气想一想”说不通。"}, {"text": "冲动", "is_correct": false, "explanation": "语义：冲动指不经考虑就行动的状态，与“想一想”正好相反。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“用”后面接的应是能用来思考的工具，眼泪不能用来想问题，“用眼泪想一想”不成立。"}], "explanations": {"理性": "理性：指遇事冷静思考，与句中“先想一想”相符，可以放进空格。", "脾气": "语义：脾气是性情或发怒的表现，不是思考的方式，“用脾气想一想”说不通。", "冲动": "语义：冲动指不经考虑就行动的状态，与“想一想”正好相反。", "眼泪": "搭配：“用”后面接的应是能用来思考的工具，眼泪不能用来想问题，“用眼泪想一想”不成立。"}, "sentence_index": 0, "correct_answer": "理性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她对朋友的理性很深，大家都很感动。", "explanation": "这里应该用〈感情〉。感情的深浅说“深”，理性指思考判断的能力，不能说对朋友的理性很深。"}, {"text": "他说了很多理性，终于说服了我。", "explanation": "这里应该用〈理由〉。说服别人要靠理由，理性是思考的能力，不能像一条条道理那样“说了很多理性”。"}, {"text": "他发了一通理性，骂了所有人。", "explanation": "这里应该用〈脾气〉。发怒可以说“发一通脾气”，理性是思考判断的能力，不能像脾气那样“发”出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c77f923-ef68-4ed7-867a-938d8a19ded9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理性", "is_correct": true, "explanation": "理性：指能冷静判断、不被情绪左右，与“孩子还小，理性不够”相符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是劳动的报酬，孩子还小通常没有工资，“工资不够”说不通。"}, {"text": "驾照", "is_correct": false, "explanation": "搭配：“不够”说的是能力或程度，驾照是证件，不能说“驾照不够”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的外观，不能用来说明孩子的判断能力。"}], "explanations": {"理性": "理性：指能冷静判断、不被情绪左右，与“孩子还小，理性不够”相符。", "工资": "语义：工资是劳动的报酬，孩子还小通常没有工资，“工资不够”说不通。", "驾照": "搭配：“不够”说的是能力或程度，驾照是证件，不能说“驾照不够”。", "颜色": "语义：颜色是事物的外观，不能用来说明孩子的判断能力。"}, "sentence_index": 6, "correct_answer": "理性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一块理性，做事很稳。", "explanation": "这里量词不对。“块”用于成块的东西，理性是抽象的思考能力，应该说〈种〉理性。"}, {"text": "她有一颗理性，遇事很冷静。", "explanation": "这里量词不对。“颗”用于颗粒状的东西，理性是抽象的思考能力，应该说〈种〉理性。"}, {"text": "他有一条理性，说话很有分寸。", "explanation": "这里量词不对。“条”用于细长的东西，理性是抽象的思考能力，应该说〈种〉理性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c77f923-ef68-4ed7-867a-938d8a19ded9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用理性地方法解决了这个问题。", "corrected_sentence": "他用理性的方法解决了这个问题。", "error_description": "错误：“地”误用。“理性”后面修饰名词的成分要用“的”，“地”只用于修饰动词。应说“理性的方法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c77f923-ef68-4ed7-867a-938d8a19ded9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面对争议，他始终保持一把理性。", "corrected_sentence": "面对争议，他始终保持理性。", "error_description": "量词错误：“把”用于有把手的器物，理性是抽象名词，不能加“一把”，应直接说“保持理性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c77f923-ef68-4ed7-867a-938d8a19ded9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
