INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20914, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "记录历史和知识的重要文字材料。", "primary_collocate": null, "pronunciation": "wén xiàn", "ipa": "wən˧˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这篇文献介绍了古代的农业技术。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆里有很多珍贵的文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们找一篇关于环保的文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份文献是八百年前留下来的。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究者认真地阅读每一篇文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在文献里找到了那位诗人的生平。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些文献记录了村子几百年的变化。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要写好报告，你得先读完相关文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆把这批文献保存得很好。", "target_word": "文献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类文献现在多数可以在网上免费下载。", "target_word": "文献", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一篇文献", "label": "量词"}, {"form": "参考文献", "label": "复合"}, {"form": "文献资料", "label": "复合"}, {"form": "文獻", "label": "繁体"}], "register": "书面", "sense_fingerprint": "记录历史和知识的重要文字材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c928e1f6-5741-4790-be78-40c893415c14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20914, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文献", "is_correct": true, "explanation": "正确：“介绍了古代的农业技术”的主语是文献，指记录知识的文字材料，语义相合。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是时间节点，不能介绍农业技术。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：量词“篇”不能修饰“冰箱”，且冰箱无法介绍技术。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手是表演者，不能用来介绍古代的农业技术。"}], "explanations": {"文献": "正确：“介绍了古代的农业技术”的主语是文献，指记录知识的文字材料，语义相合。", "节日": "语义：节日是时间节点，不能介绍农业技术。", "冰箱": "搭配：量词“篇”不能修饰“冰箱”，且冰箱无法介绍技术。", "歌手": "语义：歌手是表演者，不能用来介绍古代的农业技术。"}, "sentence_index": 0, "correct_answer": "文献"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份文献的按键坏了，要换新电池。", "explanation": "这里应该用〈遥控器〉。文献是文字材料，没有按键和电池；按键坏了要换电池的是遥控器一类的电器。"}, {"text": "这份文献在锅里煮了十分钟，很好吃。", "explanation": "这里应该用〈面条〉。文献是文字材料，不能煮来吃；煮熟了好吃的是面条一类的食物。"}, {"text": "这些文献在本次比赛中拿了冠军。", "explanation": "这里应该用〈选手〉。文献是文字资料，不能参赛拿冠军；参赛获胜的是选手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文献", "is_correct": true, "explanation": "正确：“记录了村子几百年的变化”的主语是文献，指记录历史的文字材料，语义相合。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不能记录村子的历史变化。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟只用来报时，无法记录村子几百年的变化。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：“记录”的对象是变化、事件等，不与“手套”搭配。"}], "explanations": {"文献": "正确：“记录了村子几百年的变化”的主语是文献，指记录历史的文字材料，语义相合。", "饺子": "语义：饺子是食物，不能记录村子的历史变化。", "闹钟": "语义：闹钟只用来报时，无法记录村子几百年的变化。", "手套": "搭配：“记录”的对象是变化、事件等，不与“手套”搭配。"}, "sentence_index": 6, "correct_answer": "文献"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份文献是用青铜做的，很重。", "explanation": "这里应该用〈文物〉。青铜器是实物，文献是文字资料，不能用青铜制成。"}, {"text": "妈妈给宝宝买了这份文献，宝宝很喜欢玩。", "explanation": "这里应该用〈玩具〉。文献是学术或历史资料，不是玩具；给宝宝玩的是玩具。"}, {"text": "这篇文献的幽默让人发笑。", "explanation": "这里应该用〈文章〉。形容幽默、令人发笑的是文章；文献重在资料价值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份文献我读了过。", "corrected_sentence": "这份文献我读过了。", "error_description": "体标错误：“过”和“了”的顺序颠倒，“读过了”表示已经读过，不说“读了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经找了到这些文献。", "corrected_sentence": "我已经找到了这些文献。", "error_description": "补语位置错误：“找到”是结果补语，“了”应放在“到”之后，说“找到了”，不说“找了到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
