INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20916, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "意思是“都”，表示全部。", "primary_collocate": null, "pronunciation": "jiē", "ipa": "tɕiɛ⁵⁵", "syllable_count": 1, "sentences": [{"text": "人人皆知，他是个好老师。", "target_word": "皆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里的孩子皆爱读书。", "target_word": "皆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "到会的客人皆已坐下。", "target_word": "皆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "世界各地皆有这种茶。", "target_word": "皆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们两个皆是我的同学。", "target_word": "皆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这几个房间皆已打扫干净。", "target_word": "皆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是来的人，皆有礼物。", "target_word": "皆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "家人皆喜欢这部电影。", "target_word": "皆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的花皆已开放。", "target_word": "皆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师和学生皆认真听着。", "target_word": "皆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词（书面）：都，全部，总括所指的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083b86a6-9f7b-4d1f-ab6f-174ff48943e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20916, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "皆", "is_correct": true, "explanation": "正确：皆（jiē）是副词，表示“都”，指全部。"}, {"text": "姐", "is_correct": false, "explanation": "jiē（第一声）与 jiě（第三声）声调不同，“姐”意思是姐姐。"}, {"text": "节", "is_correct": false, "explanation": "jiē（第一声）与 jié（第二声）声调不同，“节”意思是节日。"}, {"text": "界", "is_correct": false, "explanation": "jiē（第一声）与 jiè（第四声）声调不同，“界”意思是界限，如“世界”。"}, {"text": "些", "is_correct": false, "explanation": "jiē 与 xiē 声母不同（j 与 x），“些”意思是一些。"}], "explanations": {"皆": "正确：皆（jiē）是副词，表示“都”，指全部。", "姐": "jiē（第一声）与 jiě（第三声）声调不同，“姐”意思是姐姐。", "节": "jiē（第一声）与 jié（第二声）声调不同，“节”意思是节日。", "界": "jiē（第一声）与 jiè（第四声）声调不同，“界”意思是界限，如“世界”。", "些": "jiē 与 xiē 声母不同（j 与 x），“些”意思是一些。"}, "sentence_index": null, "correct_answer": "皆"}, "level_3": {"options": [{"text": "皆", "is_correct": true, "explanation": "正确：“皆”表示全部，与“人人”相呼应，符合语境。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”是否定，与“人人知”的肯定陈述矛盾。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示故意或出乎意料，句子没有这种语境。"}, {"text": "却", "is_correct": false, "explanation": "搭配：“却”表示转折，需要与前文的转折相呼应，这里没有转折。"}], "explanations": {"皆": "正确：“皆”表示全部，与“人人”相呼应，符合语境。", "从不": "语义：“从不”是否定，与“人人知”的肯定陈述矛盾。", "偏偏": "语义：“偏偏”表示故意或出乎意料，句子没有这种语境。", "却": "搭配：“却”表示转折，需要与前文的转折相呼应，这里没有转折。"}, "sentence_index": 0, "correct_answer": "皆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他皆喜欢这部电影。", "explanation": "“皆”总括多个对象，主语“他”只是一个人，不能用“皆”。应删去〈皆〉，说“他喜欢这部电影”。"}, {"text": "这件衣服皆很好看。", "explanation": "“皆”总括多个对象，“这件衣服”只有一件，不能用“皆”。应删去〈皆〉，说“这件衣服很好看”。"}, {"text": "一个学生皆很努力。", "explanation": "“皆”总括多个对象，“一个学生”是单数，不能用“皆”。应改为〈所有学生皆很努力〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20916, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "皆", "is_correct": true, "explanation": "正确：皆（jiē）是副词，表示“都”，指全部。"}, {"text": "切", "is_correct": false, "explanation": "jiē 与 qiē 声母不同（j 与 q），“切”意思是用刀分开。"}, {"text": "家", "is_correct": false, "explanation": "jiē 与 jiā 韵母不同（e 与 a），“家”意思是家庭、住所。"}, {"text": "夹", "is_correct": false, "explanation": "jiē 与 jiā 韵母不同（e 与 a），“夹”意思是用东西把物体按住或固定。"}], "explanations": {"皆": "正确：皆（jiē）是副词，表示“都”，指全部。", "切": "jiē 与 qiē 声母不同（j 与 q），“切”意思是用刀分开。", "家": "jiē 与 jiā 韵母不同（e 与 a），“家”意思是家庭、住所。", "夹": "jiē 与 jiā 韵母不同（e 与 a），“夹”意思是用东西把物体按住或固定。"}, "sentence_index": null, "correct_answer": "皆"}, "level_3": {"options": [{"text": "皆", "is_correct": true, "explanation": "正确：“皆”表示全部，与“凡是……”的全称语义相符，符合语境。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然，与“凡是……”的全称条件不符。"}, {"text": "不再", "is_correct": false, "explanation": "语义：“不再”是否定，与“有礼物”的肯定语义矛盾。"}, {"text": "偏", "is_correct": false, "explanation": "搭配：“偏”表示故意或与常理相反，不能与“凡是……”的全称句式搭配。"}], "explanations": {"皆": "正确：“皆”表示全部，与“凡是……”的全称语义相符，符合语境。", "忽然": "语义：“忽然”表示突然，与“凡是……”的全称条件不符。", "不再": "语义：“不再”是否定，与“有礼物”的肯定语义矛盾。", "偏": "搭配：“偏”表示故意或与常理相反，不能与“凡是……”的全称句式搭配。"}, "sentence_index": 6, "correct_answer": "皆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "有的同学皆同意了这个计划。", "explanation": "“皆”表示全部，不能与表示部分的“有的”同用。这里应该删去〈皆〉，说“有的同学同意了这个计划”。"}, {"text": "这事我皆知道，别担心啦。", "explanation": "“皆”表示全部，要求主语是多个对象，“我”是单数，不能说“我皆知道”。这里应该用〈都〉：“这事我都知道”。"}, {"text": "他一个人皆完成了作业。", "explanation": "“皆”表示全部，主语须是多个对象，“他一个人”是单数。应删去〈皆〉，说“他一个人完成了作业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些树皆的已长高。", "corrected_sentence": "这些树皆已长高。", "error_description": "错误：“皆的”；正确：“皆”后面不能加“的”。“皆”是副词，直接修饰“已长高”，中间加“的”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些书都皆是新的。", "corrected_sentence": "这些书皆是新的。", "error_description": "“都”与“皆”同义，不能叠用。错误形式“都皆是”重复了全称副词，正确形式只用“皆”：“这些书皆是新的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
