INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20920, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "像树根扎进土里一样牢牢扎住；比喻事物根基牢固，来源于某种基础。", "primary_collocate": null, "pronunciation": "zhí gēn yú", "ipa": "ʈʂɻ̩˧˥ kɤn˥ y˧˥", "syllable_count": 3, "sentences": [{"text": "这种艺术植根于民间生活。", "target_word": "植根于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好文学植根于真实的生活。", "target_word": "植根于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的想法植根于中国传统文化。", "target_word": "植根于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这棵老树深深植根于这片山坡。", "target_word": "植根于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些故事植根于当地的历史。", "target_word": "植根于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人的自信，应该植根于努力。", "target_word": "植根于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个节日植根于农民的生活。", "target_word": "植根于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的作品植根于家乡的土地。", "target_word": "植根于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "真正的友谊植根于互相信任。", "target_word": "植根于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的文化植根于几千年的历史。", "target_word": "植根于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "植根", "label": "缩略"}], "register": "书面", "sense_fingerprint": "根基牢牢扎在某处，来源于某个基础", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5fcf5b-556e-47e4-b003-813f3f632225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "植根于", "is_correct": true, "explanation": "正确。“这种艺术植根于民间生活”表示根基扎在民间生活中，符合句意。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：艺术不能被翻译成民间生活，句子不通。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：“搬运”的对象是物品，不能搬运“民间生活”。"}, {"text": "投资", "is_correct": false, "explanation": "搭配：“投资”后面接资金或项目，不说“投资民间生活”。"}], "explanations": {"植根于": "正确。“这种艺术植根于民间生活”表示根基扎在民间生活中，符合句意。", "翻译": "语义：艺术不能被翻译成民间生活，句子不通。", "搬运": "语义：“搬运”的对象是物品，不能搬运“民间生活”。", "投资": "搭配：“投资”后面接资金或项目，不说“投资民间生活”。"}, "sentence_index": 0, "correct_answer": "植根于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个计划植根于三个月前。", "explanation": "这里不这么用。“植根于”后面要接地方或根基，不能接时间。"}, {"text": "他每周都植根于不同的城市，从不停留。", "explanation": "这里不这么用。“植根于”表示长期稳定地扎在一个地方，与“每周换城市”矛盾。"}, {"text": "这辆车植根于马路上，一直停在那里。", "explanation": "这里不这么用。“植根于”多用于树木、思想等扎根的事物，不用于车辆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "植根于", "is_correct": true, "explanation": "正确。“这个节日植根于农民的生活”表示节日的根基在农民的生活中，符合句意。"}, {"text": "测量", "is_correct": false, "explanation": "语义：“测量”的对象是长度、温度等，不能测量“农民的生活”。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：节日不能“拒绝”农民的生活，句子不通。"}, {"text": "挂断", "is_correct": false, "explanation": "搭配：“挂断”接电话、通话，不说“挂断农民的生活”。"}], "explanations": {"植根于": "正确。“这个节日植根于农民的生活”表示节日的根基在农民的生活中，符合句意。", "测量": "语义：“测量”的对象是长度、温度等，不能测量“农民的生活”。", "拒绝": "语义：节日不能“拒绝”农民的生活，句子不通。", "挂断": "搭配：“挂断”接电话、通话，不说“挂断农民的生活”。"}, "sentence_index": 6, "correct_answer": "植根于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个决定植根于一场小雨。", "explanation": "这里不这么用。“植根于”后面要接土地、传统等根基，“一场小雨”不能作根基。"}, {"text": "这只猫植根于窗台上，一动不动。", "explanation": "这里不这么用。“植根于”多用于树木或思想、传统等扎根的事物，不用于动物。"}, {"text": "这盆花植根于花盆，却总是搬来搬去。", "explanation": "这里不这么用。“植根于”表示长期稳定地扎根，与“总是搬来搬去”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种习惯很植根于童年的经历。", "corrected_sentence": "这种习惯深深植根于童年的经历。", "error_description": "状语错误：“植根于”前面不能用“很”修饰，应改用“深深”等副词，说“深深植根于”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种传统被植根于农村的生活。", "corrected_sentence": "这种传统植根于农村的生活。", "error_description": "被字错误：“植根于”是主动意义，不用“被”；应去掉“被”，说“这种传统植根于农村的生活”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
