INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20922, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西搭起来，比如盖房子。", "primary_collocate": null, "pronunciation": "gòu zhù", "ipa": "kou˥˩ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "工人们正在构筑一座新桥。", "target_word": "构筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用石头构筑了一道墙。", "target_word": "构筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在河边构筑了一座小房子。", "target_word": "构筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们在山上构筑防线。", "target_word": "构筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用沙子构筑了一座城堡。", "target_word": "构筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边构筑了一座灯塔。", "target_word": "构筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地政府计划在城东构筑一道新的防洪堤。", "target_word": "构筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了一年时间构筑这间木屋。", "target_word": "构筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人先构筑地基，再盖楼房。", "target_word": "构筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大坝是五年前构筑的。", "target_word": "构筑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "構築", "label": "繁体"}, {"form": "构筑了", "label": "体标"}, {"form": "构筑着", "label": "体标"}], "register": "书面", "sense_fingerprint": "把房屋、墙、工事等实物搭建起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c08b601-4318-47af-9aac-f60ca0c0c5ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20922, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "构筑", "is_correct": true, "explanation": "构筑指搭建桥梁、房屋等实体，与“建一座新桥”相符。"}, {"text": "熨", "is_correct": false, "explanation": "语义：熨是整理衣物的动作，不能用于建造桥梁，“熨一座新桥”句意不成立。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：烹饪的对象是食物，不能与“一座新桥”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是发声的动作，与建造桥梁无关。"}], "explanations": {"构筑": "构筑指搭建桥梁、房屋等实体，与“建一座新桥”相符。", "熨": "语义：熨是整理衣物的动作，不能用于建造桥梁，“熨一座新桥”句意不成立。", "烹饪": "搭配：烹饪的对象是食物，不能与“一座新桥”搭配。", "唱": "语义：唱是发声的动作，与建造桥梁无关。"}, "sentence_index": 0, "correct_answer": "构筑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用刻刀构筑了一块木头。", "explanation": "这里应该用〈雕刻〉。“构筑”指搭建房屋、工事等建筑，用刻刀加工木块要用〈雕刻〉。"}, {"text": "她构筑了一首诗。", "explanation": "这里应该用〈写〉。“构筑”用于房屋、工事等实体，不用于创作诗歌。"}, {"text": "工匠构筑了一把好剑。", "explanation": "这里应该用〈打造〉。“构筑”用于房屋、工事等大型建筑，不用于小件器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "构筑", "is_correct": true, "explanation": "构筑指修建防洪堤等工程，与“一道新的防洪堤”相符。"}, {"text": "播放", "is_correct": false, "explanation": "语义：播放是放映、放送，不能用于修建堤坝。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：翻译的对象是语言或文字，不能与“一道防洪堤”搭配。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：演奏是演奏乐器或乐曲，与修建堤坝无关。"}], "explanations": {"构筑": "构筑指修建防洪堤等工程，与“一道新的防洪堤”相符。", "播放": "语义：播放是放映、放送，不能用于修建堤坝。", "翻译": "搭配：翻译的对象是语言或文字，不能与“一道防洪堤”搭配。", "演奏": "语义：演奏是演奏乐器或乐曲，与修建堤坝无关。"}, "sentence_index": 6, "correct_answer": "构筑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正在构筑那张旧照片。", "explanation": "这里应该用〈冲洗〉。“构筑”用于房屋、工事等实体，照片要靠冲洗。"}, {"text": "她构筑了一支乐曲。", "explanation": "这里应该用〈创作〉。“构筑”用于房屋、工事等实体，不用于音乐作品。"}, {"text": "陶工在窑里构筑瓷器。", "explanation": "这里应该用〈烧制〉。“构筑”用于搭建建筑、工事，瓷器要靠烧制而成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们正在构筑了一条新路。", "corrected_sentence": "工人们正在构筑一条新路。", "error_description": "时态错误：“正在”表示动作进行，不能与“了”同用。正确说法是“正在构筑一条新路”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把地基构筑了好。", "corrected_sentence": "工人们把地基构筑好了。", "error_description": "语序错误：结果补语“好”应紧跟动词，“了”应放在句末。正确说法是“构筑好了”，不能说“构筑了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
