INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20928, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "意思是“应该注意”，就是觉得某件事很重要，要多看看。", "primary_collocate": null, "pronunciation": "zhí dé zhù yì", "ipa": "ʈʂɻ̩˧˥ tɤ˧˥ ʈʂu˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "这个问题很重要，值得注意。", "target_word": "值得注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷了，老人的身体值得注意。", "target_word": "值得注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话的方式值得注意。", "target_word": "值得注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路时，红绿灯的变化值得注意。", "target_word": "值得注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的价格变化很大，值得注意。", "target_word": "值得注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个词的用法值得注意。", "target_word": "值得注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子晚上睡得太少，这一点值得注意。", "target_word": "值得注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里有一个数字值得注意。", "target_word": "值得注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天路很滑，这一点值得注意。", "target_word": "值得注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有一件事特别值得注意：药要饭后吃。", "target_word": "值得注意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "值得注意的", "label": "定语形式"}, {"form": "不值得注意", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "某事重要，应该多加留意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af672a29-e1eb-4780-8f57-35ac2a0384e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20928, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "值得尊敬", "is_correct": false, "explanation": "搭配：“尊敬”的对象通常是人，问题不能被尊敬，说“问题值得尊敬”不通。"}, {"text": "值得注意", "is_correct": true, "explanation": "“这个问题很重要，值得注意”说明问题应受到关注，符合语境。"}, {"text": "值得吃", "is_correct": false, "explanation": "语义：问题不能吃，“值得吃”与“这个问题很重要”不搭。"}, {"text": "值得品尝", "is_correct": false, "explanation": "语义：品尝是对食物或饮品而言的，问题不能被品尝。"}], "explanations": {"值得尊敬": "搭配：“尊敬”的对象通常是人，问题不能被尊敬，说“问题值得尊敬”不通。", "值得注意": "“这个问题很重要，值得注意”说明问题应受到关注，符合语境。", "值得吃": "语义：问题不能吃，“值得吃”与“这个问题很重要”不搭。", "值得品尝": "语义：品尝是对食物或饮品而言的，问题不能被品尝。"}, "sentence_index": 0, "correct_answer": "值得注意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今晚我值得注意，你们先回家吧。", "explanation": "这里应该用〈值班〉。值得注意表示事情值得留意，说自己负责今晚的工作要用〈值班〉。"}, {"text": "我把电脑值得注意了一下，它就好了。", "explanation": "这里应该用〈修〉。值得注意不能带“把”字宾语，修理电脑要用〈修〉。"}, {"text": "我把这个菜值得注意了，吃了两碗。", "explanation": "这里应该用〈尝〉。值得注意不能带“把”字宾语，品尝菜要用〈尝〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "值得庆祝", "is_correct": false, "explanation": "语义：孩子睡得太少不是值得庆祝的事，与语境相反。"}, {"text": "值得瞻仰", "is_correct": false, "explanation": "语域：瞻仰多用于庄重的场合，与这句口语化的提醒不协调。"}, {"text": "值得注意", "is_correct": true, "explanation": "“孩子晚上睡得太少，这一点值得注意”提醒大家留意，符合语境。"}, {"text": "值得赞美", "is_correct": false, "explanation": "语义：睡得太少是需要纠正的问题，不应当赞美，与语境不符。"}], "explanations": {"值得庆祝": "语义：孩子睡得太少不是值得庆祝的事，与语境相反。", "值得瞻仰": "语域：瞻仰多用于庄重的场合，与这句口语化的提醒不协调。", "值得注意": "“孩子晚上睡得太少，这一点值得注意”提醒大家留意，符合语境。", "值得赞美": "语义：睡得太少是需要纠正的问题，不应当赞美，与语境不符。"}, "sentence_index": 6, "correct_answer": "值得注意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察在路口值得注意。", "explanation": "这里应该用〈值勤〉。值得注意指事情重要、应多留意，值勤是指执行勤务，不说“值得注意”。"}, {"text": "保安夜里在仓库值得注意。", "explanation": "这里应该用〈值守〉。值得注意是评价事情值不值得留意，守卫岗位要用〈值守〉。"}, {"text": "护士在病房值得注意。", "explanation": "这里应该用〈当班〉。值得注意说的是事情重要，负责某个时段的工作要用〈当班〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事很值得注意着。", "corrected_sentence": "这件事很值得注意。", "error_description": "多了“着”：“值得注意”后面不能加“着”，应说「这件事很值得注意」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条新规定很值得注意过。", "corrected_sentence": "这条新规定很值得注意。", "error_description": "多了“过”：“值得注意”是评价事情重要，后面不能加“过”，应说「这条新规定很值得注意」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
