INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20930, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这个想法是说，所有事情都已经被安排好了，不能改变。", "primary_collocate": null, "pronunciation": "jué dìng lùn", "ipa": "tɕye˧˥ tiŋ˥˩ lwən˥˩", "syllable_count": 3, "sentences": [{"text": "决定论是说，所有事情都已经安排好了。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他信决定论，觉得人不能改变命运。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不同意决定论，因为我相信努力有用。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按决定论的想法，今天的事早就定好了。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说决定论让人什么都不想做。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在课上聊了决定论。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "相信决定论的人觉得，一切都不能改变。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥说决定论太让人难过了。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "决定论的意思是未来早就定了。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你相信决定论吗？", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "決定論", "label": "繁体"}], "register": "中性", "sense_fingerprint": "认为所有事情早已安排好、无法改变的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6d46d0b-bdfb-4036-8276-2cadd17ec858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "决定论", "is_correct": true, "explanation": "正确：「决定论是说，所有事情都已经安排好了」是对这一想法的定义，只有「决定论」能作主语。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不能用来说明「所有事情是否安排好」，「天气是说」句意不通。"}, {"text": "足球", "is_correct": false, "explanation": "搭配：「足球」不能作「是说」的主语，不能充当这一定义的主语。"}, {"text": "字典", "is_correct": false, "explanation": "语义：「字典」是工具书，不能说明「所有事情都已安排好」这一观点。"}], "explanations": {"决定论": "正确：「决定论是说，所有事情都已经安排好了」是对这一想法的定义，只有「决定论」能作主语。", "天气": "语义：「天气」不能用来说明「所有事情是否安排好」，「天气是说」句意不通。", "足球": "搭配：「足球」不能作「是说」的主语，不能充当这一定义的主语。", "字典": "语义：「字典」是工具书，不能说明「所有事情都已安排好」这一观点。"}, "sentence_index": 0, "correct_answer": "决定论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司的决定论已经定下来了。", "explanation": "这里应该用〈决策〉。「决策」指经营管理上的决定；「决定论」是哲学学说，不能指公司的决定。"}, {"text": "老板的决定论是明天放假。", "explanation": "这里应该用〈决定〉。具体某件事怎么做是「决定」；「决定论」是一种哲学想法，不能指具体的决定。"}, {"text": "这事已经成了决定论。", "explanation": "这里应该用〈定论〉。「成了定论」是固定说法，指确定的结论；「决定论」是学说，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "决定论", "is_correct": true, "explanation": "正确：「相信……的人」要求一种观点作宾语，「决定论」正合句意。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器不是观点，不能被「相信」，「相信乐器的人」句意不通。"}, {"text": "红绿灯", "is_correct": false, "explanation": "语义：「红绿灯」是交通信号，不能被「相信」，句意不通。"}, {"text": "积木", "is_correct": false, "explanation": "语义：「积木」是玩具，不是观点，不能被「相信」，句意不通。"}], "explanations": {"决定论": "正确：「相信……的人」要求一种观点作宾语，「决定论」正合句意。", "乐器": "语义：乐器不是观点，不能被「相信」，「相信乐器的人」句意不通。", "红绿灯": "语义：「红绿灯」是交通信号，不能被「相信」，句意不通。", "积木": "语义：「积木」是玩具，不是观点，不能被「相信」，句意不通。"}, "sentence_index": 6, "correct_answer": "决定论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题我找到了决定论。", "explanation": "这里应该用〈答案〉。「找到答案」是固定说法；「决定论」是学说，不能作为解题结果。"}, {"text": "他下定了决定论。", "explanation": "这里应该用〈决心〉。「下定决心」是固定说法；「决定论」不能指决心。"}, {"text": "法院做出了决定论。", "explanation": "这里应该用〈判决〉。法院作出的裁决说「判决」；「决定论」是哲学学说，不能指裁决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作者比较了两条决定论。", "corrected_sentence": "作者比较了两种决定论。", "error_description": "「决定论」是哲学学说，量词应用「种」，不用「条」；「条」用于条状事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们讨论过决定论过。", "corrected_sentence": "我们讨论过决定论。", "error_description": "「过」只用一次：表示经历的「过」应紧跟动词，写作「讨论过决定论」；宾语「决定论」之后不能再加「过」，「讨论过决定论过」是错误形式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
