INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20932, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开始流行起来。", "primary_collocate": null, "pronunciation": "xīng qǐ", "ipa": "ɕiŋ˥ tɕʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "近几年，网上购物在小城市也兴起了。", "target_word": "兴起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种运动在年轻人中兴起。", "target_word": "兴起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十年前，短视频还没有兴起。", "target_word": "兴起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着手机的普及，新的生活方式兴起了。", "target_word": "兴起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里兴起了一股骑车上班的风气。", "target_word": "兴起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡文化在这座城市慢慢兴起。", "target_word": "兴起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一种新的音乐在年轻人中兴起了。", "target_word": "兴起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候，露营刚刚兴起，人还不多。", "target_word": "兴起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络学习兴起以后，很多人在家上课。", "target_word": "兴起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种饮料是最近才兴起的。", "target_word": "兴起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兴起了", "label": "体标（了）"}, {"form": "兴起过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "新事物、新风气开始出现并流行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6b26b9a-9d68-4360-8cd8-e1c05a934069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20932, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兴起", "is_correct": true, "explanation": "正确：“兴起”指新事物开始流行，与“近几年”网上购物在小城市出现的情况相符。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”的主语是学生，“网上购物”不能毕业，句子不通。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”要带购买的对象，句中“网上购物”不能作“购买”的施事，句子不成立。"}, {"text": "倒闭", "is_correct": false, "explanation": "搭配：“倒闭”用于公司、商店等经营机构，“网上购物”不是企业，不能说倒闭。"}], "explanations": {"兴起": "正确：“兴起”指新事物开始流行，与“近几年”网上购物在小城市出现的情况相符。", "毕业": "搭配：“毕业”的主语是学生，“网上购物”不能毕业，句子不通。", "购买": "配价：“购买”要带购买的对象，句中“网上购物”不能作“购买”的施事，句子不成立。", "倒闭": "搭配：“倒闭”用于公司、商店等经营机构，“网上购物”不是企业，不能说倒闭。"}, "sentence_index": 0, "correct_answer": "兴起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一位新的演员兴起了一部电影。", "explanation": "这里应该用〈拍摄〉。兴起指风气、潮流开始流行，拍一部电影要用拍摄。"}, {"text": "昨天城里兴起了一件大事。", "explanation": "这里应该用〈发生〉。兴起指风气、潮流开始流行，偶然的大事要用发生。"}, {"text": "这家公司去年兴起了。", "explanation": "这里应该用〈成立〉。兴起指新风气流行起来，公司的设立要用成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兴起", "is_correct": true, "explanation": "正确：“兴起”指新音乐开始在年轻人中流行，与句意相符。"}, {"text": "凋谢", "is_correct": false, "explanation": "搭配：“凋谢”用于花草，音乐不能凋谢。"}, {"text": "退役", "is_correct": false, "explanation": "搭配：“退役”用于运动员或军人，音乐不能退役。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”的主语须是有意志的人，“音乐”不能放弃，句子不通。"}], "explanations": {"兴起": "正确：“兴起”指新音乐开始在年轻人中流行，与句意相符。", "凋谢": "搭配：“凋谢”用于花草，音乐不能凋谢。", "退役": "搭配：“退役”用于运动员或军人，音乐不能退役。", "放弃": "语义：“放弃”的主语须是有意志的人，“音乐”不能放弃，句子不通。"}, "sentence_index": 6, "correct_answer": "兴起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府兴起了新的制度。", "explanation": "这里应该用〈建立〉。此处兴起表示开始流行，不指政府设立制度，制度的设立要用建立。"}, {"text": "学校兴起了一场比赛。", "explanation": "这里应该用〈举办〉。兴起指风气流行起来，比赛要由学校举办。"}, {"text": "他兴起了一家小店。", "explanation": "这里应该用〈创办〉。兴起不能带店铺作宾语，开一家店要用创办。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年，一种新的舞蹈在大学里被兴起了。", "corrected_sentence": "这几年，一种新的舞蹈在大学里兴起了。", "error_description": "错误：“被兴起”。“兴起”是不及物动词，表示开始流行，不能用“被”构成被动句，应去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "早些年，这种游戏在学校里兴起了过。", "corrected_sentence": "早些年，这种游戏在学校里兴起过。", "error_description": "错误：“兴起了过”。“了”和“过”都是动态助词，不能同时用在同一个动词后，应写作“兴起过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
