INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20934, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20934, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个东西让另一个东西变了。", "primary_collocate": null, "pronunciation": "yǐng xiǎng", "ipa": "iŋ˨˩ ɕiɑŋ˨˩", "syllable_count": 2, "sentences": [{"text": "天气对我的心情有影响。", "target_word": "影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机对孩子的影响很大。", "target_word": "影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事没有给他带来坏影响。", "target_word": "影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对我的影响很深。", "target_word": "影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝咖啡会对睡眠产生影响。", "target_word": "影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母的影响会让孩子慢慢改变。", "target_word": "影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大雨对比赛没有影响。", "target_word": "影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友对他的影响非常大。", "target_word": "影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸烟对身体有很多坏影响。", "target_word": "影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书对我有很大的影响。", "target_word": "影响", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "影响力", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或事物对他人他物产生的作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eb7735c-2a9b-4b0a-9aa5-30409c5f4706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "影响", "is_correct": true, "explanation": "「影响」指一事物使另一事物发生变化，这里指天气改变了心情，符合句意。"}, {"text": "兴趣", "is_correct": false, "explanation": "语义：「兴趣」需要有意识的人作主体，天气不能有兴趣。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：「体积」只用于有形的物体，「心情」没有体积。"}, {"text": "速度", "is_correct": false, "explanation": "语义：「速度」说快慢，不指事物对心情产生的作用。"}], "explanations": {"影响": "「影响」指一事物使另一事物发生变化，这里指天气改变了心情，符合句意。", "兴趣": "语义：「兴趣」需要有意识的人作主体，天气不能有兴趣。", "体积": "搭配：「体积」只用于有形的物体，「心情」没有体积。", "速度": "语义：「速度」说快慢，不指事物对心情产生的作用。"}, "sentence_index": 0, "correct_answer": "影响"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃了药以后，他的影响很快。", "explanation": "这里应该用〈反应〉。「反应」指人对刺激的回应，「影响」指一事物对另一事物的作用，不说「他的影响很快」。"}, {"text": "这次事故的影响是司机喝酒。", "explanation": "这里应该用〈原因〉。「原因」指导致某种结果的因素，「影响」指一事物对另一事物的作用，不能用来引出起因。"}, {"text": "山谷里传来了阵阵影响。", "explanation": "这里应该用〈回声〉。「回声」指声音遇到障碍物后反射回来，「影响」指一事物对另一事物的作用，不能指声音的反射。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "影响", "is_correct": true, "explanation": "「影响」是名词，指大雨对比赛产生的作用，符合「没有影响」的否定句。"}, {"text": "价钱", "is_correct": false, "explanation": "语义：「价钱」只指买卖的东西的价格，比赛没有价钱。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「体重」指人或动物的重量，不能用在比赛上。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：比赛没有颜色的说法，「颜色」不指事件对事物的作用。"}], "explanations": {"影响": "「影响」是名词，指大雨对比赛产生的作用，符合「没有影响」的否定句。", "价钱": "语义：「价钱」只指买卖的东西的价格，比赛没有价钱。", "体重": "搭配：「体重」指人或动物的重量，不能用在比赛上。", "颜色": "语义：比赛没有颜色的说法，「颜色」不指事件对事物的作用。"}, "sentence_index": 6, "correct_answer": "影响"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电视的影响开到了最大。", "explanation": "这里应该用〈音量〉。「音量」指声音的大小，可以调节，「影响」是抽象的作用，不能「开到最大」。"}, {"text": "这张票的影响到期了。", "explanation": "这里应该用〈效力〉。「效力」指票据、规定等有效的程度或期限，「影响」指对他物的作用，不能说「到期」。"}, {"text": "病人的影响很高。", "explanation": "这里应该用〈体温〉。「体温」可以说高低，「影响」不能用「高」来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事对他有一只影响。", "corrected_sentence": "这件事对他有一种影响。", "error_description": "量词错误：「影响」是抽象名词，不能用量词「只」（只用于动物或成对的器物），应改为「一种影响」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事对我们的计划不有影响。", "corrected_sentence": "这件事对我们的计划没有影响。", "error_description": "否定词错误：「有」的否定只能用「没有」，不能说「不有」，应为「没有影响」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
