INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20938, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种经济制度，工厂、商店等生产资料归私人所有，企业以赚取利润为目的。", "primary_collocate": null, "pronunciation": "zī běn zhǔ yì", "ipa": "tsɹ̩˥ pən˨˩ ʈʂu˨˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "有人开工厂赚钱，这是资本主义。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资本主义就是自己开店，自己赚钱。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸说，资本主义让人努力做生意。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在资本主义制度下，工厂和商店是私人的。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了什么是资本主义。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的人喜欢资本主义，因为能自己赚钱。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了解资本主义的兴起过程。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资本主义国家有很多大公司。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得资本主义好不好？", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的资本主义发展得很快。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "資本主義", "label": "繁体"}], "register": "中性", "sense_fingerprint": "私人开工厂、商店赚钱的做法和制度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6d46d0b-bdfb-4036-8276-2cadd17ec858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20938, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "资本主义", "is_correct": true, "explanation": "正确：句中说的是私人开工厂赚钱的做法，即资本主义。"}, {"text": "社会主义", "is_correct": false, "explanation": "语义：句中说的是私人开工厂赚钱，与社会主义的公有制不符。"}, {"text": "民主", "is_correct": false, "explanation": "语义：「民主」指政治制度，与开工厂赚钱的经济做法无关。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：「这是工厂」不能解释「开工厂赚钱」这种做法。"}], "explanations": {"资本主义": "正确：句中说的是私人开工厂赚钱的做法，即资本主义。", "社会主义": "语义：句中说的是私人开工厂赚钱，与社会主义的公有制不符。", "民主": "语义：「民主」指政治制度，与开工厂赚钱的经济做法无关。", "工厂": "搭配：「这是工厂」不能解释「开工厂赚钱」这种做法。"}, "sentence_index": 0, "correct_answer": "资本主义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的资本主义是每天互相帮助。", "explanation": "这里应用〈信条〉。资本主义指一种经济制度，不指班级的信条或主张。"}, {"text": "开公司需要很多资本主义。", "explanation": "这里应用〈资本〉。开公司需要的是钱和财物，即「资本」；资本主义是一种经济制度。"}, {"text": "这位资本主义拥有很多家工厂。", "explanation": "这里应用〈资本家〉。资本主义指经济制度，不指人；指拥有工厂的人应说〈资本家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资本主义", "is_correct": true, "explanation": "正确：“了解……的兴起过程”问的是一种经济制度的历史发展，资本主义符合。"}, {"text": "冰川", "is_correct": false, "explanation": "语义：“冰川”是自然景观，没有“兴起过程”，句意不通。"}, {"text": "晚饭", "is_correct": false, "explanation": "语义：“晚饭”是日常饮食，不能说“兴起过程”，句意不通。"}, {"text": "春雨", "is_correct": false, "explanation": "语义：“春雨”是天气现象，不能说“兴起过程”，句意不通。"}], "explanations": {"资本主义": "正确：“了解……的兴起过程”问的是一种经济制度的历史发展，资本主义符合。", "冰川": "语义：“冰川”是自然景观，没有“兴起过程”，句意不通。", "晚饭": "语义：“晚饭”是日常饮食，不能说“兴起过程”，句意不通。", "春雨": "语义：“春雨”是天气现象，不能说“兴起过程”，句意不通。"}, "sentence_index": 6, "correct_answer": "资本主义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸是个资本主义，开了三家工厂。", "explanation": "这里应用〈资本家〉。资本主义是经济制度，不指人；开工厂的老板是「资本家」。"}, {"text": "这家公司需要更多资本主义才能扩大。", "explanation": "这里应用〈资本〉。公司扩大需要的是钱，即「资本」，不是一种制度。"}, {"text": "资本主义认为工厂应该归大家所有。", "explanation": "这里应用〈社会主义〉。工厂归大家所有是公有制的想法；资本主义的工厂是私人的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学习了关于资本主义。", "corrected_sentence": "我们学习了关于资本主义的知识。", "error_description": "「关于资本主义」只是介词短语，不能单独作「学习」的宾语，后面要加「的知识」等中心语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给资本主义很感兴趣。", "corrected_sentence": "他对资本主义很感兴趣。", "error_description": "表示对某事物有兴趣要用「对……感兴趣」，不能用「给」，应说「对资本主义很感兴趣」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
