INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20940, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家要遵守的规矩。", "primary_collocate": null, "pronunciation": "zhì dù", "ipa": "ʈʂɻ̩˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "公司有一个新制度。", "target_word": "制度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的制度要大家遵守。", "target_word": "制度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个制度对所有人都一样。", "target_word": "制度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要遵守公司的制度。", "target_word": "制度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想改变学校的考试制度。", "target_word": "制度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家有自己的法律制度。", "target_word": "制度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套制度已经用了十年。", "target_word": "制度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的人要先学习公司制度。", "target_word": "制度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有制度，大家就会很乱。", "target_word": "制度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的管理制度很严格。", "target_word": "制度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项制度", "label": "量词"}, {"form": "一套制度", "label": "量词"}, {"form": "制度化", "label": "复合"}], "register": "中性", "sense_fingerprint": "大家要遵守的规矩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e21988-a24b-41f5-92fd-a20a131657a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20940, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是一种疾病，“公司有一个新”说的是可以新设立的东西，句子读不通。"}, {"text": "制度", "is_correct": true, "explanation": "“制度”指大家要遵守的规矩，公司可以有一个新的制度。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，公司不能设立一个新天气，句意不通。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“雨”的量词用“场”，不能说“一个新雨”，与句子搭配不上。"}], "explanations": {"感冒": "语义：“感冒”是一种疾病，“公司有一个新”说的是可以新设立的东西，句子读不通。", "制度": "“制度”指大家要遵守的规矩，公司可以有一个新的制度。", "天气": "语义：“天气”是自然现象，公司不能设立一个新天气，句意不通。", "雨": "搭配：“雨”的量词用“场”，不能说“一个新雨”，与句子搭配不上。"}, "sentence_index": 0, "correct_answer": "制度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要制定一把新制度。", "explanation": "这里应该用〈项〉或〈套〉。“把”用于有柄的东西，“制度”要用“项”或“套”。"}, {"text": "他给我留下了深刻的制度。", "explanation": "这里应该用〈印象〉。“制度”指社会或团体的规定，不用来说给人留下的印象，要用“印象”。"}, {"text": "我和他有很深的制度。", "explanation": "这里应该用〈感情〉。“制度”指规定，不用来形容人与人之间的情谊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公司", "is_correct": false, "explanation": "搭配：“公司”的量词用“家”，不说“这套公司”，句子搭配不当。"}, {"text": "制度", "is_correct": true, "explanation": "“制度”指大家要遵守的规矩，可以“用了十年”，量词“套”也搭配。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不能被“用了十年”，句子读不通。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：“呼吸”是身体的活动，不能说“这套呼吸已经用了十年”，句意不通。"}], "explanations": {"公司": "搭配：“公司”的量词用“家”，不说“这套公司”，句子搭配不当。", "制度": "“制度”指大家要遵守的规矩，可以“用了十年”，量词“套”也搭配。", "天空": "语义：“天空”不能被“用了十年”，句子读不通。", "呼吸": "语义：“呼吸”是身体的活动，不能说“这套呼吸已经用了十年”，句意不通。"}, "sentence_index": 6, "correct_answer": "制度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的制度很可爱。", "explanation": "这里应该用〈样子〉。“制度”指规定，不能用来形容人的外貌，要用“样子”。"}, {"text": "他的制度很坚定，从不动摇。", "explanation": "这里应该用〈信念〉。“制度”指规定，不用来形容一个人的想法坚定。"}, {"text": "孩子们喜欢玩一种制度。", "explanation": "这里应该用〈游戏〉。“制度”不是可以玩的东西，孩子们玩的应该说“游戏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要吃掉学校的制度。", "corrected_sentence": "我们要遵守学校的制度。", "error_description": "“制度”不能被“吃”，应搭配动词“遵守”，说“遵守学校的制度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医院有一支完善的管理制度。", "corrected_sentence": "医院有一套完善的管理制度。", "error_description": "“制度”不能用量词“支”。“支”多用于队伍、军队，应说“一套完善的管理制度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20942, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻挠", "is_correct": true, "explanation": "反义：“促成”是出力帮忙使事情成功，“阻挠”是从中设置障碍使事情不能成功，二者意思相反。"}, {"text": "收藏", "is_correct": false, "explanation": "与“促成”不构成反义关系，“收藏”指把东西保存起来。"}, {"text": "洗涤", "is_correct": false, "explanation": "与“促成”不构成反义关系，“洗涤”指用水清除污垢。"}, {"text": "翻译", "is_correct": false, "explanation": "与“促成”不构成反义关系，“翻译”指把一种语言转换成另一种语言。"}], "correct_answer": "阻挠", "explanations": {"阻挠": "反义：“促成”是出力帮忙使事情成功，“阻挠”是从中设置障碍使事情不能成功，二者意思相反。", "收藏": "与“促成”不构成反义关系，“收藏”指把东西保存起来。", "洗涤": "与“促成”不构成反义关系，“洗涤”指用水清除污垢。", "翻译": "与“促成”不构成反义关系，“翻译”指把一种语言转换成另一种语言。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20942, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻挠", "is_correct": true, "explanation": "反义：“促成”是帮助事情成功，“阻挠”是设置障碍使事情不成，二者意思相反。"}, {"text": "观察", "is_correct": false, "explanation": "与“促成”不构成反义关系，“观察”指仔细看以了解情况。"}, {"text": "修补", "is_correct": false, "explanation": "与“促成”不构成反义关系，“修补”指修理破损的东西。"}, {"text": "包装", "is_correct": false, "explanation": "与“促成”不构成反义关系，“包装”指用纸或盒子把东西裹起来。"}], "correct_answer": "阻挠", "explanations": {"阻挠": "反义：“促成”是帮助事情成功，“阻挠”是设置障碍使事情不成，二者意思相反。", "观察": "与“促成”不构成反义关系，“观察”指仔细看以了解情况。", "修补": "与“促成”不构成反义关系，“修补”指修理破损的东西。", "包装": "与“促成”不构成反义关系，“包装”指用纸或盒子把东西裹起来。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20942, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一件事成功发生。", "primary_collocate": null, "pronunciation": "cù chéng", "ipa": "tsʰu˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小李帮忙促成了我们的约会。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你促成这件事。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直想促成这次旅行。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈促成了哥哥和老师的见面。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是邻居促成了这门亲事。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的话促成了我们的和好。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想促成他们俩和好。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机会是朋友促成的。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起促成了这次聚会。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想办法促成了这笔买卖。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "促成了", "label": "体标"}, {"form": "促成过", "label": "体标"}], "register": "书面", "sense_fingerprint": "出力帮忙，让某件事顺利成功", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77bd49ee-81b2-46c0-a146-5020ea436bdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20942, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咬", "is_correct": false, "explanation": "语义：“咬”不能带“约会”作宾语，句意荒谬。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”不能与“约会”搭配，无法表示帮忙使事情成功。"}, {"text": "促成", "is_correct": true, "explanation": "正确：“促成”指出力帮忙让事情成功，与“帮忙”及“约会”搭配，句意通顺。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能带“约会”作宾语，表达不出帮忙促成的意思。"}], "explanations": {"咬": "语义：“咬”不能带“约会”作宾语，句意荒谬。", "擦": "搭配：“擦”不能与“约会”搭配，无法表示帮忙使事情成功。", "促成": "正确：“促成”指出力帮忙让事情成功，与“帮忙”及“约会”搭配，句意通顺。", "洗": "搭配：“洗”不能带“约会”作宾语，表达不出帮忙促成的意思。"}, "sentence_index": 0, "correct_answer": "促成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想促成这把椅子。", "explanation": "这里应该用〈搬走〉。促成的对象是事情或结果，不能是具体的椅子。"}, {"text": "我想促成那只猫。", "explanation": "这里应该用〈养〉。促成的对象是事情或结果，「那只猫」是动物，不能作促成的对象；应说「我想养那只猫」。"}, {"text": "他想促成那瓶水。", "explanation": "这里应该用〈喝〉。促成的对象是事情或结果，「那瓶水」是具体的东西，不能作促成的对象；应说「他想喝那瓶水」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20942, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拆", "is_correct": false, "explanation": "语义：“拆”是拆开的意思，不能使人和好，“拆他们俩和好”句意矛盾。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”不能表示促使人和好，句意荒谬。"}, {"text": "促成", "is_correct": true, "explanation": "正确：“促成”指推动事情达成，与“想”及“他们俩和好”搭配，句意通顺。"}, {"text": "尝", "is_correct": false, "explanation": "搭配：“尝”不能带“他们俩和好”这样的小句作宾语。"}], "explanations": {"拆": "语义：“拆”是拆开的意思，不能使人和好，“拆他们俩和好”句意矛盾。", "烤": "语义：“烤”不能表示促使人和好，句意荒谬。", "促成": "正确：“促成”指推动事情达成，与“想”及“他们俩和好”搭配，句意通顺。", "尝": "搭配：“尝”不能带“他们俩和好”这样的小句作宾语。"}, "sentence_index": 6, "correct_answer": "促成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们希望促成那棵树。", "explanation": "这里应该用〈种〉。促成的对象是事情或结果，「那棵树」是具体的东西，不能作促成的对象；应说「我们希望种那棵树」。"}, {"text": "他想促成那声叹息。", "explanation": "这里应该用〈听到〉。促成的对象是事情或结果，“那声叹息”是声音，不能用“促成”，应说“听到”。"}, {"text": "他想促成那位老人。", "explanation": "这里应该用〈照顾〉。促成的对象是事情或结果，不能直接用于人，想照顾老人应说“照顾”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们俩促成着这次旅行。", "corrected_sentence": "他们俩促成了这次旅行。", "error_description": "错误：促成着。正确：促成了。「促成」表示让事情成功，是有结果的动作，不能用「着」表示持续，应该用「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师促成着那次见面。", "corrected_sentence": "这位老师促成了那次见面。", "error_description": "“着”用错：“促成”表示事情已经达成，完成时应用“了”，不能用“着”表示持续。错误：促成着。正确：促成了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
