INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20948, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西你中有我，我中有你，分不开。", "primary_collocate": null, "pronunciation": "xiāng hù jiāo zhī", "ipa": "ɕi̯ɑŋ˥ xu˥˩ tɕi̯ɑʊ˥ ʈʂɻ̩˥", "syllable_count": 4, "sentences": [{"text": "老树的根在地下相互交织。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶上的电线相互交织，像一张网。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的草和花相互交织着。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的马路相互交织，像一张大网。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竹子的根相互交织，把土抓得很紧。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毛线相互交织，织成了一件毛衣。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里，树枝相互交织，挡住了阳光。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的藤蔓相互交织，爬满了墙。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔网上的线相互交织，非常结实。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两棵老树的枝叶在山下相互交织。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相互交织着", "label": "体标"}], "register": "书面", "sense_fingerprint": "具体的东西你中有我、我中有你、分不开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c87be3b-a562-4471-8594-119adfda2aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相互交织", "is_correct": true, "explanation": "正确：老树的根在地下互相缠绕，符合具体事物缠绕的义项。"}, {"text": "相互飞翔", "is_correct": false, "explanation": "语义：根在地下不能飞翔，与“在地下”的语境矛盾。"}, {"text": "相互对视", "is_correct": false, "explanation": "配价：“对视”的主体须是有眼睛的生物，树根不能对视。"}, {"text": "相互唱和", "is_correct": false, "explanation": "配价：“唱和”需要能歌唱的主体，树根不能唱和。"}], "explanations": {"相互交织": "正确：老树的根在地下互相缠绕，符合具体事物缠绕的义项。", "相互飞翔": "语义：根在地下不能飞翔，与“在地下”的语境矛盾。", "相互对视": "配价：“对视”的主体须是有眼睛的生物，树根不能对视。", "相互唱和": "配价：“唱和”需要能歌唱的主体，树根不能唱和。"}, "sentence_index": 0, "correct_answer": "相互交织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两位朋友在街上相互交织，各走各的。", "explanation": "这里应该用〈分开〉。各走各的是分开，“相互交织”表示东西你中有我、分不开，不能用于分开。"}, {"text": "两张照片在桌上相互交织。", "explanation": "这里应该用〈重叠〉。两物部分盖在一起要用重叠，“相互交织”强调缠绕穿插。"}, {"text": "他把一杯水和一杯牛奶相互交织在一起喝了。", "explanation": "这里应该用〈混合〉。液体倒在一起要说混合，“相互交织”指线条、枝条等穿插缠绕在一起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相互交织", "is_correct": true, "explanation": "正确：树枝互相缠绕，才能挡住阳光。"}, {"text": "相互远离", "is_correct": false, "explanation": "语义：树枝相互远离就不会挡住阳光，与“挡住了阳光”矛盾。"}, {"text": "相互照耀", "is_correct": false, "explanation": "语义：“照耀”指发光，树枝不会发光，与“挡住了阳光”矛盾。"}, {"text": "相互问候", "is_correct": false, "explanation": "配价：“问候”的主体须是人，树枝不能问候。"}], "explanations": {"相互交织": "正确：树枝互相缠绕，才能挡住阳光。", "相互远离": "语义：树枝相互远离就不会挡住阳光，与“挡住了阳光”矛盾。", "相互照耀": "语义：“照耀”指发光，树枝不会发光，与“挡住了阳光”矛盾。", "相互问候": "配价：“问候”的主体须是人，树枝不能问候。"}, "sentence_index": 6, "correct_answer": "相互交织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两支军队在河边相互交织，互相攻击。", "explanation": "这里应该用〈对抗〉。互相攻击是对抗，“相互交织”表示东西分不开，不表示敌对。"}, {"text": "两个孩子在院子里相互交织，互相追跑。", "explanation": "这里应该用〈追逐〉。互相追跑是追逐，“相互交织”表示缠绕在一起，不表示追逐。"}, {"text": "两位同事在办公室里相互交织，聊了一下午。", "explanation": "这里应该用〈交谈〉。聊天要说交谈，“相互交织”指东西缠绕在一起，不用于人的交谈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两根铁丝在墙角被相互交织着。", "corrected_sentence": "两根铁丝在墙角相互交织着。", "error_description": "被字句误用：“相互交织”是不及物动词，不能用在“被”字句中，应去掉“被”，说“相互交织着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "藤蔓在墙上相互交织的很密。", "corrected_sentence": "藤蔓在墙上相互交织得很密。", "error_description": "错误在于补语标记。表示动作程度的补语要用结构助词“得”，写成“的”是常见错误。正确形式是“相互交织得很密”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20950, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻止", "is_correct": true, "explanation": "“阻止”表示使事情无法前进，与“推动”（使事情前进）的意思相对，是反义词。"}, {"text": "欣赏", "is_correct": false, "explanation": "“欣赏”表示喜爱、称赞，与“推动”没有反义关系。"}, {"text": "收藏", "is_correct": false, "explanation": "“收藏”表示保存起来，与“推动”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”表示仔细看，与“推动”没有反义关系。"}], "correct_answer": "阻止", "explanations": {"阻止": "“阻止”表示使事情无法前进，与“推动”（使事情前进）的意思相对，是反义词。", "欣赏": "“欣赏”表示喜爱、称赞，与“推动”没有反义关系。", "收藏": "“收藏”表示保存起来，与“推动”没有反义关系。", "观察": "“观察”表示仔细看，与“推动”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20950, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻止", "is_correct": true, "explanation": "“阻止”表示使事情无法前进，与“推动”（使事情前进）的意思相对，是反义词。"}, {"text": "购买", "is_correct": false, "explanation": "“购买”表示付钱取得东西，与“推动”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”表示用脑子想问题，与“推动”没有反义关系。"}, {"text": "写作", "is_correct": false, "explanation": "“写作”表示写文章，与“推动”没有反义关系。"}], "correct_answer": "阻止", "explanations": {"阻止": "“阻止”表示使事情无法前进，与“推动”（使事情前进）的意思相对，是反义词。", "购买": "“购买”表示付钱取得东西，与“推动”没有反义关系。", "思考": "“思考”表示用脑子想问题，与“推动”没有反义关系。", "写作": "“写作”表示写文章，与“推动”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20950, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西动起来或让事情向前走。", "primary_collocate": null, "pronunciation": "tuī dòng", "ipa": "tʰuei˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "风推动了河上的小船。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力推动了那辆旧车。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新技术推动了经济发展。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话推动我努力学习。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水可以推动大轮子转起来。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起推动这个计划。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友推动我完成了这件事。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想推动环境保护。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛推动了城市的发展。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮忙推动一下这张桌子。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推动了", "label": "体标"}, {"form": "推动着", "label": "体标"}, {"form": "推动过", "label": "体标"}, {"form": "推动力", "label": "复合"}], "register": "中性", "sense_fingerprint": "用力使物体移动或使事情进展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bacc239c-df87-4c0c-a87d-ec7f9978f1b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20950, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推动", "is_correct": true, "explanation": "“推动”表示使小船移动，符合“风……了河上的小船”的句意。"}, {"text": "修理", "is_correct": false, "explanation": "语义：风不能修理小船，句意不通。"}, {"text": "卖", "is_correct": false, "explanation": "语义：风不能卖东西，句意不通。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的动作主体一般是人，不说“风驾驶小船”。"}], "explanations": {"推动": "“推动”表示使小船移动，符合“风……了河上的小船”的句意。", "修理": "语义：风不能修理小船，句意不通。", "卖": "语义：风不能卖东西，句意不通。", "驾驶": "搭配：“驾驶”的动作主体一般是人，不说“风驾驶小船”。"}, "sentence_index": 0, "correct_answer": "推动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我推动他明天会来。", "explanation": "这里应该用〈推断〉。“推动”表示促使事情前进，不能表示根据已知情况作出判断。"}, {"text": "会议推动了一天。", "explanation": "这里应该用〈推迟〉。“推动”表示使事情前进，不能表示把时间往后延。"}, {"text": "他推动了老师的邀请。", "explanation": "这里应该用〈推辞〉。“推动”不能表示拒绝别人的邀请。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
